window.__BIRINCI_STORIES__ = {"site_title":"Үлгүлүү сөздөр жана аңгемелер","lang":"ky","categories":[{"title":"Иман жана руханият","slug":"iman-ve-meneviyyat","blurb":"Ишеним, сыйынуу жана ички жол изденүү жөнүндө аңгемелер.","count":36,"stories":[{"stem":"light-of-the-universe","title":"Ааламдын жарыгы","paragraphs":["Британиялык сүрөтчү Уильям Холман Ханттын «Ааламдын жарыгы» аттуу чыгармасы Лондондогу Королдук академияда көргөзмөгө коюлат. Сүрөттө түн ичинде бир колуна чырак кармап, эшиктин алдында турган ойчул кейиптеги адам тартылган. Ал экинчи колу менен эшикти каккылап, ачылат деген үмүт менен күтүп турат.","Сүрөттү изилдеген бир искусство таануучу Хантка кайрылып: «Сүрөт сонун экен, бирок маанисин түшүнө албай жатам. Бул адам каккылаган эшик эч качан ачылбайбы? Балким, эшиктин туткасын чийүүнү унутуп калгансыз?» — деп сурайт.","Хант жылмайып жооп берет: «Бул кадимки эшик эмес. Ал адамдын жүрөгүнүн эшиги. Эшик ичтен гана ачылгандыктан, сыртында туткасы жок. Ал эшик сизге ичтен ачылмайынча, кире албайсыз».","Сабак: Жүрөктүн эшиги ичтен гана ачылат. Сүйүү менен жакшылык күч менен кирбейт — аларды ичке өзүң киргизишиң керек.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"lawful-morsel","title":"Адал тилке","paragraphs":["Ун жаңы, суу таптаза болгону менен, ачыткы бузук болсо, камыр жакшы көтөрүлбөйт; андай камырдан да жакшы нан чыкпайт.","Мүнөзү таза бала өстүрүү үчүн аны адал тилке менен багуу керек.","— Имам Газали","Сабак: Баланын адеп-ахлактык тарбиясы дасторконго коюлган тилкеден башталат. Адал эмгек менен таза ырыскы — соо адептин негизи.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"hajj-pilgrimage","title":"Ажылык сапар","paragraphs":["Ажылыкка барган бир адам шайтанга таш ыргыта турган маал келгенде, ташты ыргыткандын ордуна аны менен өзүн ура баштайт. Жанындагылардан бир жигит таң калып: «Байке, эмнеге өзүңүздү таш менен уруп жатасыз?» — деп сурайт. Ал киши: «Уулум, айтчы, биздин бул жердеги шайтан менен эмне ишибиз бар? Адегенде өзүбүздүн ичибиздеги шайтанды таш бараңга алып, напсибизди тарбиялап, өзүбүздү тазалашыбыз керек», — деп жооп берет.","* * *","Ысык отто, темир табада эмес,","касиет башта, кийген таажыда эмес.","Эмнени издесең да, өзүңдөн изде,","Кудста, Меккеде же ажыда эмес.","Сабак: Чыныгы күрөш сырттагы шайтан менен эмес, адамдын өз напси менен. Касиет ташта да, таажыда да эмес — адамдын өз ичинде. ","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"power-of-truth","title":"Акыйкаттын кудурети","paragraphs":["Акыйкаттын кылычы да ийилбейт, билеги да бүгүлбөйт.","Сабак: Акыйкат ийилбейт, ага күч жетпейт. Убакыт өтөт, бийлик алмашат, акыры акыйкат кайра өз ордун табат.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"my-alif-has-been-dotted","title":"Алифим чекиттелди","paragraphs":["Түркия түркчөсүндө «elifim noktalandı» деген сөз айкашы бар. Бул сөз айкашы эски Осмон жазуусунда «алиф» (ا) тамгасы менен «хе» (ه) тамгасынын жанаша жазылышынан (اه) келип чыккан. «Алифтен» кийин келген «хе» формасы жагынан чекитти элестеткендиктен, «алифим чекиттелди» деп айтылат; ал өтмө мааниде «кубанычым кайгыга айланды» дегенди билдирет. Анткени узун жана ичке көрүнгөн «алиф» тамгасы эркиндик менен сулуулукту, ал эми ийилип, эзилип калгандай көрүнгөн «хе» тамгасы кысым менен чөгүүнү туюнтат.","Бул эки тамга бириккенде «ах» деген зар үнү жаралат.","Сабак: Кээде бир тамганын, бир көз ирмемдин өзгөрүшү кубанычты кайгыга айлантат. Тилибиздеги ар бир айтылыш бир сезимдин, бир окуянын изин алып жүрөт.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"blessings-god-has-given","title":"Аллах берген жакшылыктар","paragraphs":["Аллах кимге жакшылык берсе, аны кантип пайдаланганын да карайт:","Бийлик берилсе — адилеттүү болдубу?","Жогорку даража берилсе — боорукер болдубу?","Байлык берилсе — ахлагын сактадыбы?","Тынч жашоо берилсе — шүгүр кылдыбы?","Өмүрлүк жар берилсе — ага ишенимдүү болдубу?","Бала берилсе — аны кандай тарбиялады?","Сабак: Ар бир жакшылык сыноо да. Сенин ким экениңди ээ болгон нерселериң эмес, аларды кантип пайдаланганың көрсөтөт.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"friend-of-god","title":"Аллахтын досу","paragraphs":["Бир карыя бут кийими жок баланы көрүп, боору ооруйт да, ага бир жуп бут кийим сатып берет.","Бала бут кийимди колуна алып, бир топко чейин карап турат. Анан башын көтөрүп сурайт:","— Сиз Аллахсызбы?","Карыянын колдору титиреп, көзүнө жаш толот:","— Жок, балам, мен жөнөкөй эле адаммын.","Бала бир аз ойлонуп туруп, акырын айтат:","— Анда сиз Аллахтын досусуз. Мен бүгүн түнү ыйлап жатып, Аллахка бут кийимим жок экенин айткан элем.","Сабак: Кээде Аллахтын жардамы жакшы адамдардын колу аркылуу келет. Бирөөнүн тилегине жооп болуу сенин колуңдан да келиши мүмкүн.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"gods-pleasure","title":"Аллахтын ыраазылыгы","paragraphs":["Кожо Убайдуллах Ахрар мындай дейт:","«Аллахтын ыраазылыгына алып барган бардык жолдорду изилдеп көрдүм. Алардын эң кыскасы — адамдарга кубаныч тартуулоо экенин түшүндүм.","Адамды Аллахтын ыраазылыгынан алыстаткан бардык жолдорду да изилдеп көрдүм. Алардын эң коркунучтуусу — бирөөнүн жүрөгүн сындыруу экенин түшүндүм».","Сабак: Аллахтын ыраазылыгына жетүүнүн эң кыска жолу — адамдарды кубантуу. Жүрөк сындыруу болсо адамды Анын ыраазылыгынан алыстатат.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"forbidden-money","title":"Арам акча","paragraphs":["Бир күнү жолдо баратып, алдымда кетип бараткан адамдын колунан бир топ акча түшүп калганын көрдүм. Адатта мындайда «Акчаңызды түшүрүп алдыңыз» деп эскертчүмүн, бирок бул жолу шайтанга азгырылып, акчаны жерден алып чөнтөгүмө салдым.","Үйгө келгенде болгон окуяны аялыма айтып бердим.","— Үстүнө бир аз кошуп, киного барып келели, — деди. Мен: «Макул», — дедим. Дем алышта киного барууну чечтик.","Аялым болбой туруп алды: «Азыр убада берип жатасың, кийин капысынан баш тартып жүрбө; эң жакшысы, билеттерди азыр эле интернеттен сатып ал, көңүлүбүз тынч болсун». Мен: «Макул», — деп, билеттерди интернет аркылуу сатып алдым.","Өзүм оңдоочу устамын. Акчалуу кардарларымдын бири телефон чалып: «Ишембиде багыма кел, бир аз жумуш бар», — деди. «Жекшембиде барсам болобу?» — деп сурадым, бирок кардарым: «Жок, мүмкүн эмес», — деди. Кино билеттерин да кырсык чалгансып ишембиге алып коюптурбуз, ошентип бул жактан да кыйла зыян тарттым.","Ошентип, ишемби да келди. Аялым экөөбүз үйдөн чыгууга камынып жатканда, эшиктин алдынан кайын энем менен кайын атам капысынан чыга калышты.","«Киного баратабыз» деп жолубузду улантайын дегиче, аялым менден озунуп: «Киного баратабыз, жүрүңүздөр, сиздер да биз менен барыңыздар», — дегенде, айлам канчалык куруп турганын түшүндүм.","Кайын энем коомдук транспортту жактырбагандыктан, кинотеатрга такси менен барууга туура келди. Таксинин акчасы да, албетте, менден.","Кинотеатрга жеттик. Дагы эки билет сатып алдым. Анын үстүнө, кино башталардан мурда ар бирине бир кутудан попкорн алып берүүгө туура келди — башкача болбойт да, көчөдөн акча таап алган соң күйөө бала баарын сыйлашы керек! Ошол попкорндорго кеткендей акчаны курмандыкка эт алганда да короткон эмесмин. Кутуларды бат эле бошотуп койгонубуздан, фильм жүрүп жатканда чыгып, дагы сатып келүүгө аргасыз болдум. Кыскасы, таап алган акчам өзүмө кымбатка турду, бирок жазам муну менен бүтпөптүр. Көрөр күнүбүз дагы алдыда экен.","Акыры кино бүтүп, көчөгө чыктык. Чыкканыбыз курусун! Эски тааныштарымдын бирине жолугуп калдым. Мурунтан кастыгыбыз бар эле, кайын атам менен кайын энем жанымда турганына карабай, ал мага бир-эки ачуу сөз айтты. Чыдай албадым. Мушташ чыгып кетти. Мушташ болгондо да тим эле укмуш! Мен аны, ал мени — сабашып эле жатып калдык. Кайын атам да аралашты. Кыскасы, полиция келгенче менин мурдум, кайын атамдын колу сынып бүттү. Полиция бөлүмүндө чатакты тынчтык менен бүтүргөнүбүз менен, алган жаракаттарыбыздан улам өзүмдүн да, кайын атамдын да оорукана чыгымын төлөө менин мойнума түштү.","Жакында дагы жолдо бара жаттым. Алдымда бирөө дөнөр сатып алып жатыптыр. Сатуучу акчанын кайтарымын бергенде, тыйындар жерге түшүп кетти. Ал киши эңкейип, аларды көтөрүп койгон жок. Чыдабай: «Эй, бир тууган, өзүңдү ойлобосоң да, бул акчаны таап ала турган адамды ойлочу; элдин башына балээ үйбө, суранам, тиги акчаны жерден алып кой», — дедим.","Сабак: Мандай тери менен табылбаган акча пайда бербейт; көбүнчө тапканыңдан бир нече эсе көптү жоготосуң. Арамга кол сунба.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"if-fate-allows-we-will-meet","image":"wisdom-stories/Bakhtiyar%20Sirajov/illustrations/if-fate-allows-we-will-meet.webp","title":"Кысмет болсо, көрүшөбүз","paragraphs":["Дайыма «көрүшөбүз» деген адам эми «кысмет болсо, көрүшөбүз» деп калды. Мында бир бөтөнчүлүк бар. Мен өзгөргөн жокмун, ага болгон мамилем да мурдагыдай жылуу. Аны менен дагы эле чоң кубанычта жолугушкум келет. Бирок бул «кысмет болсо» деген сөз ортобузга тосмо болуп калгандай. Мен анын тагдырын билбейм, ал да меникин билбейт. Кызык, ушул эки тагдыр бири-биринен кабардар бекен, өз ара макулдашып, бизди жолуктура алар бекен?","Балким, тагдырдан эч нерсе күтпөө керек чыгар; бул болгону «көздөн далдаа — көңүлдөн оолак» деген сөздүн өзүдүр?","Бул «кысмет болсо» деген сөз мага такыр жаккан жок.","Сабак: Жакының менен ортоңго суукчулук киргизбе. «Кысмет болсо» деп кийинкиге калтырба. Бүгүн жолугуп, бүгүн көңүлүн ал.","Бахтияр Сиражов"],"hasAudio":false,"hasImage":true},{"stem":"dervishs-spoons","title":"Дербиштин кашыктары","paragraphs":["Бир күнү дербиштен сурашты:","— Чындап сүйгөндөр менен сүйүү тууралуу сөз гана кылгандардын айырмасы эмнеде?","— Күтүп тургула, азыр силерге көрсөтөм, — деди дербиш.","Ал сүйүүнү ооз учунда гана айткан бир нече адамды чакырып, аларга дасторкон жайды. Коноктор орун алгандан кийин дасторконго ысык шорпо, андан соң «дербиш кашыктары» деп аталган адаттан тыш узун кашыктар коюлду. Дербиш шартын айтты:","— Шорпону ушул кашыктардын учунан кармап жейсиңер.","Алар макул болушту. Бирок кашыктар ушунчалык узун болгондуктан, шорпону оозго жеткирүү мүмкүн эмес эле: ар бир аракетте шорпо үстүлөрүнө төгүлүп, денелерин күйгүзүп жатты. Акыры ачка бойдон, уят болуп дасторкондон тарашты.","Андан кийин дербиш чыныгы сүйүү эмне экенин билген адамдарды чакырды. Жүздөрү нурдуу, көздөрү сүйүүгө толгон адамдар келип, дасторконго отурушту. Дербиш аларга да ошол эле шартты айтты. Бул жолу көрүнүш таптакыр башка болду: ар ким кашыгын толтуруп, маңдайындагы адамга сунду, бири-бирин тамактандырышты. Дасторкон шаңга бөлөнүп, баары тоюп, шүгүр айтып ордунан турдулар.","Коноктор тарагандан кийин дербиш суроо бергендерге кайрылды:","— Көрдүңөрбү? Жашоо дасторконунда өзүн гана көргөн адам ач калат. Бир тууганын, досун ойлоп, ага кол сунган адам өзү да тоёт. Жашоо базарында дайыма алган эмес, берген адам утат.","Сабак: Өзүн гана ойлогон адам ач калат. Башканы тойгузган өзү да тоёт. Берген адам дайыма утат.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"dervishs-clothes","title":"Дербиштин кийим-кечеси","paragraphs":["Дербиштен сурашты:","— Кийим-кечең эмнеге мынчалык тыкан эмес?","Дербиш жооп берди:","— Дайыма ички дүйнөмдү кооздоо менен алек болгондуктан, сырткы көрүнүшүмдү түзөөгө убактым жетпейт.","Сабак: Ички дүйнөсүн кооздогон адам сырткы кемчиликти өлчөм кылбайт. Адамды кооз кылган кийими эмес, жүрөгүнүн тазалыгы жана рухунун жарыгы.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"dervishs-robe","title":"Дербиштин чапаны","paragraphs":["Бир күнү канаты жараланган куш падышанын алдына келип, бир дербиш анын канатын сындырып койгонуна даттанат. Падыша дербишти дароо чакыртат.","— Бул куш сенин үстүңдөн арызданууда. Эмне үчүн анын канатын сындырдың? — деп сурайт.","Дербиш өзүн актоого аракет кылат:","— Падышам, мен бул кушту аңчылык кылгым келди. Жакындасам, качкан жок. Үстүнө бара берсем да, ордунан козголбоду. Мага багынды окшойт деп, кармайын дегенде качууга аракет кылды — ошондо канаты сынып калды.","Падыша кушту карап:","— Бул киши туура айтып жатат. Сен эмнеге качкан жоксуң? Ал сага капыстан кол салган эмес. Жакындап келатканын көрүп, өз убагында учуп кетсең болмок. Эми болсо мага келип арызданып турасың, — дейт.","Куш өзүнүн туура экенин далилдөөгө аракет кылат:","— Падышам, мен аны дербиштин кейпинде көргөнүм үчүн качкан жокмун. Мергенчи болгондо, дароо учуп кетмекмин. Бирок «дербиштен зыян келбейт, алар Кудайдан коркот» деп ойлодум.","Падыша бир азга унчукпай калып, анан буйрук берет:","— Куштуку туура. Дербиштин колун сындыргыла!","Куш дароо каршы чыгат:","— Суранам, андай кылбаңыз!","— Эмне үчүн? — деп сурайт падыша.","— Колун сындырсаңыз, айыккандан кийин кайра эле ушундай кылат. Андан көрө үстүндөгү дербиштин чапанын чечтирип салыңыз, мага окшогон куштар экинчи алданбасын.","Сабак: Ыйык көрүнүү адамды ыйык кылбайт. Чапан кийгендин баары эле дербиш эмес. Адамдын ким экенин сырткы кейпинен эмес, кылган ишинен тааны.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"let-prayer-come-and-find-you","title":"Ак бата өзү сени тапсын","paragraphs":["Аксакалдарыбыз мындай деп айтышкан: сен —","жардыга таяныч, муктажга ачык эшик, жетимдин башын сылаган кол бол. Баланын бутундагы бут кийим бол. Кыйналганга жол ач, иши оорлоп кеткенге жардам бер. Ошондо өзүңө керектүү ак бата сени издеп табат.","Сабак: Муктажга кол сунган, жетимдин башын сылаган адам өзү да дубага татыктуу болот. Жакшылык кылган колуң бир күнү сага да ачылат.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"pray-while-washing-your-dishes","title":"Идиш-аягыңызды жууп жатып дуба кылыңыз","paragraphs":["Идиш-аягыңызды жууп жатып дуба кылыңыз. Жуучу идишиңиз бар экенине шүгүр айтыңыз. Анткени бул жей турган тамагыңыз болгонун, бирөөнү тойгузганыңызды, кимдир бирөөгө кам көргөнүңүздү, тамак жасап, дасторкон жайганыңызды билдирет.","Ошол учурда жууй турган бир да идиши жок, дасторкон жая турган эч кими жок адамдарды ойлонуңуз.","Сабак: Күнүмдүк тиричиликтин өзүнөн да шүгүр кылчу нерсе тап. Жууй турган идишиң — дасторконуңа тамак келип, бирөөнү тойгузганыңдын белгиси. Шүгүр кылууну унутпа.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"faith-is-half-of-success","title":"Ишеним — ийгиликтин жарымы","paragraphs":["Бир мектептин директору бир нече мугалим кесиптешин бөлмөсүнө чакырып, аларга мындай дейт:","— Силер биздин эң мыкты, эң жөндөмдүү мугалимдерибиз болгондуктан, тандалып алынган эң зээндүү, жөндөмдүү окуучулардын тобун силерге тапшырабыз. Милдетиңер — кийинки бир жылдын ичинде аларга мыкты билим берип, дагы да жогорку деңгээлге чыгаруу. Ийгилик каалайм.","Мугалимдер да, окуучулар да, ата-энелер да бул демилгени эң сонун идея деп эсептеп, окуу жылынын аякташын чыдамсыздык менен күтүштү.","Акыры окуу жылы бүттү. Өткөрүлгөн сынактардан кийин ал окуучулар шаардагы башка мектеп окуучуларына салыштырмалуу кыйла жогорку натыйжа көрсөткөнү белгилүү болду.","Директор мугалимдерди куттуктап, мындай деди: «Мен бир нерсени мойнума алышым керек. Силерге тапшырылган окуучулар эң жөндөмдүү балдар эмес эле — алар орточо деңгээлдеги окуучулар болчу. Биз аларды туш келди тандаганбыз».","Муну уккан мугалимдер сыймыктанып, окуучулардын ийгилигин өздөрүнүн кесипкөйлүгүнүн натыйжасы деп эсептей башташты.","Директор сөзүн улантты: «Дагы бир нерсени моюнга алайын. Силер да эң жөндөмдүү мугалимдер эмес элеңер! Аты-жөнүңөр жазылган кагаздарды баштыкка салып, арасынан туш келди тандап алгам. Силер ишенгениңер үчүн ийгиликке жеттиңер».","Сабак: Ишеним адамдын ичиндеги күчтү ачат. Андан жакшы натыйжа күтүү кээде ошол натыйжага алып баруучу алгачкы кадам болот.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"idle-devil","title":"Ишсиз шайтан","paragraphs":["Бир дербиш ойго батып отуруп, капысынан жанындагы шайтанды көрүп калат. «Эмнеге мынчалык тынч отурасың, эч кимге зыян келтирбейсиң?» — деп андан сурайт.","Шайтан чарчаңкы башын көтөрүп: «Силер, адамдар, бири-бириңерге ушунчалык көп зыян келтирип, ушунчалык азап чектиресиңер — мага кылар иш калдыбы деги?»","Сабак: Адамдар бири-бирине ушунчалык зулум кылгандыктан, шайтанга иш калбайт. Жамандыктын көбү сырттан эмес, өз ичибизден чыгат.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"price-of-a-miracle","title":"Кереметтин баасы","paragraphs":["(Чыныгы окуя)","Ата-энеси анын кичинекей иниси Оливер тууралуу сүйлөшүп жатканын укканда, Лиза сегиз жашта эле. Кыздын билгени бир гана нерсе болчу: иниси өтө катуу ооруп жаткан, ал эми ата-энесинин аны дарылатууга акчасы жок эле.","Оливерди өтө кымбат операция гана сактап кала алмак. Аларга карыз бере турган эч ким да жок болчу. Лиза атасынын көзүнө жаш алган апасына акырын, айласы кеткен үн менен: «Эми аны керемет гана сактап кала алат», — дегенин укту.","Кыз бөлмөсүнө кирип, шкафтын жашыруун жеринде сактаган айнек идишин алды. Ичиндеги акчанын баарын жерге төгүп, кунт коюп санады — атүгүл бир нече жолу кайра санады. Санап бүткөндөн кийин тыйындарды этияттап идишке салып, капкагын жапты да, арткы эшиктен чыгып, дарыканага жөнөдү.","Дарыканага жетери менен ичкери кирип, дарыканачынын ага көңүл бурушун чыдамдуулук менен күттү. Дарыканачынын колу бош эмес, сүйлөшүүгө берилип кеткен эле. Лиза ар кандай кыймылдап, үн чыгарып анын көңүлүн бурдурууга аракет кылса да, ал жооп берген жок. Акыры кыз идиштеги акчанын бир бөлүгүн алып, айнек текчеге чаап жиберди. Дарыканачы селт этти:","— Кызым, сага эмне керек? — деп кыжырдана сурады да, жообун күтпөй кошумчалады: — Мен азыр көптөн бери көрө элек бир тууганым менен сүйлөшүп жатам.","— Мен да сиз менен иним жөнүндө сүйлөшкүм келет, — деп Лиза да ошончолук кыжырдана жооп берди. — Ал ооруп жатат... Аны айыктырыш үчүн мага керемет керек.","— Эмне? Керемет керекпи? — деп дарыканачы ого бетер кыжырданды.","— Анын аты Оливер, мээсинде жаман бир нерсе өсүп жатыптыр. Ата-энем эми аны керемет гана сактап кала алат дешти. Айтыңызчы, бир керемет канча турат?","— Биз бул жерде керемет сатпайбыз, кызым. Кечир, бирок сага жардам бере албайм, — деди дарыканачы бир аз жумшагыраак үн менен.","— Караңызчы, менин акчам бар. Жетпесе, калганын да таап келем. Болгону кереметтин баасын айтыңыз.","Ушул убакка чейин маекти сырттан угуп турган жарашыктуу кийинген адам — дарыканачынын бир тууганы — эңкейип, Лизадан сурады:","— Иниңе кандай керемет керек?","— Билбейм, — деп жооп берди Лиза. — Мен анын чындап ооруп жатканын гана билем. Ата-энем ага операция керек дешет. Алардын операцияга акчасы жок болгондуктан, өз акчамды коротууну чечтим.","— Канча акчаң бар? — деп сурады адам.","— Бир доллар он бир цент, — деп Лиза салмактуу жооп берди. — Бул менин болгон акчам, бирок керек болсо дагы бир аз көбөйтө алам.","— Бир доллар он бир цент... Кандай сонун дал келүү, — деп жылмайды адам. — Бул сенин кичинекей иниңе керек болгон кереметтин так баасы экен.","Ал кыздан акчаны алып, колунан жетелеп:","— Мени үйүңөргө алып бар. Иниңди көрүп, ата-энең менен сүйлөшкүм келет. Карап көрөлү, менде иниңе керек болгон керемет бар бекен, — деди.","Бул жарашыктуу кийинген адам белгилүү нейрохирург, доктор Карлтон Армстронг болчу.","Операция акысыз жасалып, көп өтпөй Оливер кайра үйүнө кайтты. Апасы менен атасынын кубанычында чек жок эле. Апасы атасына акырын: «Бул чыныгы керемет болду. Кызык, операция канчага турмак экен?» — деди.","Лиза жылмайды. Бул кереметтин канчага турганын так билчү: бир доллар он бир цент, дагы инисин сактап кала турган кереметке болгон бекем ишеним.","Сабак: Ишеним зор күч. Кээде баланын таза ишеними адамдын жакшылыгына жолукканда керемет жаралат.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"your-hand-at-work-your-hope-in-god","title":"Колуң иште, үмүтүң Кудайда болсун","paragraphs":["Илгери бир дервиш болуптур. Күндөрүнүн көбүн жалгыздыкка берилип, ибадат кылуу менен өткөрчү экен. Бирок элге көз каранды болууну да жактырчу эмес, ошондуктан күнүнүн бир бөлүгүн ишке арначу: бир аз иштеп, өз кол эмгеги менен тапкан акчасына нан сатып алчу, муктаждыгынан ашканын болсо кедейлерге таратып берчү экен.","Бир күнү ал дагы эле чөлдө ибадат кылып отуруп, бир түлкүнү көрүп калат. Түлкүнүн буттары майып болуп, сойлоп араң жылып жүрүптүр. Дервиш ичинен ойлонот: «Бул түлкү эмне менен күн көрөт болду экен? Жапайы жаныбарлар аң уулоо менен жашайт, аң уулаш үчүн болсо күлүк бут керек. Бул байкуштун буту жок. Кудай мунун ырыскысын кайдан жеткирет болду экен?»","Ушундай ойдо турганда, алыстан бир арстан аңчылыкта кармаган жейренин тиштеп сүйрөп келатканын көрөт. Арстан олжосун жерге коюп, бөлүп жеп, тойгондон кийин калганын ошол жерге таштап кетет. Бир топтон бери далдаа жерде аңдып турган майып түлкү сойлоп келип, эттен жеп курсагын тойгузат.","Дервиш бул окуяга таң калат. Арстан аркылуу түлкүгө ырыскы жеткирген Кудайга алкыш айтат. Анан анын оюна мындай пикир келет: «Бул түлкү эч нерсе кылбай туруп ырыскысын тапса, Алла Таала менин ырыскымды эмнеге жеткирбесин? Ишке сарптаган убактымды ибадатка арнап, көбүрөөк сооп тапсам болот. Мындан ары иштебейм. Майып түлкүнүн азыгын арстан аркылуу жеткирген Кудай менин да ырыскымды жеткирет».","Ошол күндөн тартып дервиш ишти биротоло таштап, күнү-түнү ибадатка берилет. Бирок канча күтсө да, ырыскы келбейт. Эшигин каккан да, бир тилим нан алып келген да болбойт. Дервиш күндөн-күнгө арыктап, сөөгү менен териси эле калат.","Акыры алдан-күчтөн тайган бир күнү кайыптан үн угулат:","— Мен сага соо дене, күчтүү кол, күлүк бут бердим. Сен болсо өзүңдү майып түлкүгө окшоштурдуң. Эмнеге өзүңдү арстанга эмес, түлкүгө теңейсиң? Эмнеге башканын арткан ашына көз артып жатасың? Тур, арстандай эмгектен, ырыскыңды өзүң тап. Колу-буту жоктор сенден үмүт кылсын. Өзүң да же, муктажды да тойгуз.","Дервиш кылган ишинен уялып, тообо кылат да, мурдагы жашоосуна кайтат. Кайрадан өз кол эмгеги менен ырыскы таап, башкаларга жүк болуу оюнан биротоло баш тартат.","Сабак: Күчү бар туруп муктаждын үлүшүнө көз арткан адам Кудайга таянган болбойт — ал жалкоолугун ишеним менен жаап жатат.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"sacrificial-meat","title":"Курмандык эти","paragraphs":["Мектептин 5-классында окучумун. Эч кимге муктаж эмес элек. Куруучу болуп иштеген атам курулуп жаткан бир турак жай кооперативине мүчө болгон. «Алты-жети айдан кийин өз үйүбүзгө көчөбүз» деп кыялданчубуз.","Бир күнү эртең менен катуу силкинүүдөн ойгондук. Жер титирептир. Кудайга шүгүр, бизге да, жакын айланабызга да жамандык болгон жок. Имаратыбыздагы эч ким жабыркаган жок. Бирок үйүбүз да, жаныбыз да аман болгону менен, бул окуя үй-бүлөбүзгө башка мүшкүл алып келди: жер титирөөдөн улам курулуш иштери токтоп, атам жумушсуз калды.","Канчалык үнөмдөөгө аракет кылсак да, атам анда-санда тапкан оңдоо иштеринен түшкөн акча үй-бүлөбүздү багууга жетчү эмес.","Кыш бою атама жумуш табылган жок. Үмүт менен чыгып, көңүлү чөгүп кайтып келчү.","Орозо айтка бир нече күн калган. Атам үйгө сүйүнүп келди — жумуш тааптыр. «Документтериңди даярдап кел», — дешиптир. Кубанычтуу кабарды айтып, чагылгандай үйдөн чыгып кетти. «Бүгүн жетишишим керек», — деди.","Бир нече сааттан кийин каалга кошунабыз шашып кирип келди. Жүзүндө коркунучтуу кебете бар эле.","— Коркпогула, бирок атаңар кичине кырсыкка кабылды, — деди.","Ооруканага жеткенибизде атамдын жүзү кубарып кетиптир. Колу-буту таңылуу болчу. Кызыл жарыкка карабай катуу ылдамдыкта келген машина атамды сүзүп кетиптир. Биз анын тирүү калганына дуба кылып жатсак, атам көзүнөн аккан жашын уяла жашырууга аракеттенип: «Эмнеге тирүү калдым, силерге дагы жүк болдум», — дечү.","Бир аздан кийин атам үйгө чыкты. Мешибиз күйчү эмес, үйүбүз суук эле. Бир нече кошунабыз муниципалитетке телефон чалып, бизге көмүр сурашыптыр. Бирок «болбойт» дешиптир — алдын ала каттоодон өтүш керек экен.","Ошентип, «кантсыз» Орозо айтыбыз да өтүп кетти. Бардык кыйынчылыкка карабай, күн бир аз жылып, атамдын колундагы таңгыч алынган, бирок буту дагы эле таңылуу болчу.","Артынан Курман айт келди. Ичимден: «Үйүбүздө он эки батир бар, көбү курмандык чалат. Кандай болсо да бизге да бир үлүш беришер, апам да мен жакшы көргөн эт тамактардан бышырар», — деп ойлодум. Терезеден карап турсам, маңдайдагы бош жерде малдар союлуп, териси сыйрылып, чара-табак эт үйлөргө ташылып жатты. Ар бир эшик ачылганда үйдө куурулган эттин даамдуу жыты биздин үйгө чейин жетчү. Бирок, тилекке каршы, бизге бир кесим эт алып келген жан болгон жок.","Ошол учурда чоң энем майрамыбыз менен куттукташ үчүн айылдан телефон чалды. Сүйлөшүп жатып, үнүмөн көңүлүм чөгүп турганын байкады. Кайра-кайра санааркап: «Атаңдын абалы начарлап кеттиби?» — деп сурады.","«Жок», — дедим акырын. «Кошуналар бизге курмандык этинен беришкен жок».","Жайкысын айылга, чоң энемдикине барчубуз. Анын бир уйу, беш-алты тоогу бар эле. Уйу сүттүү болчу. Чоң энем аны саап жатып ырдап берчү.","Майрамдын үчүнчү күнү таң эрте эшигибиз кагылды. Келген чоң энем экен. Аны кубанып тосуп алдык. Ал баарыбызды ыйлап кучактады. «Козуларым, ай, козуларым, силерге көп эт алып келдим», — деди.","Муздаткыч этке толду. Эжем дароо эт туурап, тамак камдай баштады. Казандан чыккан жыт эки күндөн бери эт эңсеген табитимди ого бетер ачты. Чыдай албай очоктун жанына келдим. Вилкага бир кесим эт илип, үйлөп оозума салайын дегенде, атамдын чоң энеме айткан сөзү кулагыма шак этти:","— Эх, апа, эх! Ал уйду эмнеге сойдуң?","Жүрөгүм айланып, башым тегеренип кетти. Колумдагы вилканы ыргытып, сыртка чуркап чыктым. Чоң энемдин үмүтү, ырдап жатып сааган ошол уй менин эт жегим келгени үчүн союлдубу?","Дасторкон жайылганда колумдан жетелеп келип отургузушту. Каалабай, уялып вилканы колума алып, эттен бир кесим оозума салдым. Бирок тамагымдан өтпөй, көзүмө жаш тегеренди. «Эмне болду?» — деп сурашты.","— Тишим-м-м!… — дедим. — Тишим аябай ооруп жатат.","Сабак: Майрам баарынын майрамы болгондо гана чыныгы майрам. Өзүбүз толуп жашап турганда, дасторконунда бир кесим эт да жокторду унутпоо — адамдык парзыбыз.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"fortieth-day-rite","title":"Кыркын чыгаруу","paragraphs":["Түрк элдеринде төрөттөн кийин эне менен наристенин кырк күн үйдөн чыкпай, үйүнө конок киргизбей отуруу салты бар. Айтымдарга караганда, бул байыркы түрк салттарынын бири болуп, тамыры Көктүрктөр дооруна чейин жетет.","Мөөнөт бүткөндө наристенин кыркын мындайча чыгарышчу экен: эне-баланы жакын туугандарынын биринин үйүнө конокко чакырышып, үй ээси наристеге өмүр бою кирешеси мол болсун деп майда акча; чачы агарганча узак жашап, жүрөгү жумшак болсун деп пахта; оозу дайыма таттуу, жүзү дайыма күлүп турсун деп кант; үйүнө береке кирсин деп күрүч; оозунун даамы кетпесин деп туз; курсагы ток, дени соо болсун деп жумуртка сыяктуу белектерди беришчү.","Сабак: Салттарыбыздын ар биринде бир бата, бир сүйүү жашырылган. Наристеге берилген белектер чындыгында анын өмүрүнө айтылган жакшы тилектер.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"calamity-and-blessing","title":"Кырсык жана немат","paragraphs":["Кырсык сени Аллахка жакындатса, ал өзү немат.","Эгер немат сени Аллахтан алыстатса, ал өзү кырсык.","Сабак: Сени Аллахка жакындаткан оордук — немат, Андан алыстаткан немат болсо кырсык. Маанилүүсү ыңгайлуу жашоо эмес, кайсы жол менен бара жатканың.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"where-does-calamity-come-from","title":"Кырсык эмнеден келет","paragraphs":["Дервиштен сурашат:","— Кырсык эмнеден келет?","Дервиш айтат:","— Көзүңдү текшерчи: арам нерсеге караган жоксуңбу?","— Тилиң менен кулагыңды текшерчи: ушак айтып, ушакка кулак салган жоксуңбу?","— Колуңду текшерчи: арамга кол сунуп, ырыскыңа арам аралаштырган жоксуңбу?","— Бутуңду текшерчи: барбашың керек болгон жерге барган жоксуңбу?","Сабак: Башыбызга келгендин тамырын көп учурда өз кылгандарыбыздан тапса болот. Көзүңдү, тилиңди, колуңду жана кадамыңды текшер.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"mullah-and-the-scholar","title":"Молдо менен аалым","paragraphs":["Башка өлкөлөрдүн биринен Аксак Темирге бир аалым келет. Котормочу аркылуу көпкө маектешкенден кийин ал бул өлкөнүн аалымдары менен жолугушкусу келерин билдирет. Темир бардык аалымдарды чогултат. Бирок алардын эч кимиси чет элдик аалым менен талашка түшүүгө батынбайт. Акыры алардын мынчалык коркконун көргөн Молдо талашты өз мойнуна алат.","Жыйын курулат. Чет элдик аалым жерге бир тегерек чийип, Молдону карайт. Молдо бир аз ойлонуп, тегеректи экиге бөлөт. Аалым унчукпаганын көрүп, дагы бир сызык тартып, аны төрткө бөлөт да, үч бөлүгүн өзүнө тартып, бир бөлүгүн чет элдик аалымга бергендей ишарат кылат. Аалым макул болот. Анан колун аркасы жерге караган бойдон жумуп кармап, Молдодон жооп күтөт. Молдо болсо тескерисинче, манжаларын жерге каратып жооп берет. Аалым буга да макул болот.","Үчүнчү жолу аалым өзүн көрсөтүп, тамак жеп жаткандай ишарат кылат. Молдо дароо чөнтөгүнөн бир жумуртка чыгарып, колдорун куштун канатындай кагат. Аалым күлүп, Молдонун колун өбөт. Анан Молдо кетет.","Темир котормочу аркылуу аалымдан: «Бул ишараттар менен эмнени айткыңыз келди? Биз эч нерсе түшүнгөн жокпуз», — деп сурайт.","Аалым мындай дейт: «Дүйнө тууралуу пикирлер ар түрдүү. Мен жерге тегерек чийип, Жер шары тоголок экенин айтып, силердин аалымдын бул жөнүндөгү оюн билгим келди. Машаллах, аалымыңар дароо шардын экваторун чийди, анан аны төрткө бөлүп, үч бөлүгү суу, бир бөлүгү кургактык экенин көрсөттү. Андан соң мен андан жер бетиндеги өсүмдүктөрдүн жашоосу тууралуу оюн сурадым. Аалымыңар буга да туура жооп берип, бардык өсүмдүктөр жамгыр менен күн нурунун аркасында жашай турганын айтты».","«Үчүнчү суроомдо адамдар менен жаныбарлар тууралуу оюн билгим келди. Ал болсо дароо жумуртка көрсөтүп, куштар да ушул топко кирерин эсиме салды».","Аалым кеткенден кийин Темир Молдону чакырып, аалым менен болгон суроо-жообун сурайт.","Молдо айтат: «Эх, аалым имиш... Мен да аны чын эле терең адам го деп ойлогом. Көрсө, келесоо, тамаксоонун бири экен... Адегенде жерге тегерек чийип, мага: “Эх, азыр ушул жерде бир таба куурулган жумуртка болсо кана”, — деди. Мен дароо экиге бөлүп: “Баарын сага беришпейт, биз да барбыз”, — дедим. Карасам, таанышым макул болбой жатат. Дароо ортосунан дагы бөлүп, үч үлүшүн өзүмө алып: “Көзүң тойбосо, ушундай болот”, — дедим. Киши жумурткадан куру каларын көрүп, макул болду. Экинчи жолу колун көккө каратып: “Бир казан палоого кандай карайсың?” — деди.","Мен да колумду төмөн каратып: “Үстүндө карасы болсо, жейм”, — дедим. Үчүнчү жолу курсагын көрсөтүп: “Жолдон келдим, ачмын”, — деди. Мен да дароо чөнтөгүмдөн жумуртканы чыгарып: “Жаның үчүн, мен өзүм сенден да ачмын, болгону чөнтөгүмдө жалгыз жумуртка бар. Сурана көрбө, бере албайм”, — дедим».","Сабак: Бир эле ишаратты ар ким өз түшүнүгүнө жараша чечмелейт. Адам каршысындагыны көбүнчө өз оюнун күзгүсүнөн көрөт.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"o-god-give-first-to-the-mountains-and-stones","title":"Оо, Кудайым, адегенде тоо-ташка бер","paragraphs":["Байыркы түрк элдеринде мындай дуба болгон экен:","— Оо, Кудайым, адегенде тоо-ташка, токойго, жаныбарларга, сууга бер. Андан кийин адамдарга, каалгалаш кошунама, муктаждарга бер. Эгер андан артса, эң акырында мага бер!","Сабак: Кең пейил адам өзүнөн мурда өзгөнүн камын ойлойт. Бул дубада элдин ырыскыны бөлүшүп, башкага үлүш бөлүү салты жашайт.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"o-god-heal-our-sorrows","title":"Оо, Кудайым, дарттарыбызга даба бер","paragraphs":["Рахман жана Рахим ысымдарың менен дарттарыбызга даба бер,","Гаффар жана Тавваб ысымдарың менен күнөөлөрүбүздү кечирип, тооболорубузду кабыл ал,","Раззак ысымың менен ырыскыбызга береке бер,","Шафи ысымың менен оорулууларыбызга шыпаа бер,","Фаттах ысымың менен кайырлуу эшиктерди ач.","Сабак: Адам өз алсыздыгын түшүнүп, чын жүрөктөн дуба кылганда көңүлү тынчтык табат. Дуба үмүтүн жана Кудайга ишенимин тилге салат.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"to-be-fasting","title":"Орозо кармоо","paragraphs":["Рамазан айында бир нече жигит карыянын бир бурчта отуруп тамак жеп жатканын көрөт. Жакындап барып, шылдыңдай сурашат:","— Эмне болду, аксакал, тамак жеп жатасыз, орозо эмессизби?","Карыя: — Албетте, орозомун, болгону суу ичип, тамак жеп жатам.","Жигиттер күлүп: — Бул кандай орозо? — дешет.","Карыя мындай дейт: — Албетте, орозомун. Калп айтпайм, эч кимге жаман көз менен карабайм, эч кимди шылдыңдабайм, ысырап кылбайм, эч кимди кемсинтпейм, ушак айтпайм, бирөөнүн мал-мүлкүнө көз артпайм. Оорума байланыштуу гана ач жүрө албайм. — Анан жигиттерге кайрылып сурайт:","— А силер орозосуңарбы?","Жигиттер уялып, баштарын жерге салышат: — Жок, орозо эмеспиз, болгону тамак жебейбиз.","Сабак: Эгер адам тамактан тыйылып, бирок калптан, ушактан, кемсинтүүдөн жана жаман иштен тыйылбаса, орозонун руханий маанисин толук жашабайт.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"ramadan-prayer","title":"Рамазан дубасы","paragraphs":["Улуу Аллах кылган дубаларыбызды кабыл кылсын, ырыскыбызга береке кошсун, оорулууларыбызга шыпаа берсин, күнөөлөрүбүздү кечирсин, алдыбызда кайырлуу эшиктерди ачсын, жүрөгүбүздү сүйүү жана мээримге толтурсун!","Рамазан майрамыңыздар кут болсун!","Сабак: Чын жүрөктөн кылынган дуба адамга үмүт берет, жүрөгүндө мээрим ойготот. Береке, шыпаа жана кечирим тилөө адамды Жаратканга жакындатат.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"not-leaving-the-right-path","title":"Туура жолдон тайбоо","paragraphs":["Күндөрдүн биринде жумушсуздуктан, бекерчиликтен жана мурасын жеп, убактысын текке өткөрүүдөн тажаган бир адам адал өмүр сүрүү үчүн кеңеш алууну көздөп, падышанын алдына келет да, жол көрсөтүп коюусун өтүнөт. Падыша бир аз ойлонуп, ага мындай тапшырма берет: «Оозуна чейин зайтун майы толтурулган бул кумураны ал да, бир тамчысын да төкпөй, шаардын бир четинен экинчи четине жеткир. Бир эле тамчы жерге түшсө, башың алынарын бил». Көзөмөлдөө үчүн жанына эки жоокерди кошуп берет.","Адам болгон күчүн жыйнап, акылын иштетип, бир тамчы да төкпөстөн кумураны шаардын аркы четине жеткирет. Анан кайра кайтып келип, падышанын алдына чыгат: «Падышам, буйругуңузду кынтыксыз аткардым», — дейт. Падыша андан: «Шаардан эмнелерди көрдүң, кандай окуяларга күбө болдуң?» — деп сурайт. Ал күнү шаарда базар болуп, эл ушунчалык көп эле — ийне таштасаң жерге түшпөйт.","Ошого карабай, адам падышага мындай жооп берет: «Падышам, жан соогалап, кумурадагы майды жерге төкпөйүн деп ушунчалык сак болдум, көзүмдү кумурадан бир саамга да алып, айланама карай алган жокмун. Ошондуктан бир да адамды көргөн жокмун, бир да окуяга күбө болгон жокмун».","Ушул сабактан кийин падыша ага көңүлү ток кеңеш берет: «Эгер жасаган ар бир ишиңе, сага берилген ар бир милдетке ушундай кылдат мамиле кылып, бүт дитиңди ишиңе бурсаң жана Кудайдын көзү дайыма сенде экенин эсиңден чыгарбасаң, эч качан туура жолдон тайбайсың».","Сабак: Ар бир ишине толук көңүл буруп, Кудайдын өзүн көрүп турганын унутпаган адам туура жолдон тайбайт.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"eat-less-and-stay-on-the-right-path","title":"Ченемдүү тамактануу жана чынчыл жашоо","paragraphs":["Тамакта ченемдүүлүк дарыгерден, чынчылдык соттон сактайт.","«Тамакты ченеми менен жеген адамга дарыгердин кереги жок» — эгер адам ашыкча тамактанбай, туура тамактанса, ден соолугун сактап калуу мүмкүнчүлүгү жогорулап, дарыгерге азыраак кайрылат. Тамакта ченемдүү болуу ачка жүрүү дегенди билдирбейт. Бул ашыкча жеп-ичүүдөн алыс болуу, өзүн кармай билүү жана ченемди сактоо дегенди түшүндүрөт.","«Чынчыл жашаган адамга соттун кереги жок» — эгер адам чынчыл, адилеттүү жана мыйзамга ылайык жашап, башкалардын укугун бузбаса, талаш-тартыштарга жана укуктук көйгөйлөргө азыраак туш болот. «Чынчыл жашоо» бул жерде туура жолдон тайбоону да, абийирдүү жүрүүнү да билдирет.","Сабак: Тамакта ченемдүү, жүрүм-турумда түз бол — анда сага дарыгер да, сот да керек болбойт.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"church-bell","title":"Чиркөөнүн коңгуроосу","paragraphs":["Илгери бир өлкөдө мындай эреже болуптур: карапайым адам өлсө, чиркөөнүн коңгуроосу бир жолу, ак сөөк өлсө эки жолу, падышанын жакындарынын бири өлсө үч жолу, падышанын өзү өлсө төрт жолу кагылчу экен.","Күндөрдүн биринде ар ким акыйкат издеп кайрылган сот бир жаранды адилетсиз жерден күнөөлүү деп табат. Ошондо чиркөөнүн коңгуроосу беш жолу кагылат.","Эл аң-таң болуп чиркөөгө келип: «Урматтуу дин кызматчы, падышадан да маанилүү ким бар, коңгуроо эмнеге беш жолу кагылды?» — деп сурайт.","Дин кызматчы: «Албетте, бар — адилеттик. Бүгүн адилеттик өлдү», — деп жооп берет.","Сабак: Адилеттик өлсө, падышадан да чоң нерсе өлөт. Акыйкаттын жанында тур, зулум жазасыз калбасын.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"stoning-the-devil","title":"Шайтанга таш ыргытуу","paragraphs":["Ажылыкка барган бир адам шайтанга таш ыргыта турган маал келгенде, ташты ыргыткандын ордуна аны менен өзүн ургулай баштайт. Жанындагы бир жигит таң калып сурайт:","— Тага, эмнеге өзүңүздү таш менен уруп жатасыз?","Ал киши мындай жооп берет:","— Уулум, биздин бул жердеги шайтан менен эмне ишибиз бар? Адегенде өзүбүздүн ичибиздеги шайтанды таш ыргытып, напсибизди тарбиялап, өзүбүздү тазалашыбыз керек.","Сабак: Чыныгы күрөш сырттагы шайтан менен эмес, адамдын өз напси менен. Өзүн тазалоо башканы айыптоодон оор, бирок баалуу.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"drinking-the-sherbet-of-martyrdom","title":"Шейиттик шербетин ичүү","paragraphs":["Осмон доорунда согушта оор жараланып, жан берип жаткан жоокерлер шейит болор алдында оозу таттуу болсун деп, дарыгерлер өздөрү алып жүргөн чакан челектердеги замзам суусунан жасалган шербеттен ичиришчү экен. «Шейиттик шербетин ичүү» деген сөз айкашы ушундан келип чыккан.","Сабак: Ар бир сөздүн артында бир тарых, бир жан аябастык турат. Тилибиздеги сөздөр өткөнүбүздүн эсин да алып жүрөт.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"why-are-you-waiting-for-the-last-day-of-the-world","title":"Эмне үчүн дүйнөнүн акыркы күнүн күтүп жатасыңар?","paragraphs":["Бир күнү Америкадагы университеттердин биринде мугалим сабакты баштап жатып, студенттерге мындай дейт:","— Бир саамга бүгүн дүйнөнүн акыркы күнү деп элестеткиле. Эртең ушул убакта баары бүтөт. Кутулууга да эч мүмкүнчүлүк жок. Андай болсо, эмне кылат элеңер?","Студенттер ар кандай жооп беришет:","— Ибадат кылып, Кудайдан күнөөлөрүмдү кечиришин сурамакмын.","— Бардык жакындарым менен коштошмокмун.","— Калган убактымды үй-бүлөмө арнамакмын.","— Апамды же атамды көрүп келмекмин.","— Акыркы жолу жакшы көргөн тамактарымдын баарын жемекмин.","— Канып уктап алмакмын.","— Акыркы жолу токойдо сейилдеп, жашыл жаратылыштан ырахат алмакмын.","— Акыркы жолу күндүн чыгышы менен батышын карамакмын.","— Кечинде жылдыздарды карап отурмакмын.","— Эң жакшы көргөн тамагымды жасап, сүйгөн адамдарымдын баарын кечки тамакка чакырмакмын.","— Өмүрүмдө эң көп баргым келген жерге барып, өлүмдү ошол жерден күтмөкмүн.","— Көңүлүн ооруткан адамдарымды издеп таап, мени кечиришсин деп алардан кечирим сурамакмын жана башка.","Мугалим айтылган жооптордун баарын тактага жазат да, анан жылмайып:","— Балдар, мунун баарын жасоо үчүн эмнеге дүйнөнүн акыркы күнүн күтүп жатасыңар? — дейт.","Сабак: Жакшылык кылууга акыркы күндү күтпө. Сүйгөн адамыңа сүйөрүңдү айт, кечир жана жакындарыңдын баасын бүгүн бил.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"most-beautiful-portion","title":"Эң сонун насип","paragraphs":["Дервиштен сурашты:","— Адамдын башына келе турган эң сонун насип эмне?","Дервиш жооп берди:","— Сени угууну каалаган адамга жолугуу.","Сабак: Сени чын жүрөктөн угууну каалаган адамга жолугуу — чоң немат. Угулганыңды сезүү сүйүлгөндөй.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"help-yourself-o-exalted-god","title":"Өзүң жардам бере көр, улуу Аллахым","paragraphs":["Тынчы кеткенге, үйсүз калганга,","Жетим болгонго, жалгыз калганга,","Муктаж болгонго, ач-суусап калганга,","Ооруган жанга, колу кыска калганга,","Көңүлү жарадар болгонго, көзү жолдо калганга,","Үмүтү өчкөнгө, чарасыз калганга,","Капарсыз болгонго, нурдан кур калганга,","Тилеги барга, кыялдар курганга,","Ыймансыз болгонго, Сенсиз калганга —","Өзүң жардам бере көр, улуу Аллахым!","Сабак: Чарасыздын, жалгыздын, үмүтсүздүн акыркы баш калкалары Жараткан. Дуба адамдын эң терең муктаждыгын айтат.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true}]},{"title":"Үй-бүлө жана тарбия","slug":"aile-ve-terbiye","blurb":"Ата-эненин сүйүүсү, бала тарбиялоо жана үй куруу.","count":22,"stories":[{"stem":"father-and-son","title":"Ата менен уул","paragraphs":["Уулу атасы менен катуу урушуп кеткен соң, ачууланып үйдөн чыгып кетет. Буга жүрөгү жараланган атасы да каарданып, үйдө уулунун атын атоого да тыюу салат. Апасы болсо ар түнү уулунун керебетине отуруп, жаздыгын жыттап-жыттап жатып уктап калчу.","— Уулумду сагындым. Суранам, барып таап, үйгө алып келеличи, — десе да, атасы макул болбойт.","Арадан көп убакыт өтөт.","Бир күнү аялынын дайыма көз жашын төгүп жүргөнүн көргөн атанын боору ооруп, чөнтөгүнөн уулунун дареги жазылган кагазды чыгарып, ага сунат:","— Бар, аны ушул даректен табасың, — дейт. — Бирок даректи мен бергенимди ага эч качан айтпа.","Атасы дагы бир нече сөз айтса да, апасы аны укпагандай болду; оюнда жалгыз гана дарек бар эле. Кубанычтан канат байлап, дароо камынып жолго чыкты да, кагаздагы дарекке жетти. Бул жер оңдоочу устакана экен. Уулу жумушчу кийимчен иштеп жүрүптүр. Апасы бир нече мүнөт уулун көзүнө жаш алып карап турду да, акыры аны көздөй басты. Үй-бүлөсүнөн көптөн бери кабар албаган, баары мени унутту деп ойлогон уул апасын көргөндө адегенде таң калып, анан аны бекем кучактады.","Атасынан башкасынын баарын сурап, ал-жайын билип, акырында:","— Ал киши кандай, дагы эле ачуулуубу? — деп апасынан сурады.","Апасы бул суроону жоопсуз калтырып:","— Жүр, уулум, үйгө кетели, — деди.","— Жок, апа, барбайм. Ал киши менен мындан ары бир үйдө жашай албайм, — деди да, иштеген жерин көздөй баса баштады.","Апасы уулун бир аз артынан карап турду да, даярдап келген таттуусун берүү үчүн үн катты.","Уулу белекти алып:","— Суранам, апа, кыйнаба, барбайм. Мени бир да жолу издеп койбогон, ал-жайыма кызыкпаган адам менен бир үйдө жашай албайм, — деди.","Апасы башын шылкыйтып:","— Макул, балам, өзүң бил. Чечимиң бекем экенин көрүп турам. Бирок атаң бир сөз тапшырды: акыркы бир айда дос болуп жүргөн кишиден алыс бол, андан сага жакшылык келбейт. Мурунку досуң менен жараш, — деди.","Муну уккан уул таң калганынан ордунда катып калды.","Апасы үйгө кайтып келип, атасын жемеледи:","— Кайда экенин билсең, эмне үчүн менден жашырдың? Демек, ошон үчүн мынчалык камырабай жүрдүңбү?","Дайыма ачуулуу көрүнгөн атанын көңүлү бошоп, көзүнөн жаш куюлду:","— Ал менин жаным да, жаным, — деди.","— Качантан бери билесиң? — деп сурады апасы.","— Кеткен күндөн бери. Кээде түшкү тыныгууда эмне ичип-жеп жүргөнүн көрүш үчүн барып, алыстан карачумун. Айрым учурда үйгө кеч келишимдин себеби да ушул эле: кечинде уулубуз эмне кылып, кимдер менен жүргөнүн билүү үчүн артынан байкап турчумун, — деп жооп берди атасы.","Карыялар бири-бирин кучактап ыйлап турганда, эшик кагылды. Апасы көз жашын сүртө-сүртө эшикти ачканы жөнөдү.","Уулу үйгө кайтып келиптир. Ал ата-энесинин колунан өөп, экөөнү кучактады. Эми ал баарын түшүнгөн эле: аны унутту деп ойлогон атасы, чындыгында, баласынан көзүн бир мүнөт да алган эмес экен.","Сабак: Сүйүүңдү жашырба, көрсөт. Кээде өз убагында жасалган бир кадам жылдарга созулган таарынычтын алдын алат.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"fathers-footprints","title":"Атанын изи","paragraphs":["Атасы уулуна:","— Уулум, баскан кадамыңа этият бол! — деди.","Уулу жооп берди:","— Өз кадамыңа өзүң этият бол, ата. Анткени мен сенин артыңдан келатам.","Сабак: Тарбиянын эң таасирдүү жолу — үлгү болуу. Бала көбүнчө чоңдордун айтканын эмес, кылганын кайталайт.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"raising-children","title":"Бала тарбиясы","paragraphs":["Бир үй-бүлөдө ата-энесинин тилин албаган уул бар эле. Алар эмне десе, бала ошонун тескерисин жасачу. Мектептеги иши да начар болчу. Сабактарын ынтаа коюп окучу эмес, үй тапшырмаларын да толук аткарчу эмес. Апасы ачууланып урса да, майнап чыкчу эмес. Атасы бөлмөгө камап жазаласа да, баланы оңдой алган жок.","Бир күнү эне баласын мектепке алып баратып, жолдон «аюу үйрөтүүчүгө» жолугат. Тегерегине кызыккан эл топтолгон үйрөтүүчү дап кагып, мурдуна шакек тагылган аюу болсо секирип бийлеп жаткан экен.","Аял токтоп, ойго батты. Ичинен: «Мен бул баланы тарбиялай албай жатам, бул киши болсо аюуну кандай үйрөтүп койгонун кара!» — деди.","Анан аюу үйрөтүүчүгө жакындап: — Баламды тил алдырта албай жатам, сиз бул жапайы жаныбарды кантип үйрөтөсүз? — деп сурады.","Киши жылмайды: — Ар нерсенин өз жолу бар. Менин да өз тарбиялоо ыкмам бар.","Аял: — Суранам, мага жардам бериңиз, — деди.","Аюу үйрөтүүчү баланы карап: — Кыйын эч нерсе жок. Аны мага бир жумага тапшырыңыз, тил алчаак кылып берем, — деди.","Аял сүйүнүп, баласын күн сайын аюу үйрөтүүчүгө алып барып, кайра алып келе баштады.","Бир нече күн эле өткөнүнө карабай, баланын жүрүм-туруму акырындык менен оңоло баштады. Эми ал апасына каршы чыкпай калды. Бир жумадан кийин бала аял каалагандай болуп өзгөрдү. Аял аябай сүйүндү. Аюу үйрөтүүчүгө ыраазычылыгын билдирип, ага көп бата берди.","Кошуна-колоң бул ишке абдан таң калды. Мурдагы тил албас, кежир бала жок болуп, ордуна токтоо, жоош, тарбиялуу бала келген эле.","Мектептеги мугалими да баладагы өзгөрүүгө ыраазы болуп, апасын куттуктады. Бирок өзгөрүү көпкө созулган жок. Мурдагыдай өжөр жана ачуулуу болбосо да, бала эми классташтарынын буюмдарын уурдап, жашыруун иштерди жасап, көз көрүнө калп айта баштады. Мугалим апасына телефон чалып: «Эмне кыларыңызды билбейм, бирок балаңыз абдан кызык болуп калыптыр. Уурулук кылып, калп айта баштады», — деди. Аял катуу кайгырды. Капаланып аюу үйрөтүүчүнү издеп барганы менен, аны таба алган жок. Ал киши ал жерден кетип калыптыр.","Ата-эненин айласыз абалын көргөн көптү көргөн кошунасы: «Кабатыр болбоңуздар, мен жүрөгү кең, акылман бир адамды тааныйм. Кааласаңыздар, ошого барып, жагдайды түшүндүрүңүздөр», — деди.","Аял макул болду. Баласын ээрчитип, акылмандын алдына барды. Ал жагдайды уккандан кийин: — Бул татынакай жигитти мага бир жумага бериңиз, колуман эмне келерин көрөйүн, — деди. Аял сунушту кабыл алды.","Ал баласын акылмандын жанына алып барып, кайра алып келе баштады.","Эки эле жолугушуудан кийин акылман катуу капа болду. Баланын апасына: — Сиздер бул балага эмне кылдыңыздар? Андан айбанга мүнөздүү сапаттарды көрүп жатам, — деди. Аял таң калып: — Мен эч нерсе кылган жокмун, болгону бир кезде бала абдан тентек болгондуктан, аны аюу үйрөтүүчүгө алып барып жүрчүмүн, — деди.","Акылман катуу ачууланды: — Сиздин оюңузча, жаныбар үйрөтүүчү балага тарбия бере алабы? Жаныбарлар коркуу менен, адамдар болсо абийир менен тарбияланат. Жаныбарларды кээде уруп, урушуп, жазалап тартипке салат; бул да жардам бербесе, караңгы бөлмөгө камап, айласыз абалга түшүрүшөт. Өз балаңызды жаныбар үйрөтүүчүгө кантип тапшырып койдуңуз?","Анан сөзүн улады: — Эсиңизде болсун, тарбия — баланы кысымга алуу эмес, анын жүрөгүнө жол табуу. Балаңызды алып кетиңиз. Ага жакын болуңуз, өөп-кучактаңыз, аны угуңуз, сүйүүңүздү аябаңыз. Сүйгөнүн көргөн сайын сиздерге болгон ишеними артат, мамилеси жумшарат.","— Балаңыздын дабасы аюу үйрөтүүчү да, мен да эмесмин; жалгыз өзүңүздөр — ата-энесиздер, — деп акылман сөзүн бүтүрдү.","Сабак: Бала коркуу менен эмес, сүйүү менен тарбияланат. Балага тарбия берүүчү үйрөтүүчү же сырттан келген адам эмес — сүйүү көрсөткөн ата-эне.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"only-my-mother-would-weep","title":"Бир гана апам ыйлайт","paragraphs":["Бир гана апам чын ыйлайт, калганы жалган ыйлайт!","Сабак: Дүйнөдө көп сүйүүнү көрүүгө болот, бирок эненин кызыкчылыксыз, чын ыкластуу сүйүүсүнүн орду жок.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"nails-lasting-lesson","image":"wisdom-stories/Etibar%20Siracsoy/illustrations/es_nail%E2%80%99s-lasting-lesson_ky.webp","title":"Бир мыктын баяны","paragraphs":["Бир айылда ачуусу чукул, чыдамы жок бала жашачу. Болор-болбос сөзгө да туталанып, ачууланганда маңдайындагы адамдын көңүлүн оорутуудан тартынчу эмес.","Атасы уулунун бул мүнөзүнө абдан тынчсызданчу. Бир күнү ага бир баштык мык берип, мындай деди:","— Уулум, кимдир бирөөгө ачууланып, жаман сөз айткан сайын короонун тосмосуна бул мыктардын бирин как.","Бала адегенде муну маанисиз иш деп ойлоду. Бирок эртеси ачууланып, тосмого бир мык какты. Анан дагы туталанып, дагы бир мык какты. Күн өткөн сайын тосмодогу мыктар көбөйө берди.","Бир топ убакыттан кийин бала өзүнүн жүрүм-турумуна көңүл бура баштады. Ачуусу келген сайын колунун мыкка сунулганы аны ойлондуруп жатты. Акыры бир күнү атасына келип:","— Ата, эми ачууланбаганга аракет кылам, — деди.","Атасы жылмайып жооп берди:","— Абдан жакшы. Эми өзүңдү кармап, эч кимдин көңүлүн оорутпай өткөргөн ар бир күнүңдө тосмодон бир мыкты сууруп тур.","Бала айткандай кылды. Күндөр өттү, айлар өттү. Акыры тосмодогу мыктардын баары суурулду.","Бала сүйүнүп, атасын чакырды:","— Ата, карачы! Мыктардын баарын сууруп бүттүм.","Атасы аны тосмонун жанына алып келип, жай гана айтты:","— Мыктардын баарын суурупсуң. Бирок карачы, алардын орду калды. Сен да ачууланып, бирөөгө оор сөз айтканда ушундай болот. Кийин кечирим сурашың мүмкүн, өкүнүшүң мүмкүн, ал адам сени кечириши да мүмкүн. Бирок жүрөктөгү жара кээде изсиз айыкпайт.","Бала тосмодогу тешиктерди көпкө карап турду.","Ошол күндөн тартып ал ачууланганда адегенде унчукпай, анан ойлонууну үйрөндү.","Сабак: Ачуу менен айтылган сөз жүрөктө ушундай из калтырышы мүмкүн: аны кечирим суроо да өчүрө албайт. Ошондуктан ачуу келгенде токтоп, ойлонуп, анан сүйлөө керек.","Этибар Сиражсой"],"hasAudio":false,"hasImage":true},{"stem":"from-a-wise-fathers-advice-to-his-son","title":"Даанышман атанын уулуна айткан насааттарынан","paragraphs":["Оо, менин сүйүктүү уулум!","Адамдар менен тил табыша билүү үчүн акыл керек, уулум. Акыл бакыттын түгөнгүс булагы.","Жашоодон тойууга болбойт; анын кыска же узун болушу баркын кемитпейт.","Мөмө бышканда гана бутактан кооз түшөт. Ошондой эле адамдар турмуш көргөн, тажрыйбалуу адамдарды ар дайым жогору коюшкан.","Адам баласы жаш кезинде кетирген жосунсуз иштерин, адатта, ойлонбой жасайт. Бирок кийин аларды эстегенде, ошол күнөөлөр жүрөгүнө канжардай сайылып, жанын кыйнайт.","Жаш кезинде туура, жакшы жолдо жүргөндөр карылыгында анын акыбети катары урмат-сый көрүшөт.","Күчтүү, кубаттуу болуу жакшы. Бирок күч акылдын буйругуна баш ийүүгө тийиш.","Ааламдардын Жаратуучусу болгон Улуу Жараткан адам баласын бул дүйнөгө түбөлүк жашасын деп жиберген эмес; өмүрүнүн соңунда өлүмдүн даамын татышын буюрган.","Муну да жакшы бил: Аллахтын уруксаты менен мени ушул жашка чейин ден соолукта сактаган эки адат бар. Аларды жылдар бою сынадым: тамакты ченеп жеген жана жегенди сиңириш үчүн басып-сейилдеген.","Дагы бир нерсени билишиңди каалайм: бул дүйнөдө адамдардын үч түрү бар:","Биринчиси — акыл-эси ордунда, келечекти аздыр-көптүр баамдап, ойлоно билген адамдар;","Экинчиси — баскан жолу туурабы же кыйшыкпы, аны ажырата албаган, бирок мындай абалга өз каалоосу менен эмес, айланасындагылардын таасиринен түшкөн адамдар. Аларга насаат айтылса, кабыл алып, сөз угушат.","Үчүнчүсү болсо — өзү эч нерседен кабарсыз, айтылган насаатка да кулак салбайт, бирок баарын билем деп ойлойт. Баарынан бечарасы — ушулар.","Оо, уулум!","Эгер Улуу Жараткан сени мен биринчи катарда атаган адамдардан кылса, кубанам.","Экинчилерден болсоң, сага айтылган насааттарга кулак сал деп кеңеш берем.","Үчүнчүлөрдөн эч качан болбо. Алардын бети Жараткандын алдында да, адамдардын арасында да агарбайт.","Сабак: Акыл — бакыттын булагы, ал эми күч — акылдын кызматчысы. Насаатты уккан көтөрүлөт; баарын билем деп ойлогон болсо кыйрайт.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"hold-my-hand","title":"Колумдан карма","paragraphs":["Кичинекей кыз атасы менен көпүрөдөн өтүп баратышат. Атасы бир аз тынчсызданып, кызынан колун кармоосун өтүнөт:","— Таттуу кызым, сууга түшүп кетпеш үчүн колумдан бекем карма.","Кыз мындай жооп берет:","— Жок, ата, сен менин колумдан карма.","Бир аз таң калган атасы кызыга сурайт:","— Анын эмне айырмасы бар?","— Айырмасы абдан чоң, — деп жооп берет кыз. — Эгер мен сенин колуңдан кармап, мага бир нерсе болсо, колуңду коё беришим мүмкүн. Ал эми сен менин колумдан кармасаң, эмне болсо да колумду коё бербей турганыңа ишенем.","Сабак: Сүйүүнүн күчү — кыйын учурда колду коё бербөөдө. Сүйгөндөрүң сага кол сунушун күтпө, өзүң алардын колун бекем карма.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"puppies-for-sale","title":"Күчүктөр сатылат","paragraphs":["Дүкөндүн терезесине «күчүктөр сатылат» деп жазылган кагаз чапталганын көргөн кичинекей бала ичкери кирди:","— Күчүктөрдү канчадан сатасыз? — деп сурады.","— Отуздан элүү долларга чейин. Ар биринин өз баасы бар, — деди дүкөн ээси.","Бала колун чөнтөгүнө салып, болгон акчасын чыгарып, сатуучунун алдына койду да, баарын кунт коюп санап чыкты. Акырында көңүлү чөгүп:","— Менин болгон акчам он үч доллар жыйырма жети цент экен, — деди. Анан терең дем алып:","— Жок дегенде күчүктөрдү көрүүгө болобу? — деп сурады.","Дүкөнчү жылмайып, күчүктөрдү алып келсин деп арткы бөлмөдөгү аялына үн катты. Бир аздан кийин аял чыкты, артынан томолонгон беш татынакай күчүк ээрчип келди. Бирок алардын бири араң басып жүрдү. Баланын көзү ошол күчүккө кадалды:","— Буга эмне болгон? Эмнеге баса албайт? — деп сурады.","— Ветеринарыбыз анын балтырынын ичке сөөгү тубаса кемтик экенин айтты. Ал эч качан эркин баса албайт, — деп жооп берди дүкөн ээси.","Муну уккан бала толкунданып:","— Мен дал ушул күчүктү сатып алгым келет, — деди. Дүкөн ээси болсо:","— Муну сатып алгың келбесе керек, балам. Кааласаң, сага белек кылып берейин, — деди.","Кичинекей баланын катуу ачууланганы көзүнөн көрүнүп турду. Ал дүкөн ээсинин көзүнө тике карап:","— Аны мага белек кылышыңызды каалабайм. Бул күчүк да башкалардай эле баалуу. Азыр сизге он үч доллар жыйырма жети цент бере алам, ал эми отуз доллар толгонго чейин жума сайын беш доллардан алып келип турам, — деди.","Дүкөнчү:","— Бул күчүктү чындап каалабайсың, уулум. Ал башка күчүктөрдөй болуп сени менен чуркап ойной албайт, — дегенде, бала:","— Бирок ага мүмкүнчүлүк беришибиз керек, ал да башка күчүктөрдөй эле баалуу, — деп каршы чыкты. Анан эңкейип, шымынын багалегин өйдө түрүп, балдар шал оорусунан жабыркаган бутун жана ага тагылган темир таянычтарды көрсөттү. Кайра кишиге бурулуп, жумшак үн менен мындай деди:","— Байке, мен да чуркап ойной албайм. Бул күчүккө да, мага да бизди түшүнүп, колдой турган достор керек.","Сабак: Ар бир жанга аны түшүнүп, колдой турган дос керек. Башкачасы да калгандарындай эле баалуу; ага мүмкүнчүлүк берүү керек.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"festive-gift","title":"Майрамдык белек","paragraphs":["— Аксакал, — деп сурадым, — майрамга эмне алайын?","Ал мындай деп жооп берди:","— Бир нече адамдын көңүлүн көтөр. Бир нече баланы кубантып, жүзүнө жылмаюу тартуула. Колуңдан келсе, бир нече жардынын батасын ал.","Сабак: Эң баалуу белек акча менен эмес, жүрөк жана көңүл буруу менен ченелет. Майрамды чыныгы майрам кылган кээде алганың эмес, бергениң.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"weeds-must-be-pulled-from-the-root","image":"wisdom-stories/Bakhtiyar%20Sirajov/illustrations/weeds-must-be-pulled-from-the-root.webp","title":"Отоо чөптөр","paragraphs":["Мектепте окуп жүргөндө жайкы каникулду үй-бүлөбүз менен бакчабызда өткөрчүбүз. Маркум атам бизди эмгекке көндүргүсү келчү. Өзү жумушта болгон күндөрү бакча иштерин бизге тапшырчу. Коон-дарбыз эгип койгон, аны сугаруу биздин милдет эле. Кудугубуздун суусу ичүүгө жарабагандыктан, коңшубуз Агаселим аксакалдын бакчасындагы кудуктан таза суу ташычубуз.","Жер казганды үйрөнгөн элек. Отоо да кылчубуз: күрөк менен жердин астын үстүнө оодарып, отоо чөптөрдү жанчып-сындырар элек. Бирок алар оңой менен жок болчу эмес. Бир күнү атам бизди чакырып: «Отоо чөптү жок кылгыңар келсе, күрөктү терең сайгыла; тамырын жулмайынча иш бүтпөйт», — деп түшүндүрдү.","Сабак: Көйгөйдүн да, жаман адаттын да тамырын кеспесең, сыртынан оңдоо пайда бербейт. Бир аз убакыттан кийин кайра чыгып келет.","Бахтияр Сиражов"],"hasAudio":false,"hasImage":true},{"stem":"i-am-waiting-for-the-teeth","title":"Тиштерди күтүп жатам","paragraphs":["Кыштын суук кечтеринин биринде кары жубайлар McDonald's ресторанына кирип, бир үстөлгө отурушат. Карыя кассага барып, бир гамбургер, бир чоң куту фри жана чоң Coca-Cola сатып келет. Гамбургерди экиге бөлүп, жарымын аялынын алдына коёт, картошканы да бирден санап, тең жарымын ага берет. Анан Coca-Cola бөтөлкөсүн ачып, адегенде өзү бир ууртайт, кийин аялы ичет.","Айланасындагылар аларды «бир кишиге жетчү тамакты экөө бөлүшүп жатышат, бечаралар» дегендей карап турушат.","Бир аздан кийин аялдын алдындагы гамбургер менен картошкага кол тийбегенин көрүшөт. Аял күйөөсүнүн тамшанып тамак жегенин карап отуруп, маал-маалы менен коладан ууртап коёт...","Акыры жаш кызматкерлердин биринин чыдамы кетип, жубайларга жакындайт да, карыядан сурайт:","— Ата, кечиресиз, силерди бир топтон бери карап турам: сиз жеп жатасыз, аялыңыз болсо тамакка кол тийгизген жок. Жактырбаса, уруксат берсеңиз, ага башка нерсе алып келейин...","Карыя:","— Рахмат, жигит, бирок биз өз абалыбызга ыраазыбыз... Алтымыш жылдан бери үйлөнгөнбүз жана бардык нерсебизди ушинтип бөлүшөбүз, — дейт.","Бул жоопко канааттанбаган жигит эми аялга кайрылат:","— Апа, сиз эмне үчүн гамбургериңиз менен картошкаңызды жебей жатасыз, эмнени күтүп отурасыз?","Кемпир күйөөсүн көрсөтүп, мындай жооп берет:","— Тиштерди...! Тиштерди күтүп жатам, балам.","Сабак: Эч ким сүйгөн адамына көз каранды калбасын. Жараткан эч кимди, өз үй-бүлөсүндө да, жардамсыз калтырбасын.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"fallen-teeth","title":"Түшкөн тиштер","paragraphs":["Бир падыша түшүндө тиштеринин баары түшүп калганын көрөт да, түш жоруучуну чакыртып, маанисин сурайт. Ал киши: «Падышам, бул бардык тууган-туушкандарыңыз каза болуп, эң акырында сиз дүйнөдөн кайтасыз дегенди билдирет», — деп жооп берет. Падыша каарданып, аны кууп чыгат да, башка бирөөнү чакыртып, ага да ошол эле суроону берет. Андан: «Падышам, үй-бүлөңүздө эң узак өмүр сүргөн адам сиз болосуз», — деген жооп алат. Падыша бул жоопко абдан ыраазы болуп, ал кишиге сыйлык берип узатат.","Сабак: Чындыкты айтканда да сөздүн ыңгайын тап. Бир эле ой көңүлдү оорутушу да, жубатышы да мүмкүн.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"builder-of-the-nest","title":"Уянын куруучусу","paragraphs":["Уяны ургаачы куш курат.","Сабак: Уя куруп, үй-бүлөнүн таянычы болгон аялдын мээнетин көрүп, баалай билүү керек.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"mothers-advice-fakir-baykurt-never-forgot","title":"Факир Байкурт унутпаган эне насааты","paragraphs":["Бир күнү Факир Байкурт (түрк жазуучусу, 1929–1999) апасынан чай сурап: «Апа, чай ичким келип турат, жүрү, чай ичели», — дейт. Апасы уулунун сөзүн жерде калтырбай, аны жакын жердеги Топал Хүсейиндин чайканасына алып барат да: «Уста, суранам, балама бир стакан чай алып кел», — деп кайрылат.","Чай келгенде, толкундануусунан анын ысык экенин унутуп, чоң ууртам алат. Оозу күйүп кеткенде, стаканды капысынан жерге таштайт.","Чайдын стаканы топуракка түшкөндүктөн сынбайт, бирок Факир Байкурт апасы азыр аны чабат деп ойлойт. Андай болбойт. Апасы Топал Хүсейинди чакырып, дагы бир чай алып келүүсүн өтүнөт.","Бул жолу Байкурт экинчи чайды үйлөп-үйлөп ичет. Кийин көп жыл бою апасынан ошол күнү эмнеге чаппаганын сурайт, бирок апасы суроону ар жолу жоопсуз калтырат...","Факир Байкурттун апасы бул суроого көп жылдан кийин уулу мугалим болуп иштеген айыл мектебинде жооп берет. Апасы Элиф айым анын сабагына катышкан ошол күндү Факир Байкурт мындай эскерет:","— Сабак учурунда ачууланып, толкундап, үнүмдү катуу чыгарып жибердим! Сабак бүткөндө сырттан апамдан: «Апа, кандай, мугалимдигим жактыбы?» — деп сурадым.","Апам: «Ээ, эмне дейин, уулум, жаман эмес экен», — деди.","— Апа, инспекторлор келип, жактырып, жакшы баа беришет. Сиз болсо «жаман эмес» дейсиз. Бул кандай? — деп сурадым.","Ошондо апам ар кимге сабак болчу мындай сөздөрдү айтты: «Көп жыл бою менден эмнеге сени чаппаганымды сурадың. Эми айтам, кулагыңды ачып ук!","Эгер чайды төккөн күнү сага ачуулансам, ичиңдеги арстан таарынмак. Сени урсам, ал арстан өлмөк! Анда мындай мугалим боло алмак эмессиң. Сен да мендей бол, сабырдуу жүр. Бул балдарды уруп, алардын ичиндеги арстанды өлтүрүүгө аракет кылба».","Сабак: Баланын ичиндеги «арстанды» — өзүнө болгон ишенимин — уруп өлтүрбө. Чыныгы тарбия коркуу менен эмес, сабыр жана сүйүү менен берилет.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"i-am-tired-mother","title":"Чарчадым, апа","paragraphs":["— Чарчадым, апа...","— Эмнеден, уулум?","— Баарынан: иштегенден, достордон, ары-бери жүргөндөн, баарын ыраазы кылууга аракет кылгандан чарчадым. Абдан чарчадым.","— Башыңды тиземе коюп, эс ал, уулум. Бир саамга баарын унут... ооруңду мага бер...","— Рахмат, апа. Сенин бар экениң кандай жакшы; жаныңда жашымды да, башымдан өткөндөрдү да унутам. Бар бол, апа.","— Эне — өмүр берген адам, уулум. Мен ар дайым жаныңдамын.","— Апа, биз да сени аябай чарчатабыз, бизди кечир.","— Мени силер чарчатпайсыңар, уулум. Мени чарчаткан — энесиздигим. Башымды жөлөй турган «эне тизеси» жок менде, уулум... Сен чарчаба, колуңдагынын баркын бил...","Сабак: Эненин кучагы дүйнөдөгү эң жайлуу баш калкалоочу жай. Энеси бар адам чарчоосун коёр жерди дайыма табат — колуңдагынын баркын бил.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"rotten-seed","title":"Чириген үрөн","paragraphs":["Аялы каза болгондон кийин ар кандай оору менен кыйналган кичинекей уулун «чириген үрөн» деп атаган атасы аны кемсинтип, балдар үйүнө өткөрүп берет.","Жылдар өтөт.","Бир күнү ал киши эр жеткен уулун бир мектептин алдында көрүп калат. Көзүнө ишенбейт. Уулунун жайнаган көздөрү менен чың денесин өкүнө караган ата толкундана:","— Мен сенин айыгарыңа, сенден адам чыгарына ишенчү эмесмин. Зор балбан болупсуң. Бул керемет кантип болду? Ооруларыңдан кантип арылдың? — деп кайрылат.","Жигит жаш толгон көздөрүн бир кезде аны кемсинткен атасына кадайт да, аркы жактан жылмайып өзүнө жакындап келе жаткан, аны асырап алган кары аялды көрсөтүп, мындай дейт:","— Сен «чириген үрөн өнбөйт» деп мени балдар үйүнө өткөрүп бергенден кийин, бул апа мени асырап алды. «Сүйүү менен сугарылган ар бир үрөн өнөт» деп, мээримдүү колун эч качан үстүмдөн алган жок.","Сабак: Сөз же өстүрөт, же кыйратат. Бир ооз сөз менен адамды көтөрүүгө да, чөгөрүүгө да болот — сүйүү менен сугарылган ар бир үрөн өнөт.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"grandfather-and-grandson-at-the-market","title":"Чоң ата менен небереси дүкөндө","paragraphs":["Чоң ата небереси менен супермаркетке келет. Текчелердин арасынан азык-түлүк тандап, себетке салып жүрүшөт. Ошол маалда небереси улам «Мага тигини алып бер, муну алып бер!» деп кыйкырып, супермаркетти башына көтөрөт. Чоң атасы болсо ар жолкусунда: «Тынчтан, Ариф, соодабызды бүтүрүп, үйгө кетебиз», — дейт. Баланын нааразычылыгы чегине жетип, текчедеги «Kinder Surprise» шоколаддарынын бирин алып, бут алдына салып эзет. Чоң атасы дагы эле: «Тынчтан, Ариф, соодабызды бүтүрүп, үйгө кетебиз», — дейт да, көңүлү чөгүп жанындагы кызматкерге кайрылат: «Абдан кечирим сурайм, мунун да акчасын төлөйм».","Акыры кассада төлөп, чоң ата менен небереси супермаркеттен чыгышат. Бул окуянын баарына күбө болгон бир айым да алардын артынан чыгып, чоң атага жакындап: «Арифке жасаган мамилеңизге суктандым. Абдан сабырдуу адам экенсиз. Баракелде!» — дейт. Чоң ата айымга ыраазычылык билдирип, жылмаят: «Баланын аты Рафик, Ариф — менмин».","Сабак: Чыңалган учурда өзүңдү колго алуу — чыныгы күч. Кээде тынчтыкты сактоо үчүн башканы эмес, өзүңдү тыюу керек.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"spinach","title":"Шпинат","paragraphs":["Биз алыскы бир айылда жашачубуз. Каттап жүрүүгө жарытылуу жолубуз да жок эле. Апам шпинатты улам бышыра берчү. Бала кезимде атам каза болгондон кийин апамдын акылынан айнып калган деп ойлочумун.","«Муну көп жеш керек, денеге күч берет», — дечү апам. Эртең менен да, түштө да, кечинде да бизге жалаң шпинат бышырып, жанына дайыма жүгөрү нанын кошуп берчү. Мен шпинатты жек көрүп калгам, бул көк чөптү көргүм да келчү эмес.","Бир күнү апама: «Чоңоюп, иштеп, үй-бүлө курганда үйгө эч качан шпинат сатып албайм. Үйүмдө шпинаттан тамак бышпайт», — дедим. Ал болсо ошол күндөрдү чыдамсыздык менен күтүп жатканын айтып, канча жашта болсо да үйлөнүү тоюмда бийлей турганына сөз берди.","Күндөр өтүп, орто мектепте окуш үчүн айылыбыздан шаарга көчүп кеттим. Алган аз гана стипендияма араң жан бакчумун. Айына бир жолу үйгө келгенде, апам дасторконго койгон шпинаттан бир кашык да жегим келчү эмес. Жатаканага кайтып барып, даамдуу тамактарды гана жегим келчү.","Окудум. Мамлекеттик насыянын жардамы менен университетти, магистратураны, докторантураны аяктаганымда, апамдын бели бүкүрөйүп, карып калган эле. Үйлөнчү кызымды ээрчитип айылга келип той бергенде, карыган апам ыйлады да, көп жыл мурун убада кылгандай тоюмда бийледи. Ал бийлеп жатып эмнеге көз жашын төгүп жатканын ошондо түшүнгөн эмесмин.","Арадан жылдар өттү. Апам эки жыл мурун дүйнөдөн кайтты.","Бир күнү апамдын эски сандыгынан ал кезде жазып жүргөн эскерүү дептерин таптым. Дептердин бир бетине апам мындай деп жазыптыр: «Колумда шпинаттын үрөнү гана калган эле. Дайыма шпинат, бир аз жүгөрү эгип өстүрчүмүн. Колдо бар, оозго алар эч нерсе жок болчу. Балдарым ач калбасын деп улам ошол тамакты бышырып берчүмүн. Бирок каршы чыкчу эмесмин. «Шпинат абдан пайдалуу, ошон үчүн силерге күнүнө үч маал берем», — деген сайын жүрөгүм ооручу. Балдарым үчүн колумдан келгени ушул эле. Аларды жанымдан артык көрөм».","Элүү жашымда шпинатты сүйүп жей баштадым. Жубайым үйгө эмнеге шпинатты мынчалык тез-тез сатып аларымды таң кала сурай берет, мени шпинатты абдан жакшы көрөт деп ойлойт. Бирок мен ал тамактын жытын сезген сайын апамдын мени чоңойтуш үчүн тарткан мээнетин, тоюмда ыйлап жатып бийлегенин эстээримди ал билбейт...","Сабак: Эненин жардычылыктагы мээнетин көбүнчө жылдардан кийин түшүнөбүз. Сүйүү кээде жөнөкөй тамак салынган тарелкада жашырынат.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"mother-and-son","title":"Эне жана уул","paragraphs":["Киши колундагы чемодандарды дубалдын түбүнө койду. Анан боюн түзөп, терең дем алды да, энесине: «Апа, бул жер абдан кооз экен», — деди. «Албетте, кооз, уулум», — деп жооп берди кары аял. Бир азга экөө тең унчукпай, бөлмөнү кунт коюп карап чыгышты.","Андан соң аял кичинекей чемоданын ачып, түнкү көйнөгүн, үй тапичкесин, бир нече сүлгүнү жана алкакка салынган сүрөттү алып чыкты. Сүрөттү керебетинин жанындагы үстөлгө койду.","Сүрөттө мектеп формасын кийип, жоокердей түз турган бала бар эле. Көзүнө жаш толуп, эрдин чүрүштүрүп алыптыр...","Эркек терезеге жакындап, көшөгөнү ачты. Бөлмөгө күңүрт күндүн жарыгы төгүлдү. Сыртта аяз эле. Колун жылыткычка коюп, көчөдөн өтүп жаткан ылайга булганган машиналарды бир аз карап турду. Анан башын бурбастан: «Бул шкаф сага жетеби, апа?» — деп сурады.","Кары аял ойго батып кеткендиктен, уулунун сөзүн уккан да жок. Керебетинде бир аз кыйшая отуруп, эскирген алкактагы үркөк караштуу балага көзүн кадап калган эле.","Бул анын мектепке барган алгачкы күнү түшкөн сүрөт болчу.","Аял күтүүсүздөн далай жыл мурунку күнгө кайтып барды. Бир күн мурун мектептин кандай сонун жер экенин сааттап түшүндүрсө да, уулун класска араң киргизген. Күн бою мектепте калып, ар бир танаписте анын жанына барып: «Мен ушул жерде болом, уулум, сени күтүп турам», — деген. Бирок бала ар жолкусунда апасынын колун мурдагыдан да бекем кармап: «Мени таштап кетпе, апа, аябай коркуп жатам», — деп ыйлаган эле.","Күн батып бараткан. Эркек колун жылыткычтан алып, бууланган терезеге таянды. «Тиги чемоданыңды да ач, буюмдарыңды жайгаштыралы, апа», — деди.","«Сен кармалба, уулум, өзүм эле жайгаштырып алам. Ансыз деле буюмум аз», — деди кары аял. Калтыраган колун сунуп, уулунун колун кармады. Бир нерсе айткысы келгендей болду, бирок кайра ойлонду. Жутунуп алып: «Балдар да санааркап калышат», — деди.","Эшик кычырап жабылды. Кары аял боёгу көчүп түшкөн бөлмөдө сүрөттөгү үркөк караштуу, жоокердей түз турган уулу менен жалгыз калды. Керебетте бир аз отургандан кийин үй тапичкесин кийип, көшөгөсү ачык терезенин жанына барды. Уулу машинасына отуруп жаткан экен.","Кары аял коркуп турду. Бир күн мурун бул жердин кандай кооз экени тууралуу сааттап укканына карабай, коркуп турду.","Терезеде уулунун алаканынын изи калыптыр. Аял жаагын ошол изге акырын жөлөдү. Көзүнө жаш толуп, эрдин чүрүштүрүп алган.","«Мени таштап кетпе, уулум, аябай коркуп жатам», — деп шыбырады.","Сөздөр бууланган айнекке урунуп эригенсип, сыртта машинасында отуруп алып ага кол булгалап жаткан уулун көздөй агып жөнөдү.","Ошол түнү кары аял менен бир кабатта жашагандар өксүп ыйлаган үндү угушту. Ансыз деле карылар үйүндө көнүп бүткөн жалгыз нерсе — түнкүсүн коридорлордо жаңырган ушундай өксүк үн эле.","Сабак: Бир кезде энесинин колунан кармаган бала чоңоюп, аны жалгыз калтырышы мүмкүн. Ата-энеге берилгендик материалдык камкордук гана эмес — аларды мээримден жана көңүлдөн кур калтырбоо.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"mothers-love","title":"Эне мээрими","paragraphs":["Эрих Фромм","Бир жаштамын — абдан бактылуумун; апам ар дайым жанымда.","Эки жаштамын — апам кээде гана жанымда. Эмне болуп жатат?","Үч жаштамын — апам жумушта, бала багуучум жанымда.","Беш жаштамын — апам жыйында, чоң энем жанымда.","Жети жаштамын — апам семинарда, мен болсо мектептемин; мугалимим жанымда.","Он үч жаштамын — өспүрүм куракка келдим. Апам дагы эле иштөөгө аргасыз, досторум жанымда.","Он жети жаштамын — апам жумуштан чарчап келет. Мен класста, мектепте же кафеде жүрөм; досторум жанымда.","Жыйырма жаштамын — жашмын. Апам үйдө эмес, досторум жанымда.","Жыйырма үч жаштамын — иштей баштадым. Апам эми үйдө, мен болсо жумуштамын.","Отуз жаштамын — ойлонуп калам: апам экөөбүз акыркы жолу качан чогуу сонун убакыт өткөрдүк эле? Мында бир бөтөнчүлүк бар.","Отуз беш жаштамын — үй-бүлөлүүмүн. Апам өз үйүндө, мен өз үйүмдө.","Кырк жаштамын — апам жолумду карайт; мен бала кезде анын жолун карагандай.","Элүү жаштамын — өзүм да карыдым, бирок эч качан карыбаган бир тилегим калды: жүрөгүмдү анын жүрөгүнө жакындатып, аны кучактап, башымды чарчаган тизесине коюу.","Элүү беш жаштамын — эми дайыма бир эненин, балдарымдын энесинин жанындамын. Өз апам болсо дүйнөдөн өттү; аны сагынып жашайм.","Турмуштун күнүмдүк агымында кетирген эң олуттуу кайдыгерлигибиз — кээде балдарыбызга жана жакындарыбызга жетиштүү убакыт бөлбөгөнүбүз. Балдар — көз алдыбызда тездик менен алмашкан кереметтүү өмүр тасмасынын эң кымбат каармандары. Алардын чоңоюшун байкабай калсак, өтүп кеткен көз ирмемдерди кайра кайтара албайбыз.","Жашоодо өткөн көрүнүштөрдү кайра көрсөтө турган «токтот», «башта», «алдыга» жана «артка» баскычтары жок. Муну түшүнгөн күнүбүз кеч болуп калбасын.","Балаңды бүгүн сүй, бүгүн кучактап, колунан кармап, жанында бол. Анын бүгүнкү күнүн өткөрүп жибербе. Эртең бул дагы башка бир күн болот.","«Эне мээрими — кызыкчылыксыз, коргоочу жана жылуу башпаанек. Ал эч нерсе күтпөгөндүктөн, аны мажбурлап алуу мүмкүн эмес.»","Сабак: Эненин мээрими акы күтпөйт жана эч нерсе менен алмаштырылгыс. Жакындарыңа убакытты бүгүн бөл: кайтарып ала албай турган эң кымбат байлык — убакыт.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"most-beautiful-gift","title":"Эң сонун белек","paragraphs":["Атага — кадыр-барк,","апага — урмат,","балага — мээрим,","өмүрлүк жарга — сүйүү,","доско — берилгендик,","коомго — кызмат,","маркумга — дуба,","дүйнөгө — адамгерчилик,","акыретке — бул дүйнөдө жасалган жакшылык.","Сабак: Эң сонун белек — ар бир адамга өзүнө керектүү камкордукту көрсөтүү: атага кадыр-барк, апага урмат, доско берилгендик, коомго кызмат.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"value-of-your-family","title":"Үй-бүлөңүздүн баасы","paragraphs":["Бир кечте уулу атасына келип, бир суроо бергиси келерин айтты. Атасы макул болду. Уулу түз эле кептин төркүнүнө өтүп, атасынан бир саат иштегенде канча акча табарын сурады. Атасы бул суроого тынчсызданып, эмнеге мындай нерсени сурап жатканын билгиси келди. Уулу жөн гана кызыкканын айтып, жооп күтүп туруп алды. Акыры атасы көнүп, саатына жүз доллар табарын айтты.","Муну уккан уулу башын жерге салды. Бир аз унчукпай туруп, атасынан элүү доллар карыз сурады. Бул өтүнүч атасын ачуулантты. Ал баласы акчаны маанисиз оюнчукка же керексиз нерсеге коротот деп ойлоп, бербей койду да, бөлмөсүнө барып уктоону буюрду. Уулу каршы болбой бөлмөсүнө кирип, эшикти акырын жапты.","Атасы болсо бөлмөдө ары-бери басып, ачуусун басууга аракет кылды. Бир аздан кийин тынчып, уулунан акчаны эмнеге сураганын билбей туруп ачууланганы туура эмес болгонун өзүнө мойнуна алды. Абийири кыйнаган ата уулунун бөлмөсүнө барып, эшикти акырын каккылады да, уктап калган-калбаганын сурады. Уулу али ойгоо экенин айтты.","Атасы бөлмөгө кирип, орой мамилеси үчүн кечирим сурады. Күндүн түйшүгүн уулунан чыгарганын мойнуна алып, элүү долларды сунду да, каалаганындай жумшасын деди. Уулу сүйүнүп ыраазычылык айтты, жаздыгынын алдына катып койгон акчасын чыгарып, санап бүтүп атасын карады. Муну көргөн атасы кайрадан ачууланып, акчасы бар туруп эмнеге дагы сураганын сурады.","Уулу мурда акчасы жетпегенин, эми болсо туптуура жүз доллары болгонун түшүндүрдү. Анан атасынан анын бир саатын «сатып алсам болобу?» — деп сурап, эртең жумуштан эрте кайтып, өзү менен чогуу тамактануусун өтүндү.","Бул сөздөр атасын терең толкутуп, көзүнө жаш тегерентти. Ал кичинекей уулун кучактап, андан кечирим сурады.","Сабак: Балдардын эң чоң муктаждыгы — ата-энесинин аларга көрсөткөн көңүлү, сүйүүсү жана алар менен чогуу өткөргөн убактысы.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true}]},{"title":"Сүйүү жана нике","slug":"sevgi-ve-evlilik","blurb":"Сүйүү, берилгендик жана бирге жашоонун сыноолору.","count":20,"stories":[{"stem":"loving-from-afar","title":"Алыстан сүйүү","paragraphs":["Эки дос жолугуп, мындайча сүйлөшөт:","— Сыягы, мен бир кызды сүйүп калдым окшойт.","— Кандай сонун! Ал муну билеби?","— Жок.","— Анда эмнеге жанына барып, сезимиңди айтпайсың?","— Айтмакмын, бирок рахатым бузулуп калабы деп корком. Турган жеримден башыма түйшүк түшүрүп, сүйүүгө кабылам. Кино, театрга барып, кол кармашып сейилдей баштайбыз. Анан таарынышуусу бар, жарашуусу бар, «тигини эмнеге карадың?», «муну эмнеге тиктедиң?» деген кылыктары бар. Акыры баары бир ажыраша турган болсок, мынча ызы-чуунун эмне кереги бар?","Андан көрө, мен ал кызды алыстан эле сүйүп жүрө берейин.","Сабак: Кээде адам жоготуп алуудан коркуп, сүйүүсүн айтуудан тартат. Бирок жашалбаган сүйүү да жоготуу.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"woman-and-the-mirror","title":"Аял жана күзгү","paragraphs":["Аял эртең менен ойгонуп, күзгүгө карайт. Башында үч тал чач калганын көрөт.","«Мм... — дейт ал. — Бүгүн чачымды өрүп алам...» Чачын өрүп, күнүн эң сонун өткөрөт...","Эртеси ойгонуп, кайра күзгүгө карайт... Башында эки тал чач калганын көрөт.","«Мм... — дейт ал. — Бүгүн чачымды экиге бөлүп тарайм...» Айтканындай жасап, дагы бир сонун күн өткөрөт...","Кийинки күнү ойгонгондо күзгүдөн башында жалгыз тал чач калганын көрөт.","«Эч нерсе эмес... — дейт ал. — Бүгүн аны ат куйрук кылып байлап алам...» Ошентип, бул күнүн да укмуштай сонун өткөрөт...","Дагы бир күнү күзгүгө караса, башында такыр чач калбаптыр.","«Ой-иий!… — деп сүйүнүп кыйкырат. — Кандай жакшы, бүгүн чач менен такыр убара болбойм!»","Сабак: Жашоого болгон көз карашыбыз маанайыбызга таасир этет. Бактыны башкадан гана күтпө; оор күндө да сүйүнө турган себеп тап.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"what-is-loyalty","title":"Берилгендик деген эмне?","paragraphs":["Унутпоо — берилгендик,","оор күндө жүз бурбоо,","эшикти жаап салбоо...","Досуң ыйлап турганда күлбөй,","ар бир кайгысына кошо үшкүрүү — берилгендик...","Ал жөн гана сөз эмес...","Берилгендик — досуңдун абалын тең бөлүшүү,","жарадарга даба,","суусаганга суу болуу,","акырында, берилгендик — «түшүнө билүү», тикени бар деп гүлдү ыргытып жибербөө.","Сабак: Берилгендик — оор күндө таштап кетпөө, тикени бар деп гүлдү ыргытпоо. Ал сөз эмес, иш.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"what-women-have-endured-in-this-world","title":"Бул дүйнөдө аял эмнелерди гана көрбөдү","paragraphs":["Бул дүйнөдө аял эмнелерди гана көрбөдү...","Жомоктордо да ага же сыйкырчы кемпир, же өгөй эне болуу жарашат дешти...","Окуяларда аял тууралуу эмнелер гана айтылбады.","Ага өзү болууга жол беришкен жок; а чынында, бул дүйнөдө аны өмүр берген, бала өстүргөн, эч нерсе күтпөй сүйгөн адам катары таанышы керек эле.","Аял...","«Чачы узун, акылы кыска», — дешти ага.","«Колуң ун, ордуңда отур, эч кимдин ишине аралашпа», — дешти ага.","Аттиң, аял, бул дүйнөдө эмнелерди гана көрбөдүң.","Кадыр-баркыңды билгендер аз болду.","Сүйүүңдү, жүрөгүңдү, жакшылыгыңды көрө алгандар да аз болду.","Өз укугуңду талап кылсаң — жаман, унчукпай койсоң — таза болдуң.","Сүйүүңдү ачык көрсөткөнүңдө, айрымдар өздөрүн сенин кожоюнуң деп ойлошту.","Кээде сүйүүң менен көккө көтөргөн адамдарың ошол бийиктикте кала берүүнү артык көрүп, сени унутушту.","«Кандайсың, эмне жаңылык бар?» — деп сурашкан жок.","Барың же жогуң менен иштери болгон жок.","Сенин да жаның бар экенин унутушту.","Адам экениңди унутушту.","Сени оорутуп салышты, эзишти, көрмөксөнгө салышты...","Сенин болсо көрктөндүрүп, жардам берип, жакшыртуудан башка ниетиң жок эле.","Жаның бул дүйнөдө сүйүүгө зар болуп жүрдү.","Бейиш тууралуу сүйлөп, тозокту жашатышты.","Көзүңө тике карап туруп, ал жерден көргөндөрүн да инкар кылышты. Ичиңден чыккан зар үнүңдү угушкан жок.","Ал баарынан да эне болууну, баласынын көзүнө мээрим менен кароону сүйдү. Бул дүйнөдө баласынын кучагы гана ага чын ыкластуу сезилди.","Сабак: Аял бааланбаган жерде тынчтык да, сүйүү да болбойт. Анын эмгегин жана жүрөгүн көрүү — коомдун милдети.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"friendship-and-love","title":"Достук жана сүйүү","paragraphs":["— Уруш-талашты дарактын жалбырагына жаз: күз келгенде жалбырак куурап түшсүн, уруш-талаш да жоголсун.","— Ачууну булутка жаз: жамгыр жаап, булуттар тарап кетсин, ачуу да жоголсун.","— Жек көрүүнү карга жаз: күн чыгып, кар эрип кетсин, жек көрүү да жоголсун.","— Достук менен сүйүүнү жаңы төрөлгөн наристелердин жүрөгүнө жаз: алар чоңоюп, достук менен сүйүү бүт дүйнөгө жайылсын.","Сабак: Чыр-чатак, ачуу жана жек көрүүнү өткүнчү нерселерге жаз, алар менен кошо жоголсун. Достук менен сүйүүнү болсо жүрөккө жаз, жашап, бүт дүйнөгө жайылсын.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"beware-of-those-you-love","title":"Жакындарыңызга аяр мамиле кылыңыз","paragraphs":["Күн чайыттай ачык күндөрдүн биринде сейил бакта отурган аял жанындагы кишиге селкинчекте кызыл жейде кийип ойноп жүргөн бала анын уулу экенин айтты. Киши жылмайып, көк жейдечен бала да өзүнүн уулу Жамил экенин билдирди.","Бир аздан кийин саатын карап, үн катты:","— Жамил, үйгө кетчү убакыт болду.","— Дагы беш мүнөт, ата, суранам!","Атасы макул болду. Бир аз өткөндөн кийин кайра чакырды, бала болсо дагы беш мүнөт сурады. Киши дагы «макул» деди.","Аял суктана айтты:","— Кандай сабырдуу атасыз.","Киши муңайыңкы жылмайып, жооп берди:","— Бул сабырдуулук эмес. Улуу уулум Камалды былтыр жакын жердеги жолдо мас айдоочу сүзүп кеткен. Ага эч качан жетиштүү убакыт бөлбөптүрмүн. Азыр аны менен дагы беш мүнөт болуу үчүн баарын берет элем. Жамилге карата ошол эле катаны кайталабоого өзүмө сөз бергем.","— Ал ар жолу ойноого дагы беш мүнөт утуп алдым деп ойлойт. Чынында болсо уткан менмин: уулумду дагы беш мүнөт карап туруу бактысына ээ болом.","Сабак: Жакындарың менен өткөргөн ар бир кошумча көз ирмем ырыс. Кеч боло электе аларга бүгүн дагы беш мүнөт убакыт бөл.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"do-not-let-your-hearts-part","title":"Жүрөгүңөрдүн алысташына жол бербегиле","paragraphs":["Адамдар талашып жатканда эмне үчүн кыйкырышат? Адам жаныңда турса, кыйкыруунун эмне кереги бар? Аны менен жай сүйлөшүүгө болбойбу? Ачууланганда эмне үчүн кыйкырасың?","Адамдар бири-бирине нааразы болуп, талашканда жүрөктөрү алыстайт. Ошол аралыкты басып өтүп, бири-бирин угуш үчүн кыйкырууга туура келет. Канчалык ачууланышса, ошончолук катуу кыйкырышат.","Ал эми адамдар бири-бирин сүйгөндө эмне болот?","Алар кыйкырбайт, тескерисинче, жумшак сүйлөшөт. Анткени жүрөктөрү абдан жакын, ортодогу аралык да өтө кыска.","Сүйүүсү ого бетер күчөгөндө эмне болот?","Алар үнүн басып, шыбырашып гана сүйлөшөт, бул сүйүү аларды дагы да жакындатат. Акырында шыбыр да керексиз болуп калат — жөн гана бири-бирин карап, баарын сөз айтпай эле түшүнүшөт. Бири-бирин сүйгөн эки адам ушунчалык жакын болот.","Ошондуктан талашып жатканда жүрөгүңөрдүн алысташына жол бербегиле, ортодогу аралыкты чоңойто турган сөздөрдү айтпагыла. Анткени бир күнү ал аралык ушунчалык узарып, кайра кайта албай калышыңар мүмкүн.","Сабак: Кыйкырык — жүрөктөрдүн ортосундагы аралыктын үнү. Талашта ошол аралыкты чоңойткудай сөз айтпа, болбосо кайра кайтуу кыйындайт.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"purple-jacket","title":"Кызгылт көк чепкен","paragraphs":["Байыркы замандарда түрк журттарында мындай салт болуптур: турмушка чыккан кыздардын себине башка буюмдар менен кошо кызгылт көк түстөгү чепкен да салыныптыр. Чепкен сандыктын эң түбүнө коюлуп, аял аны эч качан кийбесе экен деп тилешчү экен.","Кызгылт көк чепкен эркектер үчүн кесепеттүү кийим болгон экен. Анткени аял ошол чепкенди кийип, үйдүн чатырына, моруна, айылдын аянтына — элдин баары көрө турган жерге чыкса, бул: «Күйөөмдү сүйбөйм, ал мени кыйнайт, өз каалоомсуз турмушка чыккам, ажырашкым келет, оор абалдамын, мага жардам бергиле», — дегенди билдирчү экен. Мындайда айыл эли аялга жардам берип, күйөөсүн айыптачу. Бул эркек үчүн чоң уят саналчу экен.","Ошондуктан эркектер жубайлары менен болгон көйгөйлөрүн күч колдонбой, сүйүү жана урмат-сый менен, анын үстүнө аялынын оюн эске алып, мунасага келүү менен чечүүгө аракет кылышчу экен. Болбосо аял кызгылт көк чепкенин кийип чыгарын билишкен.","Аялы кызгылт көк чепкен кийген эркек ажырашууга гана аргасыз болбостон, кайра оңой менен үйлөнө да албай калчу экен. Анткени аялына кызгылт көк чепкен кийдирген адамдан күйөө чыкпай турганын баары билчү. Аялды сыйлабаган, ага зомбулук көрсөткөн адамга эч ким кайра кызын берчү эмес, ошондуктан анын үйлөнүшү өтө кыйын болчу. Айтымында, дал ушул себептен зомбулукка кабылган аялдардын саны дээрлик жокко эсе экен.","Эгер бир аял кызгылт көк чепкенин кийсе, агып жаткан суулар токтоп, уй сааган, жүн ийриген, килем токуган колдор ишин таштачу; улгайган энелер менен чоң энелер жумушун жыйыштырып, ошол чепкенди кийүүгө аргасыз болгон аялды коргоого чыгышчу экен.","Ошол учурда тегеректе той-топур, сурнай-керней же башка оюн-зоок болсо, баары тынчып калчу экен. Анткени турмушка чыккан аялдын кызгылт көк чепкен кийип, оор абалга түшүшү өлүмгө тете кабыл алынчу.","Кызгылт көк чепкен кийген аялдын күйөөсү үйдөн сыртка чыга албай, чайканага бара албай калчу, эч ким да анын жүзүнө карачу эмес.","Сабак: Аялга каршы зомбулук кабыл алынгыс. Коом аялды коргоону абийир парзы деп билгенде, зулумга орун калбайт.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"red-dress","title":"Кызыл көйнөк","paragraphs":["Кызыл көйнөк апамдын кийим шкафында илинип тура берчү. Ал өмүр бою кийген эскирип, өңү өчкөн кийимдердин арасында бул кызыл көйнөк нур чачып тургандай көрүнчү.","Апамды көрүүгө бардым да, аны көргөн замат өмүрүнүн акыркы көз ирмемдерин жашап жатканын түшүндүм.","Кызыл көйнөктү көрүп, ага:","— Апа, кандай сонун көйнөк! Муну сиздин үстүңүздөн эч качан көрбөптүрмүн, — дедим.","— Кийген да жокмун, — деди ал акырын. — Жаныма отур, сулуу кызым. Бул дүйнөдөн кетерден мурун сага бир сабак айткым келет.","Керебеттин четине отурдум. Апам терең дем алды. «Убактым аз калды», — деди да, сөзүн улады:","— Силерге дайыма жакшы нерселерди үйрөттүм деп ойлочумун. Эми болсо көп жаңылыш нерселерди үйрөткөнүмдү түшүндүм.","— Эмне деп жатасыз, апа?","— Мени ук. Мен жакшы аял эң оболу өзүн ойлобошу керек деп дайыма ишенчүмүн. Өзүмдөн мурда башкаларды гана ойлошум керек эле. Тигинин да, мунун да — деги эле ар кимдин каалоосун аткарууга тийиш болчумун. Менин каалоолорум болсо башкалардын каалоолорунун алдында тебеленип калды. Ким билет, балким, бир күнү менин да тилектерим орундалмак. Бирок ал күн эч качан келген жок. Бүт өмүрүм атаң үчүн, бир туугандарың үчүн жана сен үчүн кылган курмандыктар менен өттү.","— Ооба, апа, сиз эне колунан келгендин баарын жасадыңыз.","— Эх, кызым, сен үчүн да, алар үчүн да жасагандарым өзүмө эч кандай жакшылык алып келген жок. Түшүнүп жатасыңбы? Мен өзүм үчүн эч качан эч нерсе каалаган эмесмин! Атаң азыр коңшу бөлмөдө ачууланып, дубалды тиктеп отурат. Дарыгер ага акыркы күндөрүмдү жашап жатканымды айтканда, жаныма келип:","— Сен өлбөшүң керек, угуп жатасыңбы? Сенден кийин мен эмне кылам? — деди.","— Кызым, мен силер үчүн дайыма өзүмдү отко да, чокко да салдым. Аптанын жети күнү... Үйдө биринчи ойгонгон да, акыркы уктаган да дайыма мен болдум. Күйүп калган нандарды, эң кичине кесимдерди дайыма мен жедим. Чогулткан ар бир тыйынымды кийимиңерге, китептериңерге жумшадым — көбүнчө зарыл болбосо да. Өмүрүмдө бир жолу да дүкөнгө барып, өзүмө кооз бир нерсе сатып алган эмесмин. Былтыр гана сен көргөн кызыл көйнөктү алдым. Кир жуугуч машинаны оңдотууга деп сактаган бир аз акчам бар эле. Көйнөктү алып үйгө келгенимде, атаң мени аябай капа кылды:","— Бул көйнөктү каякка киймек элең? Операга барасыңбы? — деди.","Чынында, ал туура айткан. Ал көйнөктү дүкөндө ченеп көргөндөн башка бир да жолу кийбедим.","— Эх, кызым, адам бул дүйнөдө өзүн ойлобосо, тиги дүйнөдө бактылуу болот деп ойлочумун. Эми буга ишенбейм. Менимче, Кудай каалоолорубузду дал ушул дүйнөдө, тирүү кезибизде орундатышыбызды каалайт. Азыр бир керемет болуп, ушул төшөктөн тура алсам, таптакыр башкача жашамакмын.","Апамдын мага айткан акыркы сөздөрү ушул болду:","— Кызым, — деди ал, — менин жолум менен кетпе. Мага сөз бер.","Апама сөз бердим, анан ал акыркы демин чыгарды.","Сабак: Өзүн дайыма унуткан адам бир күнү өз тилектерин жашабай калганын түшүнөт. Башкаларды сүй, бирок өз жашооңдун да баркын бил.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"i-kiss-your-eyes","title":"Көзүңдөн өбөм","paragraphs":["Эмне үчүн «көзүңдөн өбөм» деп айтыларын билесизби?","Сагынычтын азабын баарынан көп көздөр тартат; ошондуктан жолугушууга эң оболу көздөр татыктуу.","Сабак: Эң көп сагынган жолугушууга эң татыктуу. Сүйүү мээнетин тарткандын акысын кайтарат.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"i-love-you","title":"Мен сени сүйөм","paragraphs":["Айтылып жүргөндөй, бир булбул ак розага ашык болуптур... Ал ар түнү учуп келип, жанына конуп, сүйүүсүн билдирчү экен. Ак роза болсо булбулдун сезимине кайдыгер карап, анын сүйүүсүнө көңүл бурчу эмес.","Бир күнү булбул дагы бүт кайратын жыйнап, ак розанын жанына конот да, аны акылынан адашкандай сүйөрүн айтат. Роза болсо: «Жакама жармашпа, мен сени сүйбөйм!» — деп булбулду кагып салат. Булбул канчалык жалынбасын, роза аны четке кага берет.","Бул сүйүү ушунчалык күчтүү болгондуктан, булбул айласыздыктан титиреп, розадан кечирим сурайт да, анын бир тикенин сындырып алып, болгон күчү менен жүрөгүнө саят. Аппак розаны өз каны менен кызылга боёйт!","Роза кеч болсо да, булбулдун аны чындап катуу сүйгөнүн түшүнөт. Бирок андан не пайда! Эми өтө кеч эле. Булбул кызылга боёлгон розанын бутактарынын алдында көзүн түбөлүккө жумду.","Ошол күндөн бери кызыл розалар «МЕН СЕНИ СҮЙӨМ» деген маанини да билдирет.","Сабак: Сүйүүнүн баркы кээде өтө кеч түшүнүлөт. Сүйгөнүңдүн баркын убагында бил, кийин «эми кеч» деп калба.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"what-breaks-a-marriage","title":"Никедеги өчүргүч","paragraphs":["Атасы менен жаңы үйлөнгөн уулунун ортосунда мындай окуя болот.","Атасы уулунан ак кагаз, калем жана өчүргүч алып келүүнү суранат.","— Эмнеге? — деп сурайт уулу.","— Сен алып келчи, — дейт атасы.","Уулу калем менен кагаз алып келет, бирок өчүргүч таба албайт.","— Барып өчүргүч да сатып кел, — дейт атасы.","Уулу аябай таң калат, бирок барып өчүргүч сатып алып, атасынын жанына отурат.","— Жаз, — дейт атасы.","— Эмне жазайын?","— Каалаганыңды жаз.","Уулу бир сүйлөм жазат.","— Эми өчүр, — дейт атасы.","Уулу өчүрөт.","— Дагы бир сүйлөм жаз.","— Кудай үчүн, ата, эмнени каалап жатасыз?","— Дагы бир нерсе жаз.","Уулу жазат. Атасы кайра жазганын өчүртөт.","Бул жазып-өчүрүү бир нече жолу кайталангандан кийин атасы сурайт:","— Кагаз али да акпы?","— Ооба, ак, ата. Мунун баары эмнени билдирет?","Атасы колун уулунун ийнине коюп мындай дейт:","— Ооба, уулум, нике деген өчүргүчсүз болбойт... Жубайыңдын айрым каталарын кечирип, үстүнөн өтө билишиң керек. Сенин каталарыңды өчүрүш үчүн жубайыңда да ошондой өчүргүч болууга тийиш. Антпесеңер, кыска убакытта никеңердин барагы капкара болуп калат...","Эгер жашооңордо өз ара сүйүү менен урмат-сый күтсөңөр, экөөңөр тең муну бири-бириңерге көрсөтүшүңөр керек. Өчүргүчтү болсо эч качан унутпагыла!","Сабак: Нике — кечире билүү өнөрү. Сүйүү менен урмат улана берсин үчүн эки тарап тең бири-биринин кемчилигин «өчүрө» билиши керек.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"rose","title":"Роза гүлү","paragraphs":["Гүлдү ашыкча сугарсаң, чирийт; аз сугарсаң, куурайт; өлчөмү менен сугарсаң, жашайт.","Сабак: Сүйүүдө да, тарбияда да ченем негизги. Ашыкча кысым да, кайдыгерлик да эмес — ченемдүү камкордук жашоону сактайт.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"yellow-and-red-flowers","title":"Сары жана кызыл гүлдөр","paragraphs":["Илгери бир үйдүн терезесине коюлган сары гүлдөр «бул үйдө оорулуу адам бар, бул жерден өтүп баратып ызы-чуу кылбагыла» дегенди, ал эми кызыл гүлдөр «бул үйдө бойго жеткен кыз жашайт, сүйлөгөн сөзүңөргө көңүл бургула» дегенди билдирчү экен.","Сабак: Адамдарга сыйды кээде назик бир ишарат менен да билдирүүгө болот. Эскертүү үчүн дайыма үн көтөрүү шарт эмес.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"mother-of-pearl-flower","title":"Седеп гүлү","paragraphs":["Сот залында ажырашуу арызы каралып жаткан сексен жаштагы жубайлардын абалы баарынын жүрөгүн оорутту... Катуу унчукпай отурган кемпирдин ыйдан соолуп калган көздөрүн тиктеген сот кары аялга токтоо үн менен кайрылды:","— Айтыңызчы, эжеке, эмнеге ажырашкыңыз келет? — деп сурады.","Кары аял терең дем алып, каргылданган үн менен сөз баштады:","— Бул адам мени чарчатты, туптуура элүү жылдан бери жашоодон тажатып бүттү... — деди да, унчукпай калды.","Залга узакка созулган тынчтык орноду. Жымжырттыкты бир журналисттин фотоаппаратынын жарыгы бузду. Ким билет, элүү жылдык өмүрдөн кийинки бул окуя гезиттерге кандай ат менен чыгат? Сот отурумуна көп журналист көз салып отурган. Аял эмне айтат? Баары аны угуп турду. Кары аялдын көзүнө жаш толуп, сөзүн улады: — Менин аябай жакшы көргөн бир седеп гүлүм бар эле... Бул киши аны билбейт... Элүү жыл мурун болгон. Ал гүлдү мага белек кылган гүлдестен үзүп алган жалбырагымды тамырлатып өстүргөм. Балалуу болбодук, ошол гүлдү баламдай көрдүм. Бир убакта гүл соолуй баштаганын байкадым.","Ошондо ар түнү күн чыга электе ойгонуп, гүлдү сугарып турууга сөз бердим. Элүү жыл өттү, бул киши бир да жолу түнкүсүн туруп: «Бул гүлдү мен сугарайын», — деген жок. Кечээ түнгө чейин... Кечээ алым кетип, уктап калыпмын, ойгоно албай койдум... Мен ушундай адам менен элүү жыл жашадым. Өмүрүмдү, үмүтүмдү, баарымды бердим. Андан эч нерсе көргөн жокмун. Ишенип коюңуздар, ансыз жакшыраак жашай алам.","Сот карыяга кайрылды:","— Айтар сөзүңүз барбы, ата? — деп сурады.","Кары киши таягына сүйөнүп, күнөөлүүдөй түр менен сотту көздөй бурулуп, сөзүн баштады:","— Аскер кызматымды багбан болуп өтөдүм. Ал бакчанын көрктөнүп, гүлдөп турушу үчүн көп эмгектендим. Фатима менен да ошол жерден таанышкам. Ага эң кооз гүлдөрдөн гүлдесте тартуулачумун. Жаңы үйлөнгөнүбүздө мойну ооруп жатканын айтканда, дарыгерге алып бардым. Дарыгер: «Көпкө чейин ойгонбой уктап жатса, мойнундагы булчуңдар катып, абалы начарлайт. Ар түнү уйкусун бөлүп ойгонсун да, бир аз басып жүрсүн», — деди. Жубайым дарыгердин сөзүн уккан жок... Менин да тилим өтпөдү... Ошол күндөрү кокустан гүлүбүз соолуй баштады. Мен ага: «Гүлдү түнкүсүн туруп сугарсаң, кайра жанданат», — дедим. Сөз берүүсүн өтүндүм, ал макул болду...","Ар түнү аны ойготуп, карап турчумун. Сүйгөн аялымдын баласындай көргөн гүлүн сугарып жатканын карачумун. Ар түнү ошол гүл мен болгондой сезилчү...","Карыя бир аз унчукпай туруп, кайра сөзүн улады:","— Ар түнү ал уктагандан кийин ойгонуп, идиштеги сууну төгүп салчумун. Седеп гүлүн түнкүсүн сугаруу жакшы эмес, урматтуу сот... Кечээ түнү болсо... эмне дейин, карылык экен... мен да ойгоно албай калыпмын... Гүл бир түн суусуз кала бермек, бирок жубайымдын абалы начарлап кетиши мүмкүн... Аны ойготпой калганым үчүн мени күнөөлөдү... Мен үн катпай, унчукпадым...","Ошол учурда журналисттер баш болуп, залдагылардын баарынын көзүнө жаш толгон эле...","Сабак: Сүйүү кээде сөздө эмес, жылдар бою үнсүз тартылган камкордукта жашынат. Сүйгөн адамыбызды коргойлу, жүрөк оорутуудан алыс бололу.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"can-a-broken-heart-love-again","title":"Сынган жүрөк кайра сүйөбү?","paragraphs":["Бирөө дербиштен сурады:","— Сынган жүрөк кайра сүйөбү?","— Ооба, сүйөт, — деди дербиш.","Ал киши кайра сурады: — Сиз сынган идиштен суу ичип көрдүңүз беле?","Дербиш жооп берди: — А өзүңүз идиш сынды деп суу ичпей койдуңуз беле?","Сабак: Идиши сынса да, адам суудан кечпейт. Ошол сыңары, жүрөгү сынса да, сүйүүдөн баш тартпайт.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"beloved-is-one-who-gives-love-to-people","title":"Мээрим төккөн мээрим табат","paragraphs":["Көп жыл мурун Кытайда Ли-Ли аттуу кыз турмушка чыгып, күйөөсү жана кайненеси менен бир үйдө жашай баштайт. Бирок көп өтпөй эле кайненеси менен тил табышып жашоо абдан кыйын экенин түшүнөт. Экөөнүн мүнөзү таптакыр эки башка болгондуктан, алар бат-баттан урушуп кетишчү. Кытай салты боюнча мындай көрүнүш жакшы саналчу эмес жана айланадагылардын нааразылыгын жаратчу.","Бир нече айдан кийин түгөнбөгөн келин-кайнене чатагы жаш келинге да, ортодо калган күйөөсүнө да тозоктун азабындай сезиле баштайт. Бир чара көрүү керек деп чечкен келин атасынын эски досу болгон татымал сатуучуга чуркап барып, муңун айтат. Кары киши ага чөптөрдөн дары даярдап берип, үч ай бою күн сайын кайненесине бышырган тамакка аз-аздан кошууну тапшырат. Келин кайненесин өлтүргөнү билинбесин деп, «уу» аз-аздан берилмек.","Кары киши эч ким, өзгөчө күйөөсү шектенбеши үчүн, кайненесине абдан жакшы мамиле кылып, ага эң даамдуу тамактарды бышырып берүүсүн айтат. Үйүнө сүйүнүп кайткан Ли-Ли карыянын айтканын так аткара баштайт.","Ал күн сайын эң сонун тамактарды бышырып, кайненесинин табагына тамчылатып «уу» кошчу. Эч ким шектенбесин деп ага абдан жакшы мамиле кылчу. Бир аз убакыттан кийин кайненеси аябай өзгөрүп, келинине өз кызындай мамиле кыла баштайт. Кылган иши жанына баткан жаш келин өкүнгөн бойдон татымалчынын дүкөнүнө барат да, кайненесин уунун таасиринен куткара турган дары берүүсүн өтүнүп жалбарат. Эми ал кары аялдын өлүшүн каалабай калган эле.","Кары киши алдында турган Ли-Лини карап, каткырып күлөт да: «Кымбаттуу Ли-Ли, мен сага берген нерсе болгону витамин болчу. Чыныгы уу сенин ойлоруңда болчу. Сен ага жакшы мамиле кылган сайын, ал уу да эрип, ордун сүйүүгө бошотту. Ошентип, силер чыныгы эне-баладай болуп калдыңар», — дейт.","Сабак: Чыныгы уу көбүнчө адамдын өз ойлорунда болот. Алдыңдагыга сүйүү менен мамиле кылган сайын жек көрүү эрийт, душман дос болуп калат.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"true-love","title":"Чыныгы сүйүү","paragraphs":["Бардык сезимдер жашаган бир арал болуптур.","Бир күнү арал чөгүп баратканы жөнүндө кабар тарайт. Сезимдер аралдан кетүүгө шашылыш даярдана башташат.","Сүйүү болсо аралдан кетүүгө шашпайт. Керемет келип куткарат дегендей, эң акыркы ирмемге чейин күтөт. Арал толук чөгүп баратканда гана Сүйүү жардам суроону чечет.","Ошол учурда Байлык абдан чоң кайык менен аралдан алыстап бараткан экен.","Сүйүү: «Байлык, мени да өзүң менен кошо ала кетесиңби?» — деп сурайт. Байлык: «Жок, ала албайм. Кайыгымда толтура алтын-күмүш бар, сага орун жок», — дейт.","Бул жолу Сүйүү абдан кооз жел кайыкта сүзүп бараткан Текебердикке кайрылат: «Текебердик, суранам, мага жардам берчи».","Текебердик: «Сага жардам бере албайм, Сүйүү. Аябай суу болупсуң, парусумду жок кыласың», — деп жооп берет.","Кайгы жакын жерде экен. Сүйүү андан да жардам сурайт: «Кайгы, сени менен кошо барсам болобу?»","Кайгы: «Ох, Сүйүү, ушунчалык кайгылуумун, жалгыз калгым келип турат», — дейт.","Бакыт Сүйүүдөн анча алыс болбосо да, ушунчалык толкунданып тургандыктан, анын чакырганын укпай калат.","Бир маалда бир үн угулат: «Сүйүү, кел, мени менен кет». Сүйүү өзүн ушунчалык бактылуу сезгендиктен, куткаруучусунун ким экенин суроо оюна да келбейт. Жээкке жеткенде аны куткарган жан Сүйүүнү ошол жерге калтырып, жолун улантат.","Жээкке чыккандан кийин ага канчалык карыз экенин түшүнгөн Сүйүү алдынан чыккан акылманга окуясын айтып: «Мага жардам берген ким болду экен?» — деп сурайт.","Акылман: «Ал Убакыт болчу», — деп жооп берет.","«Убакытпы? Эмнеге мага жардам берди?» — деп сурайт Сүйүү.","Акылман жылмайып: «Анткени Сүйүүнүн канчалык маанилүү жана баалуу экенин Убакыт гана билет», — дейт.","Сабак: Чыныгы сүйүүнүн баркын убакыт гана билет. Убакыт чын сүйүүнү жашатат, жалган сүйүүнү болсо өчүрүп, унуттурат.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"early-marriage","title":"Эрте нике","paragraphs":["Университетти жаңы эле бүтүп, мектепте мугалим болуп иштей баштагам. Бир күнү мугалимдер бөлмөсүндө окуучулардын сынак барактарын карап отурдум. Кыз окуучулар жакшы баа алып жогорку класска өтүшү үчүн ката жоопторун өчүрүп, оңдоп жаттым.","Ошол учурда мугалимдер бөлмөсүнө бир киши кирип, кыздардын сынак барактарын эмне үчүн өзгөртүп жатканымды кызыга сурады. Мен: «Бул кыздар сынактан өтпөй калса, аталары мектептен чыгарып, он эки-он үч жашында күйөөгө беришет. Ал эми жогорку класска өтүшсө, никеге туруу курагы жок дегенде он беш-он алтыга жетет. Ошол убакыт ичинде эң жалкоо окуучу да сабактан сөзсүз бир нерсе үйрөнөт», — дедим.","Жарым сааттай өткөндөн кийин директор мени чакырып, мугалимдер бөлмөсүндө эмне кылып жүргөнүмдү сурады. Сынак барактарын карап жатканымды айттым.","— Мугалимдер бөлмөсүндө бир кишиге жолугупсуң. Ага эмне дедиң? — деп сурады.","— Ал киши мени сизге арыздандыбы? — деп сурадым.","— Такыр андай эмес! Ал мага мектепти текшерүүгө келгенин, бирок буга эч кандай муктаждык жок экенин айтты.","— Эмнеге? — деп таң калдым.","— Ал мындай деди: силерде акылман жаш мугалим бар экен, ага менин ыраазычылыгымды жеткириңиз.","Сабак: Мугалимдин кичинекей камкордугу бир кыздын тагдырын өзгөртүшү мүмкүн. Эрте нике балдарды билимден ажыратат; буга көз жуумбайлы.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"advice-for-those-who-marry","title":"Үйлөнгөндөргө кеңеш","paragraphs":["Жаңы үй-бүлө курган жаш жубайларга турмушту көп көргөн улуулар мындай насаат айтышат:","«Өз турмушуңарды башкалардын турмушуна салыштырбагыла. “Тигинин күйөөсү мындай” же “мунун аялы тигиндей” дебегиле.","Кемчиликсиз адам издебегиле: эч кимибиз кынтыксыз эмеспиз. Бири-бириңердин өткөнүңөрдү чукуп ээлебегиле. Өткөн иш өткөн бойдон калсын.","Жубайыңар айттырбай эле оюңарды билип алат деп күтпөгүлө. Муну эч ким биле албайт. Эмне каалап, эмнеге тынчсызданып жатканыңарды ачык айткыла. Көйгөйдү ичке катпай, сүйлөшүп чечкиле.","Чогуу жашасаңар да, ар бириңердин өз дүйнөңөр бар экенин кабыл алгыла. Кирпилер тикендери мүмкүнчүлүк бергенче гана жакындашат; ашыкча жакындаса, бири-бирин жарадар кылышат. Силер да бири-бириңердин жеке чектерин сыйлагыла.","Үй-бүлөдө бири-бириңерге кожоюн же кул болбой, өмүрлүк жолдош болгула.","“Баары дайыма жакшы болот” деп убада бербегиле. Анын ордуна: “Кыйынчылыкка кабылсаң, жаныңда болом”, — дегиле.","Күндүз таарынышып калсаңар да, уктаар алдында бири-бириңерге “Кайырлуу түн” дегенди унутпагыла. Эртеңки күнүңөр жарашуу менен башталсын.»","Сабак: Бактылуу нике салыштырууда жана кемчиликсиздик издөөдө эмес, ачык сүйлөшүүдө, өз ара урматта жана жеке чектерди сыйлоодо.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true}]},{"title":"Достук жана адамдык мамилелер","slug":"dostluq-ve-insan-munasibetleri","blurb":"Дос тандоо, мээрим жана адамдарга мамиле.","count":31,"stories":[{"stem":"humanity","title":"Адамгерчилик","paragraphs":["Ал жылдар бою окуп, мээнет кылды. Акыры тагдырын аныктай турган сынак күнү да келди... Атасы Казым абдан талапчыл адам эле; уулунун сабактарына дайыма жакындан көңүл буруп, бул сынактан сөзсүз өтөрүнө ишенчү...","Камал имаратка кирип, сынак тапшыра турган классын тапты. Суроо-жооп барактары таратылганда толкунданганы менен, сынак башталганда кыйла тынчып калды... Суроолорго оңой жооп берип, жоопторунун тууралыгына толук ишенип отурду... Сынактын бүтүшүнө жарым саат калган. Өзүнө ушунчалык ишенген эле...","Бир маалда ал класстын терезесине тигиле карады. Эмнени көргөнүн ким билсин, эч ойлонбостон ордунан тура калып, эшикти көздөй чуркады...","— Кайт! Болбосо сынагың жокко чыгарылып, бир жылың текке кетет, уулум, — деп сынак алып жаткан мугалим артынан кыйкырды. Бирок ал токтобой, чуркаган бойдон имараттын арткы эшигинен чыгып кетти...","Болгон окуяны уккан атасы бир нече сааттан кийин үйгө келген Камалды адегенде тилдеп, анан бетке да чаап жиберди. Казым абдан капалуу эле. Эмне үчүн класстан чыгып кеткенин, сынакты эмне үчүн жарым жолдо таштаганын сураса да, атасы мындан бетер ачууланарын билген Камал унчуккан жок... Айтса да, түшүнмөк эмес...","Казым ошол жыл бою уулун тынымсыз жемелеп, тилдей берди. Камал буга таарынганы менен, үн катпай, башын жерге салып сабактарын окуй берди.","Кийинки жылы кайра сынак тапшырып, медицина факультетине өттү... Мыкты дарыгер болду. Шаарда көп жыл жашаганына карабастан, алыскы бир айылдык ооруканага өз каалоосу менен дайындоону суранды. Ал жерде бир жыл иштеген соң, үй-бүлөсү конокко келди... Атасы экөөнүн ортосундагы сынак окуясы эбак унутулган эле...","Кар жаап, суук түшкөн бир кечте Камалдын үй телефону шыңгырады. Чалган киши жакын айылдардын биринде оорулуу бар экенин айтты. Камал сумкасын алып жолго чыгарда, атасы Казым уулун тоо жолдорунда жалгыз калтыргысы келбей, кошо барууну чечти. Катуу бороондо бир сааттай жөө басып, ошол айылга жетишти. Үйдү таап, эшигин какты. Эшикти карыя ачып, аялы ооруп жатканын айтты да, дарыгерди атасы менен кошо ичкери чакырды...","Камал бейтапты текшерип, керектүү дарылоону дайындады. Карыган аял дарыгерге ыраазычылык билдирип, титиреген үн менен: «Ушул суукта дартыбызга даба болдуң, уулум. Сен сыяктуу жакшы адамдар болбосо, бул дүйнө эмне болмок? Адам болуу оңой эмес... Угуп тур», — деди.","«Көп жыл мурда шаарга баргам. Жолдун ортосунда капысынан абалым начарлап, ичим катуу сайгылашты. Айланамда эч ким жок, көчөлөр бош эле. Көрсө, ошол күнү сынак болуп жатыптыр. Беш мүнөт өтпөй, бир жаш жигит тынчсызданып жаныма келди. Ошол ысыкта мени жарым саатта ооруканага жеткирди. Кош бойлуу элем, балама бир нерсе болуп кетпесин деп коркконумдан калчылдап турдум. Кабыл алуу бөлүмүндөгү дарыгер дагы он мүнөт кечиксем, өлүп калышым мүмкүн экенин айтты... Ошол күнү уулум төрөлдү.","Мени ооруканага жеткирген жигиттин атын сурап алгам — Камал экенин айткан. «Сынакта отургам. Терезеден карап сизди көрдүм, жалгыз экениңизди түшүнүп, класстан чыгып жардамга келдим. Сынактан баш тартып бир жылымды жоготсом да, эч өкүнбөдүм», — деген.","Уулумдун атын Камал койдум. Аны ошол боорукер жигиттин окуясын айтып чоңойтуп, Камалдай адам болсун деп дайыма насаат бердим. Азыр ал мугалим... Шакирттерин биринчи кезекте адам кылып тарбиялоого аракеттенет... Эх, ошол жигитти таап, анын адалдыгын алсам кана... Ар ким дарыгер, мугалим же инженер боло алат. Бул дүйнөдөгү эң кыйыны — адам боло билүү... Ал жигит кандай сонун адам эле. Мени жолдун ортосунда жалгыз таштаган жок». Муну уккан доктор Камал: «Акым адал, эне, кабатыр болбоңуз...» — деди.","Атасы Казымдын көмөкөйү бүтсө да, көз жашын көрсөткүсү келген жок. Бирок үйдөн чыкканда жашы бетин жууп жатты. Жолго чыккандан кийин да Казымдын көз жашы токтогон жок. Ал «Камал, уулум...» — дегени менен, буулуккан ыйдан сөзүн уланта албай калды.","Сабак: Кесипке ээ болууга болот, эң кыйыны — адам болуу. Бир жигиттин өз убагында кылган боорукердиги муундан муунга созулган жакшылыкка айланат.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"how-we-treat-people","title":"Адамдарга болгон мамиле","paragraphs":["Адамдарга мамилең отко болгон мамилеңдей болсун:","өтө алыстаба — тоңуп каласың;","өтө жакындаба — күйүп каласың.","Саади Ширази","Сабак: Мамиленин да ченеми бар. Адам менен мамиледе ченемди сакта: үшүп калгыдай алыстаба, күйүп калгыдай жакындаба.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"kindness-builds-stronger-bonds","image":"wisdom-stories/Etibar%20Siracsoy/illustrations/es_kindness-builds-stronger-bonds_ky.webp","title":"Адамдар ортосундагы мамиле","paragraphs":["Адам турмушунун эң терең, эң назик катмарында бир чындык бар: адамдар менен болгон мамилебиз — жан дүйнөбүздүн күзгүсү. Үй-бүлө очогунун жылуулугу, туугандык байланышыбыз, достор арасындагы түшүнүшүү — мунун ар бири жашоодогу эң кымбат байлыктардын бири. Ал эми кесиптештердин ортосундагы сый-урмат менен жылуу мамиле күнүмдүк эмгекке дем берген көзгө көрүнбөс жарык сыяктуу.","Мээримдүүлүк — жөн гана жүрүм-турум эмес, адамдын жан дүйнөсүнүн байлыгы. Ал — жүрөктөрдү жакындаткан, көңүл сууп турган чакта жылуулук берген, сөз айтпай эле бири-бирин түшүнүүгө жол ачкан үнсүз көпүрө.","Ушул көпүрөнү сактап, бекемдей алсак, жашообуз маңыздуу болуп, адамдар бири-бирине жакындайт, дүйнөдө жашоо да бир аз жеңилдейт.","Сабак: Мамиле өз ара сый-урмат, түшүнүшүү жана мээримдүүлүк менен бекемделет. Жакындыгыбыз үзүлбөшү үчүн бири-бирибизге кам көрүүнү унутпайлы.","Этибар Сиражсой"],"hasAudio":false,"hasImage":true},{"stem":"friendship-of-horses","title":"Аттардын достугу","paragraphs":["Үйүмдүн жанындагы фермада эки ат багылат. Алыстан караганда алар башка аттардан эч айырмаланбайт. Бирок жакын барсаң, абдан кызык нерсени көрөсүң: аттардын бири сокур. Ээси аны кыйбай, коопсуз жана жайлуу аткана салдырып берген. Мунун өзү эле өзгөчө таң каларлык камкордук.","Аттарга жакындасаңыз, коңгуроонун үнүн угасыз. Бул үн жүгөнүнө коңгуроо тагылган экинчи, кичирээк, дени сак аттан чыгат. Ошол үн сокур атка шеригинин кайда экенин сезип, артынан ээрчүүгө жардам берет.","Бул эки досту кунт коюп байкасаңыз, коңгуроолуу ат сокур аттын кайда экенин дайыма текшерип турганын көрөсүз; сокур ат болсо коңгуроонун үнүнө кулак салып, акырындан дени сак аттын артынан ээрчийт.","Коңгуроолуу ат ар күнү кечинде атканага кайтып баратканда, сокур досу коңгуроонун үнүн уга ала турганчалык жакын келе жатканына көзү жетсин деп, анда-санда токтоп, артына карайт.","Сабак: Жараткан бизди кыйын учурда жалгыз таштабайт; жардам керек болгондо аны адамдын колу аркылуу жиберет. Кээде ошол жардамчы болуу өзүбүзгө туш келет.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"go-but-come-again","title":"Барыңыздар, бирок кайра келиңиздер","paragraphs":["Осмон салттарынан: үйүнө келген коноктордун дагы келишин каалаган кожоюндар алардын бут кийимдерин тумшугун үй жакка каратып, эшик алдына тизип коюшчу экен. Ошондо конок үйдөн чыкканда артка карай баскандай көрүнчү; мунун мааниси «барыңыздар, бирок кайра келиңиздер» дегенди билдирчү.","Сабак: Кичинекей ишарат менен чоң жылуулук көрсөтсө болот. Адамга берилген баа көбүнчө ушундай майда кыймылдардан билинет.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"meddling-in-others-lives","title":"Башкалардын жашоосуна кийлигишүү","paragraphs":["Кудай эч кимди башкалардын жашоосуна кийлигишкидей жумушсуз калтырбасын!","Сабак: Суралбаган кеңеш кээде жардамдын ордуна жүк болот. Жакшылык кылам деп башканын жашоосуна кийлигишүү көбүнчө зыян алып келет.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"everyone-is-the-same-here","title":"Бизде баары бирдей","paragraphs":["Райондук муниципалитетке жаңы дайындалган жаш жетекчи аймакты кыдырып, абал менен таанышууну чечет. Жалгыз өзү жер-жерлерди аралап чыккандан кийин, четки көчөлөрдүн бириндеги чайканага кирип, чай буюртма берет.","Ошол маалда он эки-он үч жаштардагы бир бала:","— Байке, бут кийимиңизди боёп берейинби? — деп жетекчиге кайрылат.","Бут кийими ансыз деле боёлгон болсо да, баланын көңүлүн ооруткусу келбей:","— Макул, боёй бер. Жакшы боёсоң, сураган акчаңды эки эсе берем, — дейт. Анда бала:","— Мен баарына бирдей боёп берем, — деп жооп берет.","Жетекчи:","— Кантип эле? — деп таң калат.","Бала мындай дейт:","— Мугалимибиз: «Балдар, кандай иш кылсаңар да, баарына бирдей мамиле кылгыла, эч кимди бөлбөгүлө», — деген. Мен бул акчага оорулуу апама дары алам. Эгер сизге башкалардан өзгөчө кызмат кылсам, ал дары апамдын оорусуна шыпаа болбой калат!","Жаш жетекчи өмүрүндөгү эң маанилүү сабактардын бирин алды. Абдан толкунданып, балага чөнтөгүндөгү эң чоң акчаны жана өзүнүн визиттик картасын берди. Атасы жок, окуусун улантып жүрүп оорулуу апасын да багууга аракет кылган бул балага кам көрөрүн убада кылды.","Баланын жүрөгүнө ушундай чынчылдыкты сиңирген мугалимге да атайын барып, өзүнчө ыраазычылык билдирди.","Бут кийим боёгон баладан уккан сөзүн унутпай, ишинде дайыма колдонуп жүрүү үчүн, үстөлүндөгү аты-жөнү жазылган тактайчанын артына «Бизде баары бирдей» деген сүйлөмдү жаздырып койду.","Канчалык кыйын болсо да, бул принципти ишинде дайыма сактоого аракет кылды.","Сабак: Адамга ээлеген орду үчүн эмес, адам болгону үчүн бирдей мамиле кыл. Коомду майда учурларда туураны тандагандар өзгөртөт.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"pair-of-boots","title":"Бир жуп өтүк","paragraphs":["Бир күнү мектептердин биринде мугалим эжей окуучуларына каалаган темада аңгеме жазууну тапшырып, эң мыкты аңгеменин авторуна бир жуп өтүк белек кыларын айтат. Окуучулардын баары жазгандарын бүтүрүп, ага тапшырышат.","Мугалим аңгемелерди бирден окуп чыгып, ар бирин абдан жактырат. Эң мыктысын тандоо кыйын болгондуктан, жеңүүчүнү чүчүкулак менен аныктоону чечет.","Ар бир окуучу кагазга бир ат жазып, бүктөйт да мугалимдин үстөлүндөгү кутуга салат. Кагаздарды аралаштыргандан кийин мугалим бирин сууруп чыгып, үнүн бийик чыгара айтат:","— Амина!","Класс кол чабууга бөлөнөт. Амина өтүктөрдү көкүрөгүнө кысып, кубанычтан төгүлгөн көз жашын токтото албайт.","Кечинде мугалим үйүнө келгенде, класста болгон окуяны жолдошуна көзүнө жаш алып айтып берет. Жолдошу таң калат:","— Сонун чечим таапсың. Анда эмнеге ыйлап жатасың?","Мугалим жооп берет:","— Анткени кутудагы кагаздардын эч биринде окуучулардын өз аты жок болчу. Баары биздин класстагы эң жакыр үй-бүлөнүн кызы Аминанын атын жазышыптыр. Алардын ар бири өтүктү дал Амина утуп алышын каалаган экен.","Сабак: Башканын кубанычын өз кубанычыңдан жогору коюу да жеңиш. Чыныгы мээрим кээде башканын пайдасы үчүн өз мүмкүнчүлүгүңдөн баш тарта билүү.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"glass-of-milk","title":"Бир стакан сүт","paragraphs":["Окуу акысын төлөө үчүн үймө-үй кыдырып, майда буюмдарды сатып жүргөн жакыр бала бир күнү чөнтөгүндө бир тыйын да калбаганын, өзү болсо аябай ачка экенин көрөт. Ал кийинки эшикти каккылап, тамак сурап көрүүнү чечет.","Эшикти жаш аял ачат. Бала уялып, тамак сурай албай, бир стакан суу гана өтүнөт. Аял анын ачка экенин сезип, суунун ордуна чоң стакан сүт алып келет.","Бала сүттү шашпай ичип бүткөн соң сурайт:","— Сизге канча карызмын?","— Эч нерсе, — деп жооп берет аял. — Апам бизге жакшылыкты акы күтпөй кылууну үйрөткөн.","Бала болгону мындай дей алат:","— Сизге чын жүрөктөн ыраазымын.","Ал жерден узап баратып, өзүн дене жагынан гана эмес, руханий жактан да күчтүү сезет. Аллахка жана адамдарга болгон ишеними бекемделет.","Арадан жылдар өтөт. Бир күнү ошол аял катуу ооруп калат. Жергиликтүү дарыгерлер оорунун себебин аныктай албагандыктан, аны чоң шаардагы адистерге жөнөтүшөт.","Кеңешүүгө доктор Ховард Келли да чакырылат. Бейтаптын кайсы шаардан келгенин укканда, ал дароо анын палатасына жөнөйт. Аялды көрөрү менен тааныйт: бул — көп жыл мурун ага бир стакан сүт берип, жүрөгүндөгү үмүт отун кайра жандырган ошол эле аял эле.","Доктор Келли аялдын дарылануусун жеке көзөмөлүнө алып, аны айыктыруу үчүн колунан келгендин баарын кылууну чечет. Узак дарылоодон кийин аял сакайып чыгат.","Ооруканадан чыгууга убакыт келгенде, доктор Келли дарыланууга кеткен чыгымдардын эсебин алдырат. Кагаздын четине бир нече сөз жазып, эсепти аялдын палатасына жөнөтөт.","Аял эсепти санааркап ачат. Көрсөтүлгөн сумманы төлөй албайм деп коркуп, бүт өмүрүмдү ушул карызды жабууга жумшайм го деп ойлойт. Бир маалда кагаздын четиндеги сүйлөмгө көзү түшөт:","«Бир стакан сүт менен толук төлөндү.»","Колу: доктор Ховард Келли.","Сабак: Акысыз жасалган жакшылык жоголбойт. Ал көрүнбөгөн эсепке жазылат да, убагы келгенде, кээде такыр күтпөгөн маалда алдыңдан чыгат.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"handful-of-roasted-chickpeas","title":"Бир ууч куурулган нокот","paragraphs":["Бир бала апасы менен кошо жаңгак-мөмө саткан дүкөнгө кирет. Ал тынбай: «Куурулган нокот каалайм», — деп өжөрлөнөт. Апасынын сатып алгысы келбегенин көргөн сатуучу баланы аяп:","— Балам, кел, өзүң бул жерден бир ууч ал, — дейт.","— Жок, өзүң берсең гана алам, — деп жооп берет бала.","Сатуучу ага бир ууч толо куурулган нокот берип, сурайт:","— Эмне үчүн өзүң албай, менин беришимди кааладың?","Бала жылмайып мындай дейт:","— Анткени сенин уучуң меникинен чоң.","— Машаллах, кандай зирек бала экенсиң! — деп сатуучу да жылмаят.","Сабак: Кээде эмне сураганың канчалык маанилүү болсо, кимден сураганың да ошончолук маанилүү. Бергендин уучу чоң болсо, үлүшүң да көп болот.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"compassion","title":"Боорукердик","paragraphs":["Кыштын суук түнү эле. Жумуштан үйгө кайтып бараткам. Алдымда мас адамдай көрүнгөн бирөө бар эле. Оңго-солго теңселип, алсырап, жанындагы мамыга жармашып алыптыр. Жанына бардым. Жашы отуздан ашса керек. Абдан таза, тыкан кийинген экен. Өтүп бараткандардын айрымдары ичимдиктин зыяны жөнүндө үнүн бийик чыгарып сүйлөп, башкалары шылдыңдап күлүп жатышты.","— Жакшысызбы, жардам керекпи? — деп сурадым.","Ал онтогондой үн чыгарып:","— Ооруп жатам!… — деди.","Жыгылып кетпесин деп белинен кармап, такси токтоочу жерге жеткирдим. Такси күтүп калдык. Кечке маал токтогон кар кайра жаай баштады; акырындап муз тоңгон жолдордо жарышып чуркаган жолбун иттерден башка тирүүлүктүн белгиси калбаптыр.","Такси табуудан үмүтүм үзүлүп баратканда, жаныбызга бир такси токтоду. Айдоочуга жагдайды түшүндүрүп, шашып жатканыбызды айттым.","Оорулууну арткы орундукка отургузуп, ооруканага жөнөдүк. Дарыгерлерге ыраазымын: дароо керектүү жардамдын баарын көрсөтүп, керектүү дарылоону жасашты; биз болсо анын керебетинин жанында күтүп турдук.","Нөөмөтчү дарыгер оорулууну жок дегенде үшүп калуудан сактап калганыбызды айтты. Жигит али сүйлөй албагандыктан, бизди карап гана жылмайып жатты. Айдоочу да жанымда эле... Бир аздан кийин бейтап эсине келди. Аны кайра унаага отургузуп, үйүнө жеткирдик.","Жубайы анын диабеттик комага бат-бат түшүп каларын билгендиктен, уулу менен кошо катуу чочулап көчөгө чыгыптыр. Бизди көргөндө толкундана чуркап келишти. Үй-бүлө мүчөлөрү бири-бирин бекем кучактап, көздөрү кубанычка толду.","Бир нече саатка созулган чарчообуздан из да калган жок; бизге кантип ыраазычылык айтарын билбей турган үй-бүлөнүн бактысын көрүп, биздин да көзүбүзгө жаш толду.","Коштошордо айдоочудан канча карыз экенимди сурадым.","Ал башын чайкады:","— Сен карыз эмессиң, тескерисинче, мен сага карызмын, досум! — деди. — Сен мени ушундай жакшылыкка шерик кылдың. Балким, жыйырма жылдан бери ыйлабаган адамга ушул сонун сезимди тартууладың.","Айдоочуну боорума кысып коштошкондо, түндүн суугун сезген жокмун жана үйгө жөө кайтууну чечтим.","Ким билет? Балким, жолумдан дагы бир жардамыма муктаж адам чыгар?","Сабак: Адамгерчилик боорукердиктин үстүнө курулат. Боорукердик — ыйлаган менен кошо ыйлоо эмес, көз жашын токтотуунун жолун табуу.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"i-want-a-friend","title":"Дос каалайм","paragraphs":["Мал да, мүлк да каалабайм,","мен чыныгы дос каалайм.","Кайсы мүлк өлгөн ээсине ырайым дубасын окуптур?","Мага ырайым дубасын окуй турган дос каалайм.","Сабак: Адамдын чыныгы байлыгы мал-мүлк эмес, берилген дос. Бул дүйнөдөн өткөндө сени ырайым менен эстей турган дос ар кандай байлыктан кымбат.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"those-you-should-not-befriend","title":"Достошпой турган адамдар","paragraphs":["— Текебер менен достошпо! Ал абалыңды да, көңүлүңдү да, жүрөгүңдү да түшүнбөйт; азап тартасың.","— Өзүн абдан акылдуу санаган менен достошпо! Көп сүйлөйт, куру сүйлөйт, кем сүйлөйт; азап тартасың.","— Намарт менен достошпо! Эрдикти да, жүрөктү да, достукту да билбейт; азап тартасың.","Сабак: Текебер, өзүнө өзү ыраазы, намыссыз адам менен достуктан өкүнүч келет. Дос тандаганда анын жүрөгүнө кара.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"know-your-friend","title":"Досуңду тааны","paragraphs":["Досуңду тааныгың келсе — аны кыйын абалда, кыйынчылыкта, чыр-чатакта сынап көр; анан дагы бир кызыкчылыгына тийип көрүп, ошондо ким экенин бил.","Сабак: Дос кыйынчылыкта, оор учурда жана кызыкчылык сыноосунда таанылат. Жай күндө баары дос; чыныгы досту кыйынчылык ачып берет.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"to-be-alone","title":"Жалгыз болуу","paragraphs":["Бир таанышымдыкына бардым. Үйүнө кирип, бөлмөсүнө өттүм. Ал башын жерге салып, үнсүз отуруптур. Кайгылуу көрүнчү.","— Капалуу жүрөсүңбү? — деп сурадым. Ал башын көтөрүп, көзүмө тике карады да: — Жок, жалгызмын, — деп жооп берди.","Сабак: Эң чоң кайгы — адамдардын арасында жүрсөң да өзүңдү жалгыз сезүү. Жаныңдагынын жалгыздыгын байкоо — чыныгы сезимталдык.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"if-the-road-does-not-tire-you-it-is-because-of-your-companion","title":"Жол чарчатпаса, жолдошуңдан","paragraphs":["Апам мындай деп айтып калчу: «Атаңа абдан жаш кезимде турмушка чыктым. Жарытып тамак жасай да алчу эмесмин, колума ийне алып сайма сайып, тигиш тиккенди да билчү эмесмин. Бир күнү кайненем — сенин чоң энең — кошунага барганы камынып жатып, жүнүн жууп-кургатып даярдаган жуурканды алдыма жайып: ‘Мен келгенче муну шырып бүтөсүң’, — деди. Шырый баштадым, бирок алым жетпеди. Ийне жууркандан өтпөй койду. Ыйлагым келди. Бир жагынан ийне колума сайылып, ооруганынан көзүмө жаш толсо, экинчи жагынан кайненеме эмне дээримди билбей, көз жашым тыйылбай жатты.","Ошол маалда атаң түшкү тыныгууга үйгө келди. Менин ыйлап отурганымды көрүп, ийнени колуна алды да, аз эле убакытта жуурканды шырып бүтүрдү. Анан тамагын ичип, кайра жумушуна кетти. Кайненеме эч нерсе айткан жок. Ал үйгө кайтып келип, жууркандын толук даяр болгонун көргөндө абдан ыраазы болду».","«Жол чарчатпаса, жолдошуңдан» деп бекеринен айтылган эмес.","Сабак: Чарчаткан да, жүктү жеңилдеткен да жол эмес, жаныңдагы адам. Туура жолдош оор ишти да жеңилдетет.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"compliment","title":"Комплимент","paragraphs":["Мария апасы менен Нью-Йорктогу чакан батирде жашачу. Ал ири компанияда катчы болуп иштечү. Күндөрү тынч, бир калыпта, бир аз көңүлсүз өтчү. Жумушунда болсо ага дээрлик эч ким көңүл бурчу эмес.","Бир күнү эртең менен жумушка баратып, көчөдөн жаңы ачылган баш кийим дүкөнүн көрүп, кызыга ичкери кирди. Дүкөндө апасы менен келген кичинекей кыз жана өзүнө баш кийим тандап жаткан дагы бир кардар бар эле.","Мария бир нече баш кийимди кийип көрдү. Алардын бири өзгөчө жакты. Аны башына кийгенде, кичинекей кыз суктана үн катты:","— Апа, карачы, бул айым ушул баш кийим менен кандай сулуу көрүнөт!","Кыздын апасы Марияга бурулуп:","— Айым, бул баш кийим сизге абдан жарашат, — деди.","Берки кардар да аларга кошулду:","— Чын эле, бул баш кийим менен абдан сулуу көрүнөт экенсиз!","Мария күзгүнүн алдына барып, өзүн карады. Өмүрүндө биринчи жолу күзгүдөгү келбетин мынчалык жактырып турду. Жүзүнө жылмаюу уялады. Кассага барып, баш кийимдин акчасын төлөдү.","Дүкөндөн чыкканда, алдында таптакыр башка дүйнө ачылгандай болду. Гүлдөрдүн өңү мурда эч качан көрбөгөндөй ачык, таза абанын жыты болсо мурдагыдан да жагымдуу сезилди. Көчөдөгү машинелер менен адамдардын үнү да кулакка шайкеш обондой угулду. Мария өзүн сулуу жана бактылуу сезип баратты.","Кеңсенин имаратына жеткенде, күзөтчү эшикти ачып, ага «Кутман таң!» деди. Лифтте бирөө кайсы кабатка барарын сурап, анын ордуна баскычты басты. Кесиптештери күнү бою суктана карап, кандай сулуу көрүнүп турганын айтып жатышты. Алар Марияны биринчи жолу көрүп жаткандай эле. Жетекчиси болсо жаңы долбоор тууралуу пикирин билүү үчүн аны түшкү тамакка чакырды.","Сыйкырдуу күн аяктаганда да Мариянын жүзүнөн жылмаюу кетпеди. Ал жашоосу бир заматта кантип өзгөрүп кеткенин ойлоп, мунун баарын жаңы баш кийимине байланыштырып жатты.","Таксиге түшүп, үйүнө кайтты. Эшикти ачкан апасы аны көрөрү менен таң калып айтты:","— Мария, кандай сулуу болуп калыпсың! Көздөрүң бала чагыңдагыдай жанып турат!","— Ооба, апа, мунун баары жаңы баш кийимимдин аркасында. Бүгүн укмуштуудай күн өткөрдүм!","— Кайсы баш кийим? — деп апасы таңыркай сурады.","Мария чочуп кетип, башын кармалады. Баш кийим жок эле. Аны таксиде, түшкү тамактанган жерде же кеңседе унутуп калгандырмын деп ойлоду. Анан дүкөндө болгон окуяларды ирети менен эстеди: баш кийимди кийип көргөнүн, адамдардын жылуу сөздөрүн, кассага барып капчыгын чыгарганын жана баш кийимди кассанын үстүнө коюп койгонун...","Ошондо ал баарын түшүндү: баш кийимин дүкөндө унутуп, көздөрү кубанычтан жайнап, сыртка баш кийимсиз эле чыгып кетиптир.","Демек, Марияны күнү бою бактылуу кылган баш кийим эмес, адамдардын чын жүрөктөн айткан сөздөрү ойготкон өзүнө болгон ишеним менен кубаныч экен. Өзгөргөн дүйнө эмес, Мариянын дүйнөгө карашы болчу.","Сабак: Бир жылуу сөз адамдын өзүнө болгон мамилесин, кээде бүт дүйнөсүн өзгөртүшү мүмкүн. Бакыт буюмда эмес, адамдын ичинде жана ага көрсөтүлгөн чын көңүлдө.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"how-to-ward-off-insults","title":"Кемсинтүүлөрдү кантип кайтаруу керек","paragraphs":["(Самурайлардын жашоосунан алынган сабактуу окуя)","Жашы улгайган даанышман самурай жашаптыр. Ал шакирттерине акылмандыктын жана согуш өнөрүнүн сырларын үйрөтчү экен. Бир күнү кезектеги сабак учурунда класска оройлугу жана таш боорлугу менен белгилүү жоокер кирет. Ал атаандаштарын кемсинтип, ачуусун келтирип, анан каарданган каршылашынын улам ката кетиришинен пайдаланып жеңчү. Бул жолу да ошол ыкмасын колдонуп, самурайды кармашка түртүш үчүн ага бир нече кемсинтүүчү сөз айтат. Самурай болсо аларга көңүл бурбай, сабагын уланта берет.","Кемсинткен сөздөрүн бир нече жолу кайталап да самурайдан эч жооп ала албаган жоокер ачууланып, класстан чыгып кетет.","Бул көрүнүштү кунт коюп карап турган шакирттер устатынан сурашат:","— Устат, бул кемсинтүүлөргө эмне үчүн чыдадыңыз? Эмнеге аны кармашка чакырбадыңыз?","Даанышман самурай мындай жооп берет:","— Эгер кимдир бирөө силерге белек алып келип, аны кабыл албасаңар, анда ал белек кимге таандык бойдон калат?","— Мурунку ээсине, — деп жооп беришет шакирттер.","— Көрө албастыкка, жек көрүүгө жана кемсинтүүгө да ушундай караш керек. Силер аларды кабыл албасаңар, мындай «белектер» силерге сунган кишинин өзүндө калат.","Сабак: Кабыл албаган кемсинтүү ээсине кайтат — кайтарылган белектей. Жамандыкка жамандык менен эмес, токтоолук менен жооп бер.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"to-forgive","title":"Кечирүү","paragraphs":["Бирөөнү кечирүү — аны сүйүү деген эмес; аны менен сүйлөшүүгө же мамилени улантууга милдеттүү болуу деген эмес; анын күнөөсүз же туура экенин моюнга алуу деген эмес.","Кечирүү — таарынычтын, кектин жана жек көрүүнүн туткунунан кутулуу, эски жаранын оорусунан арылуу.","Кечиргиле жана эркин болгула. Бирок башыңардан өткөндөн сабак алгыла, кайра ошол эле жерден жараланбагыла.","Сабак: Кечирүү бирөөнүн кылганын туура деп табуу эмес. Ал — жүрөгүңдү кектен бошотуу. Кечир да, жеңилде, бирок сабагын да унутпа.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"welcome-my-bey","title":"Кош келдиңиз, бейим","paragraphs":["Маркум атам Хафыз Али Чанаккалада жүргөндө мен али энемдин курсагында, жети айлык элем. Атамды эч качан көргөн да, тааныган да жокмун. Анын бир да сүрөтү жок эле.","Өтө оор күндөр болчу. Мобилизация, баскынчылык, боштондук, жакырчылык, жокчулук жылдары...","Балалыгыбыз нан издеп чуркап, азап менен өттү.","Апам бир жакка баргысы келгенде дайыма жаныма келип:","— Уулум, мен базарга барам. Атаң келсе, дароо мага кабар бер!","— Таежеңдикине барам. Атаң келсе, дароо мага кабар бер!","— Коңшу үйгө барам. Атаң келсе, дароо мага кабар бер! — дечү.","Апам көзү жолдо болуп, атамды күтүп жүрдү.","Мен чоңоюп, кесиптүү болуп, дүкөн ачтым. Апам мурдагыдай эле бир жакка барарда дүкөнгө келип, кайда барарын айтчу да: «Атаң келсе, мага кабар бер, ээ!» — деп кошумчалачу.","Жылдар өттү. Апам карыды. Ошентсе да адатын таштабай, таягына сүйөнүп жаныма келип: «Атаң келсе, мени чакыр, ээ!» — дечү.","Бир күнү абалы начарлап, төшөккө жатып калды.","Өлүм алдында биз менен коштошуп: «Мени жакшы бактыңар, акыңарды адал кылгыла», — деди. Акырын мага бурулуп: «Атаң келсе, ага апам сени дайыма күттү деп айт», — деди. Бир маалда башын көтөрүп, эшикти карады да, жылмайып: «Кош келдиңиз, бейим, кош келдиңиз!» — деп жан берди.","* * *","Балыкесирде жашаган кары өтүкчү Жевдет Алкалптын эскерүүлөрүнөн.","Кагазга түшүргөн: изилдөөчү-жазуучу, Бурса Чынар Анадолу лицейинин география мугалими Мустафа Догру.","* * *","18-март — Чанаккаладагы жеңиш күнү.","Эгер 1915-жылы Чанаккала жыгылып калганда, Анадолуда жасалма мамлекеттер түзүлүп, бул жерде жашаган элдер бири-бирине душман кылынып кырылышмак, өлкө англис, француз жана италиялыктардын колониясына айланмак.","* * *","Чанаккалада шейит болгон азербайжан жоокерлерибиз менен кошо бардык шейиттердин арбагы ыраазы болсун! Эч бир эненин көзү жолдо калбасын!","Сабак: Эненин өмүр бою созулган берилгендиги менен күтүүсү сүйүүнүн эң таза көрүнүшү. Мекен үчүн шейит болгондордун жана көзү жолдо калган энелердин эстелиги ыйык.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"caring-call-brightens-the-day","image":"wisdom-stories/Etibar%20Siracsoy/illustrations/es_caring-call-brightens-the-day_ky.webp","title":"Көңүл буруу","paragraphs":["Адам үчүн эң кымбат нерселердин бири — башкалардын көңүл буруп, камкордук көрсөтүшү. Кээде тууганың, досуң же таанышың жөн гана ал-жайыңды сурап, кыскача телефон чалып койсо, жүрөгүңө күн тийгендей болот. Ошондо бул кең дүйнөнүн бир жеринде сени эстеп, бар экениңди баалаган адамдар бар экенин сезесиң.","Ар бир адам сүйүүгө, эске алынууга, кадыр-баркка муктаж. Чын дилден айтылган салам, чын көңүлдөн ал-жай сурашуу же күтүүсүз телефон чалуу кээде эң кымбат белектен да баалуу болот. Анткени ушундай жөнөкөй көңүл буруу адамга эл арасында өз орду бар экенин, жакындарынын жүрөгүндө кадырлуу экенин сездирет.","Балким, бир нече мүнөт көңүл бөлүү кимдир бирөөнүн күнүн жарык кылып, жүрөгүнө үмүт жандырып, жашоого болгон ышкысын дагы бир аз күчөтөр.","Кээде адамдын өмүрүн дары эмес, жүрөккө жакын жылуу сөз, камкордук, көңүл жакындыгы узартат. Анткени бакыттын эң бекем таянычтарынын бири — өзүңдүн унутта калбаганыңды билүү.","Сабак: Бирөөнүн ал-жайын сурап, аны эстеп коюу майда иштей көрүнгөнү менен, ага чоң дем-күч бере алат. Эч ким өзүн унутта калгандай сезбеши үчүн камкордугубузду аябайлы.","Этибар Сиражсой"],"hasAudio":false,"hasImage":true},{"stem":"your-friends","title":"Сенин досторуң","paragraphs":["Бир күнү бир жигит үйлөнүүнү чечет. Тойго бир жума даярдангандан кийин, бир кечте атасына: «Ата, сизден бир өтүнүчүм бар. Бардык ишти жалгыз бүтүрүүгө күчүм жетпей жатат. Суранам, бул тизмени алып, андагы досторумдун баарына чалып, тоюма чакырып коюңузчу», — дейт. «Макул, уулум!» — деп жооп берет атасы.","Той күнү жигит ачууланып атасына жакындайт: «Ата, мен сизден досторумдун баарына чалышыңызды суранбадым беле!»","— Уулум, сен кандай сурансаң, дал ошондой кылдым.","— Менин тизмемде элүү киши бар болчу, бирок бул жерден он беш эле кишини көрүп турам, — деп жигит каршы чыгат.","— Уулум, элүү кишинин ар бирине өзүнчө чалдым. Ар бирине сенин атыңдан чалып жатканымды, азыр башыңда көйгөй бар экенин, досторуңдун жардамына муктаж экениңди айтып, ушул убакта ушул жерде болушун өтүндүм. Сен эч кабатыр болбо, уулум. Сенин чыныгы досторуң бүгүн бул жерде, жаныңда!","Сабак: Чыныгы дос кыйынчылыкка кабылганда жаныңда болот. Көп тааныштан сыналган аз дос артык.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"people-who-need-something-from-you","title":"Сизге иши түшкөн адамдар","paragraphs":["Сизди «иши түшкөндө гана издеген» адамдарга таарынгандын ордуна, алардын башына кыйынчылык түшкөнүн, жардамыңызга муктаж болушу мүмкүн экенин жана дал ошон үчүн сизди издеп жатканын ойлосоңуз, көңүлүңүз кыйла тынч болот.","Сабак: Сага иши түшкөндө гана кайрылгандарга таарынба. Сага ишенип келгенин ойлосоң, жүрөгүң тынч болот.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"to-meet-and-to-know","title":"Таанышуу жана таануу","paragraphs":["Айрымдар жөнүндө муну гана айтууга болот:","Тааныштык — сүйүндүк, тааныдык — капа болдук.","Сабак: Таанышуу сүйүнтүшү мүмкүн, бирок адамды жакындан тааныганда кээде капа болосуң. Ар кимди кандай болсо, ошондой көрүү оңой эмес.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"discussion-and-conflict","image":"wisdom-stories/Bakhtiyar%20Sirajov/illustrations/discussion-and-conflict.webp","title":"Талкуу жана жаңжал","paragraphs":["Күн сайын болгондой эле, бүгүн да Жавид мырза менен анын тобу иштеп жаткан долбоордун абалын талкуулоо үчүн жыйын бөлмөсүнө чогулушту. Ар ким мурунку күнү жетишкен ийгиликтери жана туш болгон кыйынчылыктары тууралуу кыскача маалымат берип жатты.","Кезек Камалга келди. Ал да башкалардай аткарган иштери боюнча отчёт берди, бирок кесиптештеринен жардам күткөндөй, туш болгон көйгөйүн кененирээк түшүндүрдү. Сөзүн бүтөрү менен Надир айыптаган үн менен: «Күнөөлүү өзүңсүң, сенин айыңдан биздин да иш токтоп, эч нерсе кыла албай жатабыз», — деп баарынын көзүнчө Камалды айыптап тилди. Бөлмөдөгүлөр катып калышты. Камал өзүн коёрго жер таппай, эмне кыларын билбей турду.","Долбоордун жетекчиси катары Жавид мырза бул сөз күчөп, жаңжалга айланып кетпесин деп дароо кийлигишти да топко кайрылды: «Балдар, келиңиздер бүгүнкү талкууну бүтүрөлү, бул маселени болсо өзүнчө бир убакта чечебиз». Баары тарап кетти.","Жавид мырза эмне кыларын жакшы билчү: жекече жолугуп, достук маанайда сүйлөшүү. Ал Надирди бир чыны чай ичели деген шылтоо менен компаниянын кафесине чакырды. Аркы-беркини сүйлөшкөндөн кийин негизги маселеге өтүп, токтоолугун жоготпой, жай гана мындай деди: «Уулум, бүгүн Камалга жасаган мамилең абдан туура эмес болду. Иштин чоо-жайын билбей туруп кимдир бирөөнү, анын үстүнө башкалардын көзүнчө күнөөлөө — жарабаган иш. Өзүңдү анын ордуна коюп көр. Адам бизден жардам күтүп турганда айыпталат. Камал биз чогуу отуруп ойлонуп, маселенин чечимин бирге табабыз деп күткөнүнө ишенем».","Надир уялганынан башын жерге салды. Жавид мырзанын насааты жемишин берип, Надир үчүн жакшы сабак болду; ал туура эмес иш кылганын түшүндү.","Кийинчерээк Надир бул маекти эстеген сайын Жавид мырзага ыраазычылык билдирчү. Ал дагы бир себептен ыраазы болчу — компанияда бул сүйлөшүү жөнүндө эч ким билген эмес.","Сабак: Жаңжалда кимдин туура экени, талкууда болсо эмненин туура экени иликтенет. Чындыкты тапкың келсе, талашпа, талкуула.","Бахтияр Сиражов"],"hasAudio":false,"hasImage":true},{"stem":"spend-your-time-with-people","title":"Убактыңды адамдар менен өткөр","paragraphs":["Атам акча которушу керек болгондуктан, аны менен банкта бир саат отурууга туура келди. Акыры чыдамым түгөнүп, ага мындай дедим:","— Ата, банктагы иштериңизди интернет аркылуу эле бүтүрөлү. Кандай дейсиз?","— Мунун мага кандай пайдасы бар, уулум? — деп атам таң калып мени карады.","— Акча которуш үчүн банкта бир саат убактыңызды коротпойсуз. Атүгүл керектүү буюмуңузду да интернеттен сатып ала аласыз. Баары абдан оңой жана ыңгайлуу болот, — деп шашыла жооп бердим.","Атамды интернет дүйнөсүнө тарта алам деген демилге мени аябай шыктандырып турган.","Атам сурады:","— Эгер сен айткандай кылсам, анда үйдөн сыртка чыгуунун да кереги болбой калабы?","— Ооба, дал ошондой, ата.","Мен ага азык-түлүктү да эшикке чейин жеткирип беришерин, Amazon компаниясы сатып алган нерсенин баарын кардардын үйүнө жеткирерин айттым.","Атамдын жообун укканда тилим байланып калды:","— Уулум, банкта өткөргөн бир сааттын ичинде төрт досумду көрдүм, мени көптөн бери жакшы тааныган банк кызматкерлери менен сүйлөштүм.","Өзүң билесиң, мен жалгызмын... Мага адамдарды көрүп туруу керек. Кийинип алып банкка келгенди жакшы көрөм. Убактым жетиштүү, жандуу баарлашуудан дайыма ырахат алам.","Эки жыл мурун ооруп калганымда, дайыма мөмө-жемиш сатып алган жакынкы дүкөндүн сатуучусу мени көргөнү келди. Ооруганыма аябай кейип, керебетимдин жанында отуруп, абалыма ортоктош болду.","Бир аз убакыт мурун апаң эртең менен сейилдеп жүрүп жыгылып калганда, конушубуздагы дүкөнчү аны тургузуп, машинасына отургузуп, дароо үйүбүзгө жеткирип койгон. Анткени кайда жашарыбызды билчү.","Эгер баары онлайн болуп калса, мен ушундай адамдык сезимдерден ажырап калбаймынбы?","Баарын үйүмө чейин жеткирип беришсин деп, эмне үчүн компьютер менен гана байланышта болушум керек?","Мен «электрондук сатуучунун» ордуна, баарлашкан адамымды таанып-билгим келет. Мага жандуу байланыш, адамдык мамиле керек.","Amazon муну да жасай алабы?","Технология — жашоо эмес.","Убактыңды түзмөктөр менен эмес, адамдар менен өткөр, уулум.","Сабак: Технология ыңгайлуулук берет, бирок жашоону алмаштыра албайт. Чыныгы баа жандуу баарлашууда, адам менен адамдын ортосундагы жылуулукта.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"permission-or-apology","title":"Уруксатпы же кечирим сурообу","paragraphs":["Авторлугу контр-адмирал Грейс Хопперге таандык деп эсептелген «уруксат сурагандан көрө кечирим сураган жакшы» деген сөз бар.","Бул сөз «бир ишти аткаруу үчүн алдын ала уруксат сураба — ишти бүтүр, анан нааразы болгон адам чыкса, кечирим сура» деген мааниде колдонулат.","Кээде уруксат күтүп отуруп, мүмкүнчүлүктү колдон чыгарып жибересиң. Туура деп билгениңди жаса, керек болсо кийин кечирим сура.","Элестетиңиз: бир компанияда иш жүрүшүн жайлаткан айкын көйгөй бар. Мисалы, жума сайын бир эле маалымат кол менен бир нече башка таблицага көчүрүлүп, ага бир нече саат кетет. Кызматкерлердин бири муну жөнөкөй автоматташтыруу аркылуу чечсе болорун түшүнөт.","Эгер ал адегенде узакка созулган уруксат алуу жолуна түшсө, маселе бир жетекчиден экинчисине өтүп, жоопту жумалап күтүп, мүмкүнчүлүк колдон чыгып кетиши мүмкүн. Бирок кызматкер коркунуч аз экенин көрүп, учурдагы маалыматтарга зыян келтирбеген өзүнчө сыноо тутумун түзөт, ишти автоматташтырып, натыйжасын көрсөтөт. Тутум ийгиликтүү болсо, анын пайдасын баары көрөт. Кимдир бирөө жол-жобо алдын ала макулдашылбаганына нааразы болсо, кызматкер: «Ишти тездетүү үчүн сынап көрдүм. Эгер эрежени бузган болсом, кечирим сурайм», — дей алат.","Сабак: Демилгелүү болуу эрежени тоготпоо деген эмес. Катаны оңдоого мүмкүн болгон, коркунучу аз жана пайдасы ачык көрүнгөн учурда уруксатты көпкө күтүү демилгени өчүрүшү мүмкүн. Кээде жоопкерчилик менен ишти баштап, натыйжаны көрсөтүү чексиз макулдукту күткөндөн пайдалуу.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"gossip","title":"Ушак","paragraphs":["Ачуу тилдүү, адепсиз бир адам ушак таратты деп айыпталып, айыл аксакалынын алдына чакырылды.","— Бул жөн гана тамаша болчу, болгону тамаша, — деп ал айыбын четке какты. — Сөздөрүмдү башкалар туура эмес түшүнүп алышты, мен күнөөлүү эмесмин!","Бирок ушактан жабыркаган тарап айтканынан кайткан жок:","— Таза атыма көө жаптың. Адилеттик талап кылам.","Күнөөлүү адам кысым күчөгөн сайын артка чегинди:","— Айткандарымдын баарын кайра алам, мени кечирүүнү сурайм.","Аксакал үн катпай угуп турду. Ичинен: «Бул адам кылган ишинин оордугун али түшүнө элек. Убакыт өтсө, ошол эле күнөөнү кайра кайталайт», — деп ойлоду. Анан ага мындай деди:","— Базар аянтына куштун жүнү салынган бир жаздык алып бар. Аны жарып, ичиндеги жүндөрдү тегерекке чач. Андан кийин ошол жүндөрдүн баарын бирден терип, мага алып кел. Муну аткара албасаң, кечирим жок.","Ал киши аксакалдын шартын көңүлсүз кабыл алды. «Чал акылынан айнып калыптыр», — деп ойлонуп, жаздыкты аянтка алып келип жарды. Жүндөр бир соккон желге туш тарапка чачылып учту. Ал оңго да, солго да чуркап, жүндөрдүн артынан түштү; бирок канчалык аракет кылбасын, акырында алаканында бир нече жүн гана калды.","Башын жерге салып, аксакалга кайтып келди:","— Калганын чогулта албадым.","Анан терең үшкүрүп:","— Өзүм тараткан сөздөр сыяктуу экен. Аларды да эми кайра жыйнай албайм, — деди.","Сабак: Ушак — желге учкан жүн: чачкандан кийин кайра жыйнай албайсың. Ошон үчүн ушактан алыс бол.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"mockery-is-unacceptable","title":"Шылдыңга жол берилбейт","paragraphs":["Башка адамдардын өзгөчөлүгүн же сырткы көрүнүшүн шылдыңдап, аларды басынтууга болбой турганын балдарыбызга эң кичинекей кезинен үйрөтүшүбүз керек.","Сабак: Бирөөнүн өзгөчөлүгүн же келбетин шылдыңдоо — пастык. Муну балдарыбызга эң кичине кезинен үйрөтүшүбүз керек.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"why-people-shout-when-they-argue","title":"Эмне үчүн адамдар талашканда кыйкырышат?","paragraphs":["Бир күнү сабак учурунда мугалим студенттерине суроо берди:","— Эмне үчүн адамдар талашканда кыйкырышат?","— Анткени ачуусун тыя алышпайт, — деп жооп берди бир студент.","— Бирок талашып жаткан адамың жаныңда. Эмнеге кыйкырасың? Ачуулансаң да, аны менен жай сүйлөшө албайсыңбы? — деп мугалим суроосун тереңдетти.","Студенттердин ар бири өзүнчө жооп берди, бирок эч бири мугалимди канааттандырган жок. Акыры ал мындай деди:","— Адамдар бири-бирине нааразы болуп, талаша берген сайын жүрөктөрү да бири-биринен алыстай берет. Ушунча аралыктан бири-бирин угуш үчүн алар кыйкырууга аргасыз болушат. Канчалык катуу кыйкырышса, демек, жүрөктөрү да ошончолук алыстап кеткен.","Бир аз унчукпай тургандан кийин мугалим сөзүн улады:","— Ал эми адамдар бири-бирин сүйгөндө эмне болот? Алар кыйкырышпайт, тескерисинче, акырын сүйлөшөт. Анткени жүрөктөрү бири-бирине абдан жакын, ортодогу аралык аз. Сүйүү андан да күчтүү болсо эмне болот? Анда акырын да сүйлөбөй, шыбырашат жана бири-бирине дагы жакындай түшүшөт. Жүрөктөрү жакындаган сайын шыбырашууга да муктаж болбой калышат — бири-бирин карап эле баарын сөз айтпастан түшүнүшөт... Урматтуу студенттерим, силер да талашканда жүрөгүңөрдүн бири-биринен алысташына жол бербегиле, ортодогу аралыкты чоңойто турган сөздөрдү айтпагыла.","Анткени күндөрдүн биринде ал аралык ушунчалык чоңоюшу мүмкүн — кайра кайтар жолду таппай каласыңар.","Сабак: Кыйкырык — жүрөктөрдүн бири-биринен алыстаганынын үнү. Сүйүүдө шыбыр жетиштүү — ортоңордогу аралыкты чоңойтпогула.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"sound-of-the-doorbell","title":"Эшик коңгуроосунун үнү","paragraphs":["Өткөн кышта жумуштан бошоп калдым. Жан багыш үчүн убактылуу гезит ташуучу болуп иштөөгө туура келди. Гезит жеткирген үйлөрүмдүн биринин почта кутусу бекитилип тургандыктан, эшигин кактым. Эшикти карыя ачты.","— Аксакал, почта кутусун эмнеге бекитип салдыңыз? — деп сурадым.","— Атайылап бекиттим, — деп жооп берди ал.","Анан таң калычтуу жылмайып, сөзүн улады:","— Сизден өтүнөм, күн сайын гезит алып келгенде эшикти каккылап же коңгуроону басып, өз колума тапшырыңызчы.","— Албетте, бирок бул экөөбүзгө тең ыңгайсыз, убакытты алат го, — дедим таң калып.","— Эч нерсе эмес, мен күн сайын үйдө болом, — деди да, кошумчалады:","— Аялым кайтыш болуп кеткен, уулум чет өлкөдө. Бул жерде жалгыз жашайм. Ким билет, дагы канча өмүрүм калды?","Ошондо карыянын мунарык тарткан нымдуу көздөрүн көрдүм.","— Сиз гезит окуш үчүн жазылган эмессизби? — деп сурадым.","— Мен гезитти эч качан окубайм... Эшик коңгуроосунун үнүнө гана жазылгам.","Анан алакандарын бириктирип:","— Жигит, мага бир жакшылык кылчы! Мына, уулумдун телефон номери. Бир күнү эшикти каккылап, менден жооп ала албасаң, уулума чалып кабар бер, — деди.","Сабак: Айрым адамдар үчүн бир коңгуроонун үнү, бир салам бүт дүйнөгө тете. Жалгыздардын эшигин каккылоону унутпайлы.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true}]},{"title":"Адеп жана мүнөз","slug":"exlaq-ve-xarakter","blurb":"Ак ниеттүүлүк, жоомарттык жана жеке бүтүндүк.","count":42,"stories":[{"stem":"dont-say-i-couldnt-deliver-or-i-couldnt-manage","title":"«Жетишпедим, колуман келбеди» дебегиле","paragraphs":["Күндөр бири-бирин алмаштырат. Бирөө күнүн бактылуу, бирөө кайгылуу аяктайт. Бирок кандай болгон күндө да, бүгүн бүтүрө албай калган ишиңер үчүн «жетишпедим, колуман келбеди» деп рухтан түшпөгүлө. Эң башкысы — үмүтүңөрдү үзбөгүлө. Эртеси күн чыгып келери менен бүтүндөй күн силердики.","Сабак: Ар бир күн — жаңы барак. Кечээни өзгөртө албайсың, бирок бүгүнкүнү кантип жазарың өз колуңда.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"being-human","title":"Адам болуу","paragraphs":["«Аалым болуу оңой, адам болуу кыйын» — деген сөздү көп угабыз. Анда адам болуу деген эмне?","Адам болуу — изги, даанышман, маданияттуу, адилет, ар-намыстуу жана татыктуу жашоо.","Адептүү, сылык, зирек жана жөнөкөй болуу; өзүңдү мактабай, башкаларды урматтоо.","Ар бир ишти акылга салып, ченемди билүү; ишиңде ырааттуу болуп, кыйынчылыкка моюн сунбоо.","Сөзүңө туруу; акчага жана кызматка табынбоо; уурдабоо жана бирөөнүн акысын жебөө.","Калп айтпоо, жалаа жаппоо, жеке кызыкчылык үчүн башка бирөөнү сатпоо жана акыйкатты коргоо.","Эки жүздүүлүктөн, кектен жана адамдарды бири-бирине тукуруудан алыс болуп, сүйө билүү.","Сабак: Адамдын баркы билиминен эле эмес, адамгерчилигинен да билинет. Өзгөнү сыйлай билген жүрөктө сүйүү да, адилеттик да болот.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"that-was-not-your-right","title":"Ал сенин акыңа жатчу эмес","paragraphs":["Чанаккале салгылашында аман калууга мүмкүнчүлүгү бар жарадарларга гана морфин сайышчу экен. Дарыгер Тарык Нусретке алып келген оор жарадарлардын бири өз уулу болуп чыгат. Баласынын өмүрүн сактап калуу мүмкүн эмес экенин көргөн ата ага ийне сайбайт. Эки сааттан кийин шейит кеткен уулунун жансыз денесин кучактаган ата: «Мени кечир, уулум, ал сенин акыңа жатчу эмес», — деп шыбырайт.","Сабак: Кээде эң чоң адилет — адамдын өз кызыкчылыгына каршы турушу. Акыкты билген ата өз баласына да адилетсиз үлүш бербейт.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"you-cannot-descend-a-well-on-his-rope","title":"Анын арканы менен кудукка түшүүгө болбойт","paragraphs":["Илгери зыгыр буласынан аркан жасаган Али аттуу уста болуптур. Ишин сапатсыз жасагандыктан, анын аркандары көбүнчө чирик чыкчу экен. Атүгүл аны «арканы чирик уста Али» деп атап коюшуптур. Уста Алинин аркандары тез-тез үзүлүп, көп кырсыкка себеп болчу экен.","Күндөрдүн биринде терең кудукка козу түшүп кетет. Козуну алып чыгыш үчүн кудукка түшмөк болгон бир таанышы козунун ээсинен аркан сурайт, бирок алып келген арканын жактырбай:","— Мен бул арканды тааныйм. Бул — уста Алинин жасаганы. Анын арканы менен кудукка түшүүгө болбойт, — деп нааразы болот.","— Адилетсиз айтпаңыз. Уста Алинин арканы менен кудукка түшсө болот; бирок ошол эле аркан менен кайра чыгууга болобу-жокпу, аны айта албайм, — деп козунун ээси жылмайып жооп берет.","Сабак: Кылган ишиңдин сапаты сага ишеним алып келет, сапатсыз иш болсо атыңды кадырдан түшүрөт. Бир жолу кеткен ишенимди кайра табуу кыйын.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"not-every-sorrow-is-told-to-people","title":"Ар бир муңду адамдарга айта бербейт","paragraphs":["Ар бир муңду адамдарга айта бербейт.","Күн келет, ошол муңуң менен сени урат.","Сабак: Сыр айтар адамыңды тандай бил. Ар кимге ачылган муң кийин өзүңө каршы колдонулушу мүмкүн.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"everything-is-in-our-own-hands","title":"Баары өз колубузда","paragraphs":["(Индия фольклорунан)","Бир жаш жигит кары кечилди шаштырмак болот. Ал куш кармап, алаканына кысып, колун артына жашырат да, кечилден сурайт:","— Оо, даанышман карыя, айтчы, менин колумдагы куш тирүүбү же өлүүбү?","Ичинен болсо: эгер карыя «тирүү» десе, кушту муунтуп өлтүрөм; ал эми «өлүү» десе, алаканымды ачып учуруп жиберем да, аны уят кылам, — деп ойлойт.","Даанышман карыя бир аз ойлонуп туруп мындай дейт:","— Кымбаттуу уулум, сурооңдун жообу өз колуңда.","Жигит аң-таң болуп, башын ылдый салат.","Карыя сөзүн улантат:","— Согуш менен тынчтык, жаза менен кечирим, жакшылык менен жамандык — мунун баары өз колуңда. Адамдын өмүр жолун анын акылы эмес, ниети аныктайт. Ар бир адам жакшылык да, жамандык да кылууга кудуреттүү экенин унутпа. Бирок ар дайым тандоо бар, ал тандоо да өзүбүздүн колубузда.","Сабак: Жакшылыкка да, жамандыкка да адам өзү кадам таштайт. Тагдырыбызды акылыбыз эмес, ниетибиз аныктайт.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"who-handles-honey-licks-his-finger","title":"Бал кармаган бармагын жалайт","paragraphs":["Бир балчы чогулткан балын сатыш үчүн идиштерге куюп, дүкөнчүгө алып келет. Соодалашып, баасын макулдашкандан кийин балды таразага тарта башташат.","Дүкөнчүнүн бир килограммдык гана тараза ташы бар экен. Ал бал толгон мом уяларды колу менен бөлүп, таразанын табагына салып тартат. Ар бир бөлүктү салган сайын балга булганган манжаларын жалап коёт.","Бир жолу, эки жолу, үч жолу... Балчы караса, балынын бир бөлүгү таразага жетпей эле дүкөнчүнүн манжаларында калып, оозуна кетип жатыптыр. Кабагын бүркөп, нааразылыгын билдирет. Дүкөнчү болсо ага эч көңүл бурбай, манжаларын жалай-жалай балды тарта берет.","Акыры балчынын чыдамы түгөнөт:","— Ай, байке, минтип кылганыңыз болбойт да, балдын жарымын жалап бүттүңүз!","Бал болгон манжаларын жалаганын токтотпогон дүкөнчү жылмайып, кыңырайып жооп берет:","— Ай, тууган, менин жаман оюм жок. Бал кармаган бармагын жалайт.","Сабак: Адам ишке четинен гана аралашса да, аралашкан ишинен аздыр-көптүр пайда көрөт.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"honey-or-dry-bread","title":"Балбы же каткан нанбы","paragraphs":["Наадан менен отуруп бал жегенче, аалым менен отуруп каткан нан же.","Сабак: Жанында отурган адам сени көтөрүшү да, түшүрүшү да мүмкүн. Наадан менен бал жегенден көрө, аалым менен каткан нанга канаат кылган жакшы.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"to-give-up","title":"Баш тартуу","paragraphs":["«Баш тартуу — сонун сапат!»","Кадыр-баркыңды билбегенден,","чын пейилди тебелегенден,","пайда үчүн өзгөргөндөн,","текеберликке толгон мактанчаактан,","көрө албастык кылып, ушак айткандан,","калпты адат кылгандан,","адеп-ахлак эмне экенин билбегенден,","баалуулуктарын жок кылгандардан,","наадандык менен билимсиздикке көз жумгандардан,","мекенин кемсинтип, улутун тангандан,","эне тилин унуткандардан,","эненин мээриминен, атанын кадырынан, баланын сүйүүсүнөн ажыраган адамдан...","«Баш тартуу — сонун сапат!»","өзүнөн баш тартууга болбойт деп ойлогондон...!","Сабак: Айрым адамдардан алыстоо — алсыздык эмес, өзүңдү сыйлоо. Кадыр-баркыңды билбегенге таянбоо да жакшы сапат.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"other-peoples-opinions","title":"Башкалардын ойлору","paragraphs":["Адам баласы бир күнү үтүрдү (,) жоготту. Айткандары бири-бирине аралашып кетти. Башка бир күнү чекитти (.) жоготту. Ойлору улана берип, аларды бири-биринен ажырата албай калды. Дагы бир күнү илеп белгисин (!) жоготту. Кубанычынан, ачуусунан, бардык сезимдеринен айрылды. Анан суроо белгисин (?) жоготту. Суроо бергенди унутуп, баарын кандай болсо, ошондой эле суроосуз кабыл алууга аргасыз болду. Дагы бир күнү кош чекитти (:) жоготту. Түшүндүрүп, чечмелеп берүү жөндөмү жок болду.","Өмүрүнүн аягына жеткенде колунда тырмакчалар гана калган эле — алардын ичинде болсо башкалардын ойлору гана бар болчу.","Сабак: Өз баалуулуктарын жана тамырын биринен сала жоготкон адамдын ичи жат ойлорго толот. Руханий тамырыңды сактабасаң, акыры өзүң болбой каласың.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"education-or-character","title":"Билимби же мүнөзбү","paragraphs":["Падыша вазиринен сурайт:","— Вазир, билим маанилүүбү же мүнөзбү?","Вазир ойлонбой жооп берет:","— Мүнөз, падышам.","Падыша өлкөгө жар салдырып, эң мыкты жаныбар үйрөтүүчүнү таап, алдына алып келүүнү буйруйт. Андай адамды таап келишет. Падыша андан сурайт:","— Мышыкты таманына табак карматып, жыйында кызмат кылууга канча убакта үйрөтө аласың?","— Алты айда, падышам.","Алты ай өтөт. Ал киши үйрөткөн мышыгы менен сарайга чакырылат. Падыша сурайт:","— Үйрөттүңбү?","— Үйрөттүм, падышам.","Сарайдагылардын баары чогулат. Мышык таманына табак кармап, аларга кызмат кыла баштайт. Мышык вазирге жакындаганда падыша сурайт:","— Вазир, билим маанилүүбү же мүнөзбү?","Вазир падышага жооп берерден мурда чөнтөгүндө даяр кармап турган чычканды алып чыгып, жерге коё берет. Чычканды көргөн мышык табакты таштап, артынан кууп жөнөйт.","Вазир падышага жооп берет:","— Мүнөз, падышам.","Сабак: Билим мүнөздү өзгөртпөйт; мүмкүнчүлүк түшкөндө чыныгы табият ачылат. Билимдүү болуу жакшы, бирок мүнөз андан да маанилүү.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"avoid-these-questions","title":"Мындай суроолорду бербеңиз","paragraphs":["Жумушсуз адамдан «Дагы эле жумушсузсуңбу?», иштегенден «Айлыгың канча?», баласы жоктон «Дагы эле балалуу боло элексиңерби?», бойдок же турмуш курбаган адамдан «Качан баш кошосуң?» деп суроодон алыс бололу.","Ошондой эле кимдир бирөөнү «Сен муну билчү эмес белең?» деген суроо менен уят кылбайлы. Бизге жөнөкөй көрүнгөн суроо башка адамдын эң сезимтал жарасын козгошу мүмкүн.","Сабак: Айрым суроолор жүрөктү оорутат. Мындай суроону бербей коюу бирөөнү капа болгондон сакташы мүмкүн.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"do-not-complain-about-any-day-you-have-lived","title":"Жашаган бир да күнүңүзгө нааразы болбоңуз","paragraphs":["Жашаган бир да күнүңүзгө нааразы болбоңуз:","жакшы күндөр бакыт тартуулайт,","жаман күндөр тажрыйба берет,","эң жаман күндөр сабак берет,","эң жакшы күндөр эскерүү тартуулайт.","Сабак: Ар бир күн адамга бир нерсе берет: жакшы күн кубаныч, жаман күн тажрыйба, эң жаман күн сабак, эң жакшы күн болсо унутулгус эскерүү. Жашаган бир да күнүңдү текке кетти деп эсептебе.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"mature-person","title":"Жетилген адам","paragraphs":["Бир мезгил келет: эски достордун чынчылдыгын көбүрөөк баалап, куру тааныштыкка умтулбай, наадан адамдардан жана сени ичинен чарчаткан мамилелерден алыс болосуң. Дал ошондо өзүң жетилип калганыңды түшүнөсүң.","Сабак: Кемелдик — сага зыян келтирген мамилелерден алыстап, ички тынчтыгыңды сактай билүү. Кимден жана эмнеден алыс болорун билүү да кемелдиктин белгиси.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"may-your-face-always-smile","title":"Жүзүңүздөн жылмаюу кетпесин","paragraphs":["Жүзү жайнап уксус саткан адамдын кардары кабагын бүркөп бал саткан кишиникинен көп болот.","Сабак: Жылмайган адам кабак бүркөгөндөн көбүрөөк сүйүлөт. Жылмаюу чыгым талап кылбайт, бирок жүрөктөрдү багындырат.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"goose-to-be-plucked","title":"Жүнү жулуна турган каз","paragraphs":["Кыштын кычыраган суук күндөрүнүн биринде падыша кийимин алмаштырып, башкы вазирин ээрчитип, сейилдөөгө чыгат. Бир топ жүргөндөн кийин сайдын боюнда иштеп жаткан карыяга жолугушат. Ал колундагы терилерди сууга салып, ургулап ийге келтирип жаткан экен.","Падыша карыяга салам берет:","— Ассалоому алейкум, эй пири фани.","— Алейкум ассалам, эй сардар-и жахан, — деп карыя да саламын алат. Падыша сурайт:","— Алтыда эмне кылдың?","— Алтыга алтыны кошпосоң, отуз экиге жетпейт, — деп жооп берет.","Падыша дагы сурайт:","— Түнкүсүн такыр турган жоксуңбу?","— Турдук, падышам... бирок эл-журтка пайдасы тийди...","Падыша күлүп, акыркы суроосун берет:","— Бир каз жиберсем, жүнүн жуласыңбы?","— Албетте, жулам, үнүн да чыгарбай, — деп жооп берет карыя.","Падыша менен башкы вазир карыянын жанынан кетип, жолун улантышат. Падыша башкы вазирден сурайт:","— Эмне жөнүндө сүйлөшкөнүбүздү түшүндүңбү?","— Жок, падышам, — деп башкы вазир кабатырлана жооп берет.","Падыша ачууланат:","— Бүгүн кечке чейин эмне сүйлөшкөнүбүздү түшүнбөсөң, башыңды алдырам.","Коркуп кеткен башкы вазир падышаны сарайга жеткирген соң, шашыла сайдын боюна кайтып келет. Карыя дагы эле ошол жерде иштеп жаткан экен.","— Падыша менен эмне жөнүндө сүйлөштүңүз? — деп башкы вазир карыяга кайрылат.","Карыя башкы вазирди башынан аяк кунт коюп карап чыгат:","— Кечир, бекер айтпайм. Жүз алтын берсең, айтып берем, — дейт.","Башкы вазир жүз алтын берет.","— Сен падышага «сардар-и жахан» деп салам бердиң. Анын падыша экенин кайдан билдиң?","— Мен тери иштетем. Анын үстүндөгү тонду падышадан башка эч ким кие алмак эмес.","Вазир башын кашыйт:","— «Алтыга алтыны кошпосоң, отуз экиге жетпейт» дегениң эмнени билдирет?","Карыя бул суроого жооп бериш үчүн дагы жүз алтын алат:","— Падыша: «Алты айлык жылуу мезгилде иштеген жок белең, кыштын ушул суугунда эмнеге иштеп жатасың?» — деп сурады. Мен: «Жайында алты ай, кышында да алты ай иштебесек, отуз эки тиштин оокатын таба албайбыз.», — дедим.","Башкы вазир сөзүн улантат:","— «Түнкүсүн такыр турган жоксуңбу?» дегени эмнени билдирет?","Карыя дагы жүз алтын алат:","— Падыша: «Балдарың жокпу?» — деп сурады. «Бар, бирок баары кыз; турмушка чыгып, башкалардын үйүнө пайдасы тийди», — деп жооп бердим.","Башкы вазир башын жерге салат:","— Анан «каз жиберсем» деди... ал эмнени билдирет?","Карыя күлүп, башкы вазирге:","— Аны өзүң тап, — дейт.","Сабак: Акылдуу сөз аны түшүнгөнгө ачылат. Ар ким укканын түшүнө бербейт — айрым жоопторду адам өзү табышы керек.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"explaining-ones-sorrow","title":"Кайгыны билдирүү","paragraphs":["Кайгысын жөн айтып берген — муңдуу адам; көркөм сөзгө салган — адабиятчы; абалынан сездирген — ашык; жылмаюусуна жашырган — даанышман.","Сабак: Ар ким кайгысын ар башкача көтөрөт. Бирөө сүйлөйт, бирөө жазат, бирөө унчукпай жылмаяйт. Эң терең кайгы көбүнчө эң терең унчукпоодо жашынат.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"telling-lies","title":"Калп айтуу","paragraphs":["— Калп айтасыңбы?","— Ооба.","— Ал кандай калп?","— Ал калпты өзүмө гана айтам. Башкача айтканда, күн сайын өзүмө: «Сен баарынан күчтүүсүң, баарынан билимдүүсүң, баарынан жөндөмдүүсүң», — деп айтам жана башка ушул сыяктуу сөздөрдү кайталайм.","— Балким, бул чынбы?","— Жок, мындай доомат чын болушу мүмкүн эмес. Анткени менден күчтүүсү да, жөндөмдүүсү да бар.","— Анда эмнеге өзүңө мындай калп айтасың?","— Ишенсең да, ишенбесең да, бул калп мага абдан чоң дем берет. Күчтүүрөөк, билимдүүрөөк болууга, өзүмдүн үстүмдөн дагы талыкпай иштөөгө шыктандырат.","Сабак: Кээде өзүңө айткан жакшы сөз — «колуңдан келет» — сени алдыга сүйрөгөн күчкө айланат. Адам өзүнө ишенгенге жараша күчтүү.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"expressions-you-should-stay-away-from","title":"Колдонбоо керек болгон сөздөр","paragraphs":["Бул сөздөрдөн алыс болуңуз, айрыкча үй-бүлөдө жубайыңызга карата аларды эч качан колдонбоңуз:","«Болбогонду сүйлөбө!»","Бул сөз жубайыңызга анын ой-сезимдерин баркка албай, өзүн басынтып, аны түшүнбөгөнүңүздү сездирип жаткандай угулат. Анын ордуна жумшак гана: «Мен сендей ойлобойм, бул маселеде сага толук кошула албайм», — десеңиз, өз оюңузду билдирип, ортоңуздардагы сый-урматты сактайсыз.","«Апыртпа!»","Бул сөз жубайыңыздын окуяга көз карашы туура эмес дегендей угулушу мүмкүн; ал өзүн сынга алынгандай сезет. Анын ордуна: «Эмне үчүн тынчсызданып жатканыңды, эмнени сезип жатканыңды бир аз такыраак түшүндүрүп бере аласыңбы?» — деп сурасаңыз, жаралган түшүнбөстүктү жоюуга кадам таштаган болосуз.","«Тигинин күйөөсүн (аялын) карачы! Ал тигинтип-мынтип жүрөт, а сенчи?»","Бул өтө кооптуу сүйлөм, анткени аны айтуу менен үй-бүлөлүк мамилеңиздерге үчүнчү адамдарды аралаштырасыз. Жубайыңызды башка бирөө менен салыштыруу анын ишенимин солгундатат. Ал сиздин оюңуз ошол адамда деп түшүнүп, намысы жабыркайт, өзүн сүйүлбөгөндөй сезет. Мындай салыштырып, окшоштуруунун ордуна эмнени күтөрүңүздү ачык түшүндүрүңүз.","«Сен түшүнбөйсүң!»","Бул — кемсинтүү: сиз жубайыңызды басынтып жатасыз. Эгер ал бул маселеде сизди түшүнбөйт деп ойлосоңуз же оюңузду бөлүшкүңүз келбесе: «Бул тууралуу сүйлөшкүм келбейт, таарынба, башка нерсе жөнүндө сүйлөшөлү» же «Бул сага кызык болбосо керек» дегениңиз ылайыктуураак.","«Ал жакка барба, аны менен сүйлөшпө, муну кылба, муну кийбе, антип сүйлөбө, муну алып кел, тигини ал!»","Жубайыңыз сизге баш ийген буйрук аткаруучу кул эмес. Каалабаган же жактырбаган нерсеңизди аны менен сый мамиледе кеңешип билдирсеңиз, чыр-чатактан алыс болосуз. Буйрук иретиндеги сүйлөмдөрдүн ордуна өтүнүчтү билдирген («суранам», «мүмкүн болсо» ж.б.) сөздөрдү колдонуңуз.","Сабак: Сөз эң көп сүйгөн адамыбызды жаралап алышы мүмкүн. Үй-бүлөдө буйрук менен кемсинтүү эмес, сый-урмат жана өтүнүч тили керек.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"generous-man","title":"Колу ачык адам","paragraphs":["Колу ачык бир адамдан сурашат:","— Жарды-жалчыга бөлүшкөн ырыскың үчүн ыраазычылык күтөсүңбү?","Ал мындай деп жооп берет:","— Мен өзүмдү ашпозчунун колундагы чөмүчкө окшотом. Тамак чөмүч менен бөлүштүрүлгөнү менен, аны берген чөмүч эмес, ашпозчу.","Сабак: Жакшылык кылган адам берген ырыскынын чыныгы ээси өзү деп ойлобошу керек. Ал болгону бир васита; чыныгы берүүчү — Аллах.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"turning-hardship-into-opportunity","title":"Кыйынчылыкты мүмкүнчүлүккө айлантуу","paragraphs":["Жашоодо кээде ишибиз ойдогудай жеңил жүрөт, кээде күтпөгөн кыйынчылыктарга туш болобуз. Эң маанилүүсү — жолуккан кыйынчылыкты мүмкүнчүлүккө айландыра билүү.","Сабак: Бир эле кыйынчылык бирөөнү сындырып, экинчисин чыңдайт. Тоскоолдуктан сабак алып, аны алдыга жылуу үчүн мүмкүнчүлүккө айлантууга аракеттен.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"strength-and-sorrow","title":"Күч жана кайгы","paragraphs":["Кудайым! Мага же тарткан кайгыма жараша күч бер, же күчүм жеткидей кайгы бер.","Мухаммед Фузули","Сабак: Адам кайгысына чыдай турган күч, же күчү жеткендей гана кайгы тилейт. Алың жетпеген жүктүн алдына кирбе.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"attitude-toward-a-problem","title":"Көйгөйгө мамиле","paragraphs":["Жашооңдо көйгөй барбы?","Жок болсо, тынчсыздануунун кереги жок.","Көйгөй бар болсо, аны чече аласыңбы?","Чече алсаң, тынчсыздануунун кереги жок.","Чече албасаң да, тынчсыздануунун кереги жок.","Сабак: Маселени чече алсаң, аракет кыл. Колуңдан келбеген нерсе үчүн өзүңдү тынымсыз кыйноонун пайдасы жок.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"meaningless-question","title":"Маанисиз суроо","paragraphs":["Бир күнү Беркли университетинин бүтүрүүчүсү Нью-Йоркто жашаган раввинге келип, Талмудду үйрөнүүгө жардам сурайт.","— Арамей тилин билесиңби? Жокпу? Иврит тилинчи? Жок дегенде бала кезиңде сага Тоорат окуп беришкенби?","Жигит бул суроолордун баарына терс жооп берет.","— Бирок мен Сократтын логикасы боюнча диссертация жактагам! Талмудду үйрөнүп, билимимдеги айрым боштуктарды толтургум келет.","— Талмуд — адамзат ой жүгүртүүсүнүн эң улуу эмгектеринин бири. Бирок сен аны үйрөнүүгө азырынча даяр эмессиң. Ошентсе да мынчалык өжөрлөнүп жатсаң, сага бир логикалык суроо берейин. Туура жооп берсең, сени окутам. Эки киши бир мор менен ылдый түшөт. Биринин бети таза, экинчисинин бети көөгө булганган. Кайсынысы барып бетин жууйт?","— Бул логикалык сурообу? — деп Берклинин бүтүрүүчүсү өзүнө ишене сурайт. — Албетте, бети кир киши барып жуунат!","— Туура эмес. Бети таза киши досунун кир бетин көрүп, өзүнүн да бети булганды деп ойлойт да жуунганы барат. Ал эми бети көөгө булганган киши маңдайындагы адамдын таза жүзүн көрүп, өзүм да таза калдым деп ойлойт.","— Кандай назик логика! Мага дагы бир мүмкүнчүлүк бересизби?","— Макул. Эки киши бир мор менен ылдый түшөт. Биринин бети кир, экинчисиники таза. Кайсынысы бетин жууганы барат?","— Муну азыр эле талкуулабадыкпы. Бети таза киши барат!","— Дагы жаңылдың. Экөө тең барып бетин жууйт. Бети таза киши досунун кир бетин көрүп, өзү да булганды деп ойлойт. Экинчиси болсо досу аны карагандан кийин жуунганы кеткенин көрүп, өзүнүн да бети кир экенин түшүнөт.","— Чын эле, муну ойлобоптурмун. Мага дагы бир суроо бере аласызбы?","— Макул. Акыркы жолу сурайм: эки киши бир мор менен ылдый түшөт. Биринин бети таза, экинчисиники кир. Кайсынысы бетин жууганы барат?","— Эми түшүнүктүү: экөө тең барат!","— Жок. Экөө тең барбайт. Бети кир киши маңдайындагы адамдын таза жүзүн көрүп, өзүм да тазамын деп ойлойт. Бети таза киши болсо досунун жуунганы барбаганын көрүп, мунун кереги жок экен деп эсептейт.","Үмүтү үзүлгөн жигит раввинден дагы бир суроо берүүсүн өтүнөт. Раввин сөз баштайт:","— Эки киши бир мор менен ылдый түшөт. Биринин бети кир, экинчисиники таза...","— Экөө тең бетин жууганы барбайт! — деп жигит шашып жооп берет.","— Дагы жаңылдың, — дейт раввин жай гана. — Сократтын логикасы боюнча адис катары өзүң ойлончу: бир мор менен чогуу түшкөн эки кишинин кантип бирөөсүнүн гана бети көөгө булгансын? Суроонун өзү маанисиз экенин көрбөй турасыңбы? Өмүрүңдү маанисиз суроолорго жооп издөөгө коротсоң, жоопторуң да, өмүрүң да маани таппайт.","Сабак: Маанисиз суроонун жообу адамды чындыкка алып барбайт. Туура суроо — туура жооптун жарымы.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"be-sure-of-your-purpose","title":"Максатыңыз анык болсун","paragraphs":["Эки киши оор сандыкты эшиктен өткөрүүгө аракет кылып жатышты. Көпкө алышкандан кийин терге чөмүлүп, токтоп дем алышты.","Бирөөсү айтты:","— Кандай оор сандык! Эч эле ичкери киргизе албай койдук.","Экинчиси таң кала сурады:","— Биз сандыкты сыртка чыгарышыбыз керек эмес беле?","Сабак: Ишке киришерден мурун эмне кыларыңды тактап ал. Болбосо, сааттап иштеп, бүт күчүңдү туура эмес жакка жумшап коюшуң мүмкүн.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"do-not-do-these-things","title":"Мунун баарын кылбаңыз","paragraphs":["Жакырдын жанында байлыгыңыз, оорулуунун жанында ден соолугуңуз, кайгылуунун жанында бактыңыз, камактагынын жанында эркиндигиңиз, алсыздын жанында күчүңүз, баласы жоктун жанында балаңыз, жетимдин жанында ата-энеңиз тууралуу сөз кылбаңыз.","Сабак: Бирөөнүн кем-карчын бетине салып, көңүлүн оорутпа. Анын муңун эскерткениң эмес, түшүнгөнүң керек.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"he-would-not-have-given-so-little","title":"Мынчалык аз бербейт эле","paragraphs":["Бир падыша жолдо жолуккан сүйкүмдүү балага бир алтын тыйын берет, бирок бала аны албайт. Падыша эмне үчүн албаганын сураганда, бала мындай дейт:","— Үйгө барганда апам менен атам: «Бул акчаны кайдан уурдадың?» — деп сурашат.","— Сен болсо муну падыша берди деп айтасың, — дейт падыша.","— Анда такыр ишенишпейт. «Падыша бергенде, мынчалык аз бермек эмес», — дешет, — деп жооп берет бала.","Бул жооп падышага абдан жагып, ал балага бир мүшөк алтын берет.","Сабак: Улуу иштер үй-бүлөдөн, туура тарбиядан башталат. Чынчыл өскөн бала эртең чынчыл адам болот.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"how-can-i-escape-my-thoughts","title":"Ойлорумдан кантип кутулам","paragraphs":["Күндөрдүн биринде бир адам өз доорунун таанымал аалымдарынын бирине келип сурайт:","— Мени туткундап алган азаптуу ойлордон кантип кутулам?","Аалым жооп берүүнүн ордуна ордунан туруп, жанындагы мамыны кучактай калат да, болгон күчү менен:","— Мени бул мамыдан ажыраткыла, андан куткаргыла!… — деп кыйкыра баштайт.","Ага таң кала караган киши сурайт:","— Эмнеге минтип жатасыз? Сизди даанышман адам деп, жардам сурап келгем. Бирок көрүп турам, даанышманга окшобойт экенсиз. Мамыны сиз өзүңүз кармап турасыз, ал сизди кармаган жок. Коё бериңиз, ошондо кутуласыз!","Аалым мамыны коё берип, ага мындай дейт:","— Өз сурооңо өзүң жооп бердиң. Ойлор сени эмес, сен аларды кармап турасың! Аларды коё бер, ошондо өзүң да кутуласың.","Сабак: Сени эзген ойлорду өзүң кармап турасың; аларды коё берүү да өз колуңда. Көз карашыңды өзгөртсөң, жүгүң жеңилдейт.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"dont-open-your-mouth","title":"Оозуңду ачпа","paragraphs":["Жакшы сөз айтпай турган болсоң, оозуңду такыр ачпа.","Сабак: Сөздүн күчү — аны орду менен жана жакшылык үчүн колдонууда. Айтаарлык сөзүң жок болсо, унчукпаган сөз катуураак сүйлөйт.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"think-speak-and-act-positively","title":"Жакшы ойло, жакшы сүйлө, жакшы иш кыл","paragraphs":["Жакшы ой ойлогула, анткени ой сөзгө айланат.","Жакшы сөз сүйлөгүлө, анткени сөз ишке жол ачат.","Жакшы иш кылгыла, анткени иш адатка айланат.","Жакшы адаттарды калыптандыргыла, анткени адаттарыңар баалуулуктарыңарды калыптандырат.","Баалуулуктарыңарды бийик кармагыла, анткени алар тагдырыңарга таасир этет.","Сабак: Ой сөзгө, сөз ишке, иш адатка, адат болсо тагдырга айланат. Жакшы тагдырдын башаты — жакшы ой.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"to-be-cool-headed","title":"Салкын кандуу болуу","paragraphs":["Туш болгон абалды дүрбөлөңгө түшпөй, сабыр менен баалаңыз. Ошондо туура чечим кабыл алып, жагдайды өз пайдаңызга бура аласыз.","Сабак: Эң туура чечим дүрбөлөңдө эмес, сабырдуу акыл менен кабыл алынат. Сабырдуулук кыйын абалды да өз пайдаңа бура алат.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"our-qualities-can-become-our-enemies","title":"Артыкчылыгыбыз өзүбүзгө кырсык болушу мүмкүн","paragraphs":["Тоостун душманы — өз куйругу…","Булбулду капаска түшүргөн — анын таттуу тили.","Түлкүнү тузакка түшүргөн — анын кооз териси…","Өзүбүздө жактырып сүйгөн айрым сапаттаркээде алсыз жерибизге айланып, башыбызга кырсык алып келет…","Сабак: Кээде мактанган сапатыбыз дал өзүбүздүн алсыз жерибиз. Тоосту куйругу, булбулду тили эле берет — артыкчылыгыңа ашкере ишенип кетпе.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"i-got-busy-with-cleaning","title":"Тазалыкка кириштим","paragraphs":["Бүгүн тазалыкка кириштим...","Бүт денеме да тазалык жүргүздүм...","Булчуңдарымды, нервдеримди, кан тамырларымды, атүгүл канымды да тазаладым...","Эң тереңде чогулуп калган бүт таштандымды ыргытып салдым...","Эң оболу көңүл калууларды чыгарып таштадым... Таштаганда алардын эмне экенине да караган жокмун.","Муну көрүшүңөр керек эле...","Ичимде ушунчалык чоң орун ээлеп алышкан экен...","Бошогон орунга кечирим сезимин этияттык менен жайгаштырдым. Ар бир таарынычтын ордуна кечиримдин үрөнүн септим...","Көрө албастыгымды чыгарып салдым...","Көрсө, кандай гана көрө албас адам болуптурмун...","Бул абдан оңой болду. Кубандым...","Жоготкон буюмумду кайра тапкандай болдум...","Кудайга шүгүр, жүрөгүмдө кек да, жек көрүү да жок экен...","Аны кантип тазалаганымды билбейм...","Эми кезек коркууларыма жетти...","Адегенде аларды алып чыгуудан да корктум...","Алар менен жашоого ушунчалык көнүп калыпмын...","Мынча азап менен тынчсызданууга кантип көнүүгө болорун түшүнө албадым...","Күн сайын ичимде жаңы тынчсыздануулардан жаралган жаңы коркуулар топтоло берчү...","Бакытым менен үмүттөрүмдү канчалык көп кийинкиге калтырыпмын...","Бактыма жана үмүттөрүмө өз убагында кам көрсөм кана. Үмүтүмдү күн сайын дагы бир аз арттырсам, ордуна эч нерсе күтпөй берсем, жооп күтпөй сүйсөм, эң негизгиси, ичимдеги сүйүү менен күчтүн баасын билсем, мындай тазалыктын кереги болмок эмес...","Коркууларымды тазалоо кыйын болду...","Алар чынжырдай бири-бирине чырмалып, дээрлик кулпуланып калыптыр... Бирок бир кезде ичимде коркунучтуу түш сыяктуу жашатып жүргөнүмө өкүнүп отурбай, аларды кууп чыктым.","Билем, эгер коркууларыма ачууланып, аларга кыйкырып-бакырсам, кайра айланып келип үстүмө түшмөк.","Бүгүн тазалыкка кириштим...","Кубанычтын, ишенимдин, сүйүүнүн үрөнүн септим...","Эч нерсе албай туруп берүүнү, сүйүлбөй туруп сүйүүнү, бөлүшүүнү септим...","Ичиме шашкындыкты, табигыйлыкты жана кечиримди септим...","Ар бир клеткама махабат септим...","Шыктанууну, толкунданууну, жымжырттыкты септим...","Бардык жакшы ойлор мага жымжырттыкта келет...","Кабыл алууну септим...","Баш ийүүнү эмес, болгонун болгондой кабыл алууну...","Сабак: Чыныгы тазалык жүрөктө болот: көңүл калууну, коркууну жана кекти таштап, ордуна сүйүү, кечирим жана үмүт себүү. Ички дүйнөсүн тазалаган адам рахат табат.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"no-one-listens-to-constant-complainers","title":"Тынымсыз даттанган адамды эч ким укпайт","paragraphs":["Көптү көргөн бир адам ошол эле көйгөйлөрүнө кайра-кайра даттанган бир топ кишиге мындай сабак берет. Ал күлкүлүү тамаша айтып берет; баары чын жүрөктөн каткырып күлөт. Ошол эле тамашаны экинчи жолу айтат; адамдардын бир бөлүгү гана күлөт. Үчүнчү жолу айтканда болсо, эч кимдин эрди да кыймылдабайт.","Чечим издегендин ордуна улам эле ошол көйгөйлөргө даттана берүү да ушуга окшош. Тынымсыз даттанган адамды эч ким укпайт.","Сабак: Бир эле даттанууну кайра-кайра угуу, бир эле тамашаны кайра угууга окшоп, адамды тажатат. Даттанууга кеткен күчтү айла табууга жумша.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"try-to-think-this-way","title":"Ушинтип ойлонууга аракет кылыңыз","paragraphs":["«Бул ишти жакшы кыла албайм» дебеңиз. «Балким, мен билбеген бир нерсе бардыр? Билимимди жаңылап, үстүндө иштесем, сөзсүз колуман келет», — деңиз.","«Бул иштен баш тарттым» дебеңиз. «Балким, муну башка жол менен чечүүгө болоттур? Аракет кылып көрөйүн, балким, ишке ашар», — деңиз.","«Бул иш өтө кыйын» дебеңиз. «Кыйын, бирок мүмкүнсүз эмес; бир аз кошумча убакыт жана эмгек талап кылат», — деңиз.","«Жасаганым мени канааттандырат, мындан жакшы кыла албайм» дебеңиз. «Өзүмдүн үстүмдө иштеп, өсүп, мындан да жакшы натыйжага жете алам», — деңиз.","«Ката кетирдим, аттиң, кылбашым керек эле» дебеңиз. «Бул дүйнөнүн акыры эмес; каталар мага үйрөнүүгө жардам берет», — деңиз.","«Ал өтө акылдуу, мен ага окшош боло албайм» дебеңиз. «Ал буга кантип жеткенин үйрөнүп, мен да ошондой ийгиликке жете алам», — деңиз.","Сабак: Оюңду өзгөртүү — жашооңду өзгөртүүнүн биринчи кадамы. «Колумдан келбейт» десең жол жабылат, «үйрөнөм» десең жаңы мүмкүнчүлүк ачылат. Ийгиликсиздик аягы эмес, өсүүгө мүмкүнчүлүк.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"flower-of-honesty","title":"Чынчылдыктын гүлү","paragraphs":["Бир ханзаада такка отурууга камынып жатыптыр. Бирок салт боюнча адегенде үйлөнүшү керек экен. Ылайыктуу жар тандоо үчүн өлкөдөгү эң сулуу кыздарды алдына чакыртат.","Сарай кызматчыларынын биринин кызы да ханзааданы сүйчү экен. Ал апасына ханзааданын алдына баргысы келерин айтат. Апасы аны бул оюнан кайтарууга аракет кылганы менен, кыз чечиминен кайтпай, сөзсүз барарын билдирет.","Күткөн күн келет. Сарайга чогулган жаш сулуулар эң кооз кийимдерин кийип, жасанып-түзөнүп, өздөрүн жактыруу үчүн колунан келгендин баарын кылышкан эле.","Ханзаада кыздардын ар бирине бирден үрөн берип, аны гүл идишке эгип, алты айдан кийин кайра алдына келүүнү тапшырат. Эң кооз гүл өстүргөн кызды тандап, ошого үйлөнөрүн айтат. Кыздар үрөндөрүн алып, толкунданып үйлөрүнө тарашат.","Сарай кызматчысынын кызы да алган үрөнүн гүл идишке эгет. Канчалык тырышып караса да, топурактан бир да өнүм чыкпайт. Ал бардык ыкманы колдонуп, багбандар менен кеңешет, бирок майнап чыкпайт. Алты ай бүткөндө кыз бош идишин көтөрүп сарайга келет. Калган кыздар болсо кооз гүлдөргө толгон идиштерин көтөрүп келишет.","Тандоо учуру келет. Ханзаада залга кирип, кыздардын арасын аралап, идиштерди бирден карап чыгат. Акырында кызматчынын кызын тандаганын бийик үн менен жарыялайт.","Баары аң-таң болот. Башка кыздар бул чечимге каршы чыгышат: бош идиш менен келген кыз кантип колуктулукка тандалсын?","Ханзаада чечиминин себебин мындай түшүндүрөт:","— Бул кыз эң баалуу гүлдү өстүрүп, мага алып келди. Ал гүлдүн аты — чынчылдыктын гүлү. Силерге тараткан үрөндөрдүн баары жалган болчу, алардан гүл өсүшү мүмкүн эмес эле.","Сабак: Чынчылдык — адамдын эң баалуу көркү. Адам сырткы келбети менен эмес, чын сөзү жана таза абийири менен бийиктейт.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"dont-be-words-for-mouths-dust-for-feet","title":"Эл оозуна сөз, эл бутуна чаң болбо","paragraphs":["«Эл оозуна сөз болуу» — адамдардын ушак-айыңына жана сөзүнө калуу.","«Эл бутуна чаң болуу» — өзүңдү басынтуу, өз баркыңды түшүрүү жана башкалардын бутунун астында калуу.","Сабак: Өз кадырыңды өзүң сакта. Ушакка жем болчу иштен алыс жүрүп, эч кимге өзүңдү тебелетпе.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"i-am-aware-now","title":"Эми түшүндүм","paragraphs":["Турмуштун ысык-суугун көргөн адамдын сөзүнөн:","Эми мени бирөө жакшы көрсүн деп аракет кылбайм. Мени жактырбаган адам ар дайым бир шылтоо табарын түшүндүм.","Эми өз баркымды билем жана өзүмдү эч кимге далилдөөгө милдеттүү эмес экенимди түшүндүм.","Мактанчаак жана текебер адамдарга мындан ары жашоомдон орун бергим келбейт деп түшүндүм.","Каалагандын максаты болот, каалабаганда дайыма «бирок» болот деп түшүндүм.","Ушакчы адам менен эми сырымды бөлүшпөйм, анткени ушакчы сыр сактай албасын түшүндүм.","Кежир адамды ишендирүүгө эми аракет кылбайм, анткени мындай адамды оюнан кайтаруу мүмкүн эмес экенин түшүндүм.","Калп айткан, куру убада берип, сөзүнө турбаган адамдардын жашоомдон чыгып кетишин кааларымды түшүндүм.","Кечире албаган, ырайымсыз жана катаал адамдардан эми алыс болом. Катасын түшүнүп, кечирим сурай билген адамдарды баалайм.","Кимдин жанында «өзүм» боло алсам, ошол адамдын жанында көбүрөөк бактылуу экенимди түшүндүм.","Сабак: Чыныгы жетилүү башкаларды өзгөртүүдө эмес, кимди жашооңо киргизип, кимден алыс болууну билүүдө.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"i-would-not-trade-it-for-anything","title":"Эч нерсеге алмашпайм","paragraphs":["Бир күндү,","кооз бир күндү,","күнөстүү бир күндү","эч нерсеге алмашпайм.","Анын үчүн согушту сүйбөйм,","анын үчүн зулумдукту сүйбөйм,","анын үчүн жалганды сүйбөйм.","Билем, күндүн жарыгында жашай албайт,","билем, сүйүү менен катар жашай албайт","адилетсиздик да,","коркуу да,","ачарчылык да...","Нежати Жумалы","Сабак: Кооз, күнөстүү күндө чыр-чатакка, зулумдукка жана жалганга орун жок. Жарыкта адилетсиздик, коркуу жана ачарчылык жашай албайт.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"three-best-things","title":"Эң жакшы үч нерсе","paragraphs":["Атасы:","— Уулум, жашоодо ушул үч нерсеге умтулушубуз керек: эң жакшы тамакты жеп, эң жакшы төшөктө уктап, эң жакшы үйдө жашашыбыз керек.","Уулу:","— Ата, бирок биз кедейбиз го, муну кантип кылабыз?","Атасы:","— Ачка кезде жесең, ал сенин эң жакшы тамагың болот. Көп эмгектенип чарчап уктасаң, ал сенин эң жакшы уйкуң болот. Адамдарга жүрөгүңдөн орун берсең, эң жакшы үйүң ошол болот.","Сабак: Эң жакшы тамак — ачка кезде жегениң, эң жайлуу уйку — эмгектен кийин уктаганың. Эң жакшы үй — жүрөктөрдөн алган ордуң. Бакыт мүмкүнчүлүктөн гана эмес, жашоого болгон көз караштан да көз каранды.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"strongest-shield","title":"Эң күчтүү калкан","paragraphs":["Жашоодогу эң күчтүү калкан — аралык.","Сабак: Кээде адамды эң жакшы коргогон нерсе — ал ортосуна койгон аралык. Ар кимге ашыкча жакын болуу адамды оорутушу мүмкүн.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"to-be-self-confident","title":"Өзүнө ишенүү","paragraphs":["Өзүңдү баала!","Алсыздыкка жол бербе!","Күчүңө күч кош!","Үмүтүңдү үзбө!","Кабардар бол!","Чечкиндүү бол!","Ниетиң таза болсун!","Кадыр-баркыңды сакта!","Ыймандуу бол!","Сабак: Өзүңдү баала, үмүтүңдү үзбө, кадыр-баркыңды сакта. Өзүнө ишенүү — адамдын эң күчтүү таянычы.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true}]},{"title":"Сөз, унчукпоо жана баарлашуу","slug":"soz-sukut-ve-unsiyyet","blurb":"Сөздүн күчү, унчукпоонун акылмандыгы жана туура баарлашуу.","count":12,"stories":[{"stem":"communication","title":"Баарлашуу","paragraphs":["Карылар менен да, балдар менен да көбүрөөк баарлашыңыз: биринен тажрыйбаны, экинчисинен көңүлдүн тазалыгын табасыз.","Сабак: Улуудан тажрыйба үйрөн, баладан аруулукту үйрөн. Ар бир курактын өзүнчө өрнөгү бар.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"one-who-knows-and-the-one-who-does-not","title":"Билген жана билбеген","paragraphs":["(Кытай макалы)","Билбегенин билген адам — билимге умтулат. Ага үйрөткүлө!","Билип туруп, билерин аңдабаган адам — уйкуда. Аны ойготкула!","Билбегенин да билбеген адам — наадан. Андан алыс болгула!","Билгенин билген адам — жол башчы. Анын артынан ээрчигиле!","Сабак: Үйрөнүүгө умтулганга үйрөт, капарсыз жатканды ойгот, баарын билем деген наадан адамдан алыс бол, чындап билгендин артынан ээрчи.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"say-what-you-know","title":"Билгениңди айт","paragraphs":["Билгениңди айт, бирок акыл үйрөтпө. Айтылгандарды кунт коюп ук, бирок баарын эле чындык деп ойлобо.","Унчукпай туруу эч нерсе билбегениңди билдирбегендей эле, көп сүйлөө да көп нерсе билгениңди көрсөтпөйт. Адамды басынтуу — акылсыздык, аны ашкере көкөлөтүү — коркоктук.","Сабак: Туура сүйлө, туура ук, унчукканды бил. Адамды кемсинтпей да, ашкере мактабай да калыс баала.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"silent-corridor","image":"wisdom-stories/Bakhtiyar%20Sirajov/illustrations/silent-corridor.webp","title":"Жымжырт коридор","paragraphs":["Биргелешип иштеген эки уюм бар эле: бири демөөрчү, экинчиси долбоор даярдаган мекеме болчу.","Долбоордук топ айлап талыкпай эмгектенип, документтерди даярдайт. Баары даяр болгондо материалдарды демөөрчүгө жөнөтүп, жооп күтө башташат. Күндөр, апталар өттү, бирок кабар келген жок. Жыйынтык — жымжырттык.","Топтун ичиндеги белгисиздик коридорду бойлой созулган көлөкөдөй улам жайыла берди:","«Документтер жеттиби? Каралдыбы?»","Эч кимде так маалымат жок эле. Демөөрчүгө жөнөтүлгөн кайрылуулар да бүдөмүк, так эмес жоопторду гана алып келчү.","Бир нече айдан кийин топ жагдайды тактоо үчүн демөөрчүнүн кеңсесине түз барууну чечти. Ошондо гана чындык ачыкка чыкты:","«Ооба, документтер келди. Бирок биз аларды кабыл алган жокпуз. Анткени тапшыруу формасы туура эмес жана расмий жол-жобо сакталган эмес».","Топ ордунда катып калды.","«Анда эмне үчүн муну бизге айткан жоксуңар?» — деп сурашты.","«Биз кемчиликтерди бат эле оңдоп коймокпуз».","Кызматкерлер көңүлү калып кеңсеге кайтышып, өз жетекчилигине нааразылыгын билдиришти:","«Эгер иштин жүрүшүн көзөмөлдөп, документтер кайда экенин өз убагында билип, каршы тарап менен ачык сүйлөшкөнүбүздө, мындай болмок эмес. Убактыбызды жоготтук, күчүбүздү текке кетирдик, ишенимибиз солгундады — мунун баары ортобуздагы коридор жымжырт бойдон калгандыктан болду».","Сабак: Ачык баарлашуу болбосо, эң жакшы иш да көз жаздымда калышы мүмкүн. Иштин жүрүшүн көзөмөлдөбөө эң бекем кызматташтыкты да алсыратат. Кээде кызматташтыкка эң чоң зыянды ийгиликсиздик эмес, жымжырттык алып келет.","Бахтияр Сиражов"],"hasAudio":false,"hasImage":true},{"stem":"shepherd-must-be-called","title":"Койчуну чакыруу керек","paragraphs":["Көп жылдык окуусун аяктагысы келген бир шакирт устатынан бата алуу үчүн кайрылат.","Устаты:","— Макул, бирок бир шартым бар. Ушул жылдар ичинде берген илимимди татыктуу өздөштүрдүңбү же жокпу, билүү үчүн сага бир суроо берем. Туура жооп берсең, эмгегим текке кетпегенин билип, батамды берем.","Шакирт өзүнө ишенген бойдон:","— Айтыңыз, устатым, сураңыз, — дейт.","Устаты:","— Балам, элестетчи: айылыңа баратып, жолдо бир койчунун кутурган иттеринин бүтүндөй тобу сага кол салды дейли. Өмүрүң коркунучта. Жаныңды сактап калыш үчүн эмне кыласың?","— Эңкейип, жерден бир нече таш алам да, иттерге ыргытып, кууп жиберем.","— Бирок, балам, бирине таш ыргытасың, экинчисине ыргытасың — баарына кантип алың жетет? Алар жабыла келип, сени тытып салышат.","— Анда качам.","— Алар сенден ылдам чуркап, кууп жетерине шек жок. Анда эмне кыласың?","Шакирт айласы түгөнгөнүн түшүнүп, устатынан жардам сурайт.","Устаты:","— Балам, бул абалдан чыгуунун бир гана жолу бар: койчуну чакырып, иттерин токтотушун сурашың керек. Иттер койчунун үнүн угары менен турган жеринде катып калышат.","Сабак: Ар бир маселе күч менен чечилбейт. Кээде бир кадам артка чегинип, башкача кароо — эң кыска чыгуу жолу.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"shepherds-word","title":"Койчунун сөзү","paragraphs":["Илгери бир айылда Хасан аттуу кедей, бирок чынчыл койчу жашаптыр. Күндөрдүн биринде айылдын байы аны чакырып алып мындай дейт:","— Эй, Хасан, сен тоодогу жайыттарды жакшы билет экенсиң деп уктум. Ушул жайда малымды сага тапшырам. Күзүндө малым аман-соо, семиз болуп кайтса, сага бир уй берем.","Хасан макул болот. Жай бою жаанга да, күнгө да карабай малды жайып, түнкүсүн кирпик какпай кайтарат. Күз келгенде мал мурдагыдан да семиз, аман-соо болуп айылга кайтат.","Хасан убада кылынган уйду алам деген үмүт менен байга келет. Бай болсо шылдыңдай жылмайып:","— Менин сага уй берейин деген оюм жок болчу. Ал сөздү сени ишке шыктандырыш үчүн эле айткам. Ансыз да кедейсиң, бир уйду эмне кылмак элең? — дейт.","Хасандын көзүнө жаш толот. Бирок ал токтоо, намыстуу үн менен жооп берет:","— Туура айтасыз, байым, мен кедеймин. Бирок абийирим бар, айткан сөзүмө өзүм кожоюнмун. Сиз бай болушуңуз мүмкүн, бирок берген сөзүңүздүн баркы жок болсо, чыныгы кедей — сизсиз.","Бул сөз айылга ооздон-оозго тарайт. Байдын кадыр-баркы кетип, эл аны менен иш кылуудан тартына баштайт. Ал болсо кеч болсо да бир чындыкты түшүнөт: адамдын баркын мал-мүлкү же мансабы эмес, сөзүнө бекемдиги аныктайт.","Сабак: Адамдын чыныгы байлыгы мал-мүлк эмес. Убадага бектик, таза абийир, ишеним — чыныгы байлык.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"what-is-a-word","title":"Сөз деген эмне","paragraphs":["Сөз бар — көңүлдү оорутат;","сөз бар — бермет.","Сабак: Сөз менен көңүл сындырууга да, көңүл алууга да болот. Сөздү берметке айланткан нерсе — аны кантип жана кайда айтканың.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"word-and-silence","title":"Сөз жана жымжырттык","paragraphs":["Кээде адам унчукпай туруп көбүрөөк нерсени айтат. Анткени сөз жөн гана үн эмес — ал ниеттин күзгүсү.","Эгер бир сөз жүрөктү жараласа, бир сүйлөм үмүттү өчүрсө — аны айтууга арзыбайт.","Айта турган сөзүң бир жүрөккө жылуулук бербесе, бир жылмаюу жаратпаса, унчукпай койгонуң оң.","Эсиңде болсун... ар бир сөз гүлдөбөйт. Айрымдары тикен сыяктуу — тийген адамын жаралайт.","Жымжырттык — даанышмандык. Кээде ал эң баалуу жооп да болот.","Сөз жүрөктөн чыкса — даанышмандыкка айланат; ойлонбой сүйлөгөн ооздон чыкса — зыян келтирип, жара салат.","Унчукпай тур. Жымжырттык да сүйлөйт: кээде сөздөн терең, сөздөн чынчыл болот.","Сабак: Ар бир сөз гүлдөбөйт; айрымдары тикендей жара салат. Пайда алып келбей турган сөздүн ордуна унчукпай коюу даанышмандык.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"saying-the-word-in-its-place","title":"Сөздү орду менен айтуу","paragraphs":["Сөздү орду менен айта билген адам кийин кечирим суроого аргасыз болбойт.","Сабак: Айтар сөзүңдү мурунтан таразала, кийин кечирим сурабайсың. Сөз орду жана учуру менен айтылганда баалуу.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"tongue","title":"Тил","paragraphs":["Тил — ооздо өскөн бир гүл,","Сугарып бакпасаң, соолуйт бир күн.","Сабак: Тил корголбосо, сугарылбаган гүл сыяктуу соолуп жок болот. Эне тилин жашатуу — аны күн сайын сүйүп колдонуу.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"silence","title":"Унчукпоо","paragraphs":["Айрым суроолордун жообу — унчукпоо.","Же жооп берчү учур келе элек,","же маектешиң жоопко татыктуу эмес!","* * *","Дервиш Жалал Рухави","Сабак: Ар бир суроого жооп берүү шарт эмес. Кээде учуру келе элек болот. Кээде маектешиң жоопко татыктуу эмес.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"candles-conversation","title":"Шамдардын маеги","paragraphs":["Бир бөлмөдө төрт шам үлбүрөп күйүп турган. Айлана ушунчалык тынч болгондуктан, шамдардын өз ара сүйлөшкөнү угулуп турду.","Биринчи шам: «Мен — ИШЕНИММИН! Бирок жарыгымды сактоого эч ким аракет кылбайт. Жакында өчөм окшойт», — деди.","Так ошондой болду. Анын жалыны бат эле басаңдап, акыры ИШЕНИМ толук өчтү.","Экинчи шам: «Мен — БЕРИЛГЕНДИКМИН! Тилекке каршы, эми эч кимге керегим жок. Ошондуктан мындан ары күйүп туруумдун да мааниси калбады», — деди.","Ал сөзүн бүтөрү менен акырын соккон жел БЕРИЛГЕНДИКТИ да таптакыр өчүрдү.","Кезек үчүнчү шамга келди. Ал муңдуу үн менен: «Мен — СҮЙҮҮМҮН! Мындан ары күйүүгө күчүм калбады. Адамдар мени унутуп, баркым жоголду. Атүгүл эң жакындарым да сүйгөндү унутту», — деди.","СҮЙҮҮ да чыдай албай, өчүп калды.","Ошол учурда бөлмөгө бир бала кирип, үч шамдын тең күйбөй калганын көрдү. «Эмнеге күйбөй калдыңар? Силер түбөлүк күйүп турушуңар керек эмес беле?» — деп ыйлай баштады.","Ошондо төртүнчү шам сүйлөдү: «Коркпо, мен күйүп турганда башка шамдарды кайра жандыра алабыз. Мен — ҮМҮТМҮН!»","Бала сүйүнүп, көздөрү жайнап, ҮМҮТ шамын колуна алды да, калган шамдарды бирден кайра жандырды.","Сабак: Ишеним, берилгендик жана сүйүү өчкөндө аларды кайра жандырган нерсе — үмүт. Үмүттүн жарыгын сактасак, калган баалуулуктар да жанданат.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true}]},{"title":"Акылмандык жана өмүр сабактары","slug":"hikmet-ve-heyat-dersleri","blurb":"Өмүрдүн мааниси, тандоолор жана ой жүгүртүү.","count":47,"stories":[{"stem":"day-gratefully-lived","image":"wisdom-stories/Etibar%20Siracsoy/illustrations/es_day-gratefully-lived_ky.webp","title":"Дагы бир күн жашадым","paragraphs":["Күн башталды… Күн бүттү…","Ар таңда көзүбүздү ачып, жаңы күндүн башталганын көрөбүз. Бирок көп учурда кечтин качан киргенин, өмүрүбүздүн дагы бир күнү качан өтүп кеткенин байкабай калабыз. Убакыт тынч аккан дарыядай агат, а биз анын жээгинде туруп, өтүп бараткан көз ирмемдерди узата карайбыз.","Кээде адам өзүнөн сурайт: Жараткан бул күндү мага кандай максат менен тартуулады экен? Ушул ыйык аманаттын баркын билдимби? Бул күнгө эмне коштум, андан эмне алдым? Жан дүйнөмө кандай жарык кирди, кайсы мүмкүнчүлүктү колдон чыгарып жибердим?","Адам өмүрүндөгү эң чоң байлык — убакыт. Анткени жоготкон нерселериңдин айрымдары кайра табылышы мүмкүн, бирок өткөн бир көз ирмем да кайтып келбейт. Ошондуктан ар бир күндүн, ар бир сааттын, ал тургай ар бир демдин өз баркы, өз мааниси бар.","Ошентип, дагы бир күн жашадым… Убакыттын чексиз китебинде өмүрүмдүн дагы бир барагы оодарылды. Ал баракта эмне жазылганын бир гана Жараткан толук билет.","Сабак: Ар бир жаңы күн — бизге берилген кымбат аманат. Кеч киргенде аны кандай өткөргөнүбүздү ойлонуу эртеңки күнүбүздү маңыздуу жашоого жардам берет.","Этибар Сиражсой"],"hasAudio":false,"hasImage":true},{"stem":"nothing-is-ever-truly-lost","title":"«Жоготтум» деген нерсе жок","paragraphs":["Жашоодо жоготууну гана көрбөгүлө. Жетишкен ийгиликтериңиз да, ийгиликсиздиктен алган сабактарыңыз да бар.","Сабак: «Жоготуу» деген жок — же утасың, же үйрөнөсүң. Ар бир ийгиликсиздик чындыгында сабак.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"human-emerged","title":"Адам чыкты","paragraphs":["Ойду жүрөк менен бириктирдим — сүйүү чыкты.","Сүйүүнү эмгекке коштум — берилгендик жаралды.","Нанды абийир менен бөлдүм — адилеттик чыкты.","Сүйүүнү, эмгекти, абийирди, берилгендикти жана адилеттикти бириктирдим — адам чыкты.","— Яшар Кемал","Сабак: Адамгерчилик сүйүүдөн, эмгектен, абийирден, берилгендиктен жана адилеттиктен куралат. Бул баалуулуктар бириккенде чыныгы адамгерчилик жаралат.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"if-the-door-before-you-wont-open-it-is-not-your-door","title":"Ачылбаган эшик балким сенин эшигиң эмес","paragraphs":["Бул окуя бир компаниянын жетекчиси менен анын кызматкеринин ортосунда болот. Бир күнү Жамал жетекчиси Салим мырзанын алдына келип, кызматта өсүү болорун укканын жана өзүнүн да үмүтү бар экенин айтат. Салим мырза Жамалдын ишине ыраазы экенин билдирсе да, «сен бизге толук ылайык келбейсиң» деп, анын иштен бошотулганын жарыялайт. Жамал көңүлү чөгүп, компаниядан кетүүгө аргасыз болот.","Эки жылдан кийин алар кайрадан жолугуп калышат. Жылуу учурашып, ал-жай сурашкандан кийин Жамал өзүнүн жаңы компаниясын түзгөнүн жана иштери ийгиликтүү жүрүп жатканын мурдагы жетекчисине айтып берет. Салим мырза буга абдан кубанганын билдирет.","Жамал Салим мырзага ыраазычылыгын мындайча айтат: «Чынында, мен сизге ыраазымын. Анткени мага ылайык болбогон ошол компанияда калышымды каалабай, мени бошоттуңуз. Бул мен үчүн жаңы мүмкүнчүлүк болуп, өзүм абдан жактырган иш менен алектенүүгө түрткү берди. Азыркы абалыма мен абдан ыраазымын».","Сабак: Жабылган ар бир эшик чындыгында пайдалуураак жолду көрсөтүшү мүмкүн. «Жакшыдан» ажыроо кээде «жакшыраакка» алып барат.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"no-need-to-be-sane-when-everyone-is-mad","title":"Баары жинди болгондо акыл-эстүү болуунун кереги жок","paragraphs":["Бир күнү нур жүздүү бир кишиге жогорудан кабар келет: «Эй, адам, эртеңден баштап суунун даамы өзгөрөт, андан ичкендер жинди болуп калат». Киши шашып үйүнө чуркап барып, колуна тийген кумуралар менен идиштердин баарына суу толтуруп, күтүп отурат. Эртеси караса, чын эле элдин баары жинди боло баштаптыр, өзү болсо жыйнап койгон суусун гана ичет. Ушинтип бир-эки жума өтөт. Киши чыдабай сыртка чыгат. Жолуккандар менен бир-эки ооз сүйлөшөрү менен, баары аны шылдыңдай баштайт: «Эй, киши, жинди болуп калгансыңбы? Жиндиканага бар!» Байкуш киши да үйүнө кайтып келип, идиш-кумураларын талкалап, кадимки булактан — элдин баары ичкен суудан ичет да, уктап калат.","Сабак: Чындыкты билгениң үчүн көпчүлүк сени айыпташы мүмкүн. Акылыңды сакта, бирок өзүңдү баарына далилдеп чарчап калба.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"different-path","title":"Башка жол","paragraphs":["Бир күнү бир уй сарайына кайтыш үчүн чыйыр жок токойду аралап өтүүгө туура келет. Жол тандай албаган жаныбар бирде өйдө чыгып, бирде ылдый түшүп, ийри-буйру, татаал чыйыр салып кетет.","Эртеси бир ит токойдун аркы бетине өтүш үчүн уй салган чыйырга түшөт. Кийин ошол жерге койчу отору менен келет. Даяр чыйырды көрүп, ал да койлорун ошол жолго салат.","Бир аз убакыт өткөн соң адамдар да ушул чыйырды пайдалана башташат. Алар жолдун татаалдыгына нааразы боло, бирде оңго, бирде солго бурулуп, дарактын бутактары менен бадалдарга урунбоо үчүн эңкейип-бүгүлүп илгерилешет. Бирок эч ким ыңгайлуураак башка жол издеп көрүүнү ойлобойт.","Тынымсыз колдонулган чыйыр бара-бара жолго айланат. Токойдун аркы бетине жарым саатта эле жетүүгө болорун билбеген адамдар менен оор жүк артылган жаныбарлар уй салган ийри жолду үч саат басып өтүшөт.","Жылдар өтөт. Кичинекей жол адегенде шаардын негизги жолуна, кийин анын эң маанилүү көчөсүнө айланат. Бар болгон жолдордун ичинен эң ыңгайсызы болсо да, элдин баары жол тыгынына гана нааразы болот.","Мунун баарын кары, акылман токой байкап турат. Баскан жолум туурабы деп бир да жолу ойлонбой, баягы чыйырды сокур ээрчиген адамдарга анын боору ооруйт.","Сабак: Баары баскан жол дайыма эң туура жол боло бербейт. Кээде көнгөн жолдон чыгып жаңы жол издеген адам көздөгөн жерине эртерээк жана оңойураак жетет.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"it-is-in-vain","title":"Бекер","paragraphs":["Акмакка насаат айтып, наадан менен талашып, эки жүздүү менен дос болуу — куру убара.","Сабак: Наадан менен талашка, эки жүздүү менен достукка кеткен убакыт текке кетет. Ким менен убакыт өткөрүүнү тандасаң, өмүрүңдү кантип жашарыңды да тандайсың.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"liver","title":"Боор","paragraphs":["«Ciyər» сөзү катышкан айкаштар — бири-бирине өтө жакын, чын ыкластуу, ынак досторду билдирген «can-ciyər»; абдан сүйүктүү баланы билдирген «ciyərguşəm»; коркок, кайратсыз, алсыз адамды билдирген «ağciyər»; өтө сүйүктүү кишини билдирген «ciyərparəm» — кайдан келип чыккан?","Байыркы адамдар боордун жылуу жана кандуу көрүнүшүнөн таасирленип, жылуу канды өмүр, ал эми анын жоктугун өлүм деп эсептешкен. Ошондуктан боор узак убакыт бою жашоонун борбору катары кабыл алынып келген.","Мисалы, вавилондуктар адамдын жаны боордо жайгашат деп ишенишкен. Айрым маданияттарда боор, баарынан мурда, сезимдерди билдирет деп эсептелгендиктен, макал-лакаптарда жана жазма чыгармаларда ал жүрөктөн мурда аталат.","Байыркы Грекияда изгилик жана ага байланышкан эр жүрөктүк, чечкиндүүлүк сыяктуу сапаттар боорго таандык деп саналган. Эгер адамдын боору соо болсо, ал изгиликтүү — бардык тоскоолдуктарды жеңип, өз принциптерин бекем карманган адам катары кабыл алынган.","Сабак: Тил кокустан жаралбайт; ар бир сөздүн артында тарых, ишеним турат. Сөздөрүбүз өткөнүбүздүн эс тутуму.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"spare-time","title":"Бош убакыт","paragraphs":["Айрымдар бош убактысы болгондо сиз менен сүйлөшөт, ал эми айрымдар сиз менен сүйлөшүү үчүн атайын убакыт бөлөт.","Сабак: Убакыт — кайра кайтпаган жалгыз байлык. Аны сага ыктыярдуу сарптаган адамдын кадырын бил.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"where-does-this-road-go","title":"Бул жол кайда барат?","paragraphs":["Жолдо бараткан бир жигит жол боюнда отурган карыяга жолугуп, сурайт:","— Аксакал, бул жол кайда барат?","— Эч жакка, уулум.","— Кандайча? Эч жакка барбаган жол болобу?","— Кудай акы, мен бул жерде элүү жылдан бери жүрөм; бул жол мурдатан кандай болсо, азыр да ордунда турат. Барып-келген — адамдар.","Сабак: Жол ордунда турат, жолчу — сенсиң. Кайда барарыңды билбей туруп, жол сени кайда алып барарын сураба.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"this-boat-is-empty-too","title":"Бул кайык да бош","paragraphs":["Устатым мындай дечү:","Жаш кезимде көлгө көп барып, жалгыз ойго чөмүлчүмүн. Чакан кайыгым бар эле. Ошол кайыкта сааттап сүзүп, ой дүйнөмдөн жан тынчтыгын тапчумун.","Бир күнү таң заардан, күн жаңы агарып келатканда, адаттагыдай кайыгымда отуруп терең ойго баткам.","Бир маалда бирөөнүн кайыгы менин кайыгыма урунуп, бүт кыял дүйнөмдү бузду. Аябай ачууландым. Кайыктын ээсин тилдөө үчүн көзүмдү ачсам, мага урунган кайык бош экен. Ачуумду төгө турган эч ким жок болчу. Ошондуктан көзүмдү жумуп, кайрадан ойлорума кайттым. Күн чыкканда жан дүйнөм толук тынчып калганын сездим.","Бош кайык мага сабак болду. Ошол күндөн бери кимдир бирөө мени капа кылгысы келгенде, ичимен жөн гана мындай дейм:","— Бул кайык да бош.","Сабак: Адам жан тынчтыгын сактагысы келсе, ар бир окуянын артынан жаман ниет издебеши керек. Кээде бизди тынчсыздандырган нерсе жөн гана кокустук. Аны чоңойтуп, ачууга айландыруу же айлантпоо — өзүбүздүн тандообуз.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"if-i-dont-do-it-these-days-the-world-wont-collapse","title":"Бүгүн-эртең кылбасам, дүйнө урап калбайт да","paragraphs":["Бир кызматкерибизден ага тапшырылган иш кайсы баскычка жеткенин сураганымда, анын жообу мени терең капалантты:","«Бүгүн-эртең кылбасам, дүйнө урап калбайт да…»","Бир саамга ойлонуп калдым: Ооба, дүйнө урабайт. Бирок ортобуздагы ишеним? Ал да урабайбы? Мындай мамиле кызматташтыгыбызга, өз ара урмат-сыйыбызга жана биргелешип аткарып жаткан ишибизге зыян келтирбейби?","Кеп тапшырманын бир нече күнгө кечиккенинде эмес эле. Кеп адамдын өзүнө алган милдетине жасаган мамилесинде болчу. Анткени жоопкерчилик — ишти жөн гана бүтүрүү эмес; берген сөзүңө туруу, сага артылган ишенимди актоо жана адамдардын сага таяна алышына шарт түзүү.","Менимче, өз мойнуңа алган кайсы гана милдетке болбосун ушундай жоопкерчиликсиз мамиле кылуу туура эмес. Андан да өкүнүчтүүсү — бул мамиленин кандай сөз менен билдирилгени. Мен үчүн мындай жооп, бери дегенде, орой угулат жана башка тараптын убактысы, эмгеги менен ишеними жетиштүү бааланбай жатканын көрсөтөт.","Чынын айтсам, бул сөздөр жүрөгүмдү оорутту. Ошол замат кызматташтыгыбыз мурдагыдай улана албасын түшүндүм. Анткени ар кандай кесиптик мамиленин пайдубалы — ишеним. Ишеним солгундаганда, кызматташтык да олуттуу сыноого туш болот.","Мени баарынан да капаланткан нерсе — кесиптешим айткан сөзүнүн туура эмес экенин түшүнгөн жок, ал үчүн кечирим да сурабады, тапшырманы да аткарбады. Акыры ага болгон ишенимим солгундагандыктан, маселени башка жол менен чечүүгө аргасыз болдум.","Бул окуя мага уюмдардагы эң баалуу ресурс убакыт да, акча да, технология да эмес экенин дагы бир жолу көрсөттү. Эң баалуу ресурс — адамдардын бири-бирине болгон ишеними. Ишенимге ээ болуу үчүн жылдар талап кылынышы мүмкүн, ал эми аны кээде бир эле сүйлөм менен жоготуп коюуга болот.","Сабак: Ишеним — уюмдун эң баалуу байлыгы. Аны табууга жылдар кетет, жоготууга бир сүйлөм жетиштүү. Сөзүндө турган адам бул байлыкты сактайт.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"doctors-appointment","title":"Дарыгердин кабыл алуусунда","paragraphs":["Дарыгерге кирүү үчүн кезегимди күтүп отургам. Үйдөн эртең мененки тамакты ичүүгө үлгүрбөгөндүктөн, буфеттен бир сэндвич менен алма ширесин сатып алып жей баштадым.","Ошол учурда терезенин жанында отурган бир баланын мени кунт коюп карап турганын байкадым. Анын көз карашы «Мен да ачкамын» деп жаткандай сезилди. Боорум ооруп, буфетке кайра барып, ага да сэндвич менен алма ширесин сатып бердим.","Бала тамшанып жеп жатты. Мен болсо бирөөгө жакшылык кылдым деп кубанып турдум.","Дал ошол учурда баланын апасы каттоо бөлмөсүнөн чыкты. Көргөн замат тынчсыздана жаныбызга келди:","— Эмне кылдыңыз? Дарыгер баланы кароого ачкарын алып келүүнү тапшырган. Жумуштан уруксат алып, алыс жолдон келдик. Эми эртең баарын кайра баштоого туура келет.","Аял көз жашын тыя алган жок. Мен катып калдым. Жакшылык кылдым деп ойлоп, бир үй-бүлөнүн мээнетин текке кетириптирмин.","Сабак: Сезим менен божомолго гана таянсак, туура эмес чечим чыгарышыбыз мүмкүн. Жардам берерден мурун жагдайды билүү да боорукердиктин бир бөлүгү.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"diderot-effect","title":"Дидро эффекти","paragraphs":["XVIII кылымдагы француз жазуучуларынын бири, агартуучу Дени Дидро чоң карызга батат. Анын оор абалы орус императрицасы Екатеринанын кулагына жетет.","Императрица Дидрону бул оор абалдан чыгаруу үчүн кең пейил сунуш кылат: анын китепканасын акчага сатып алып, кайра өзүнө белек кылат. Андан тышкары, ошол китепканада иштесин деп Дидрого 25 жылдык айлыгын да алдын ала төлөп берет. Албетте, мынча акчаны алдын ала алуу Дидро үчүн күтүүсүз байлык эле. Ошентип, Дидро бардык карызынан кутулуп, көңүлү жай алат.","Бир күнү досу ага кызыл баркыт халат — кымбат баалуу сырт кийим — белек кылат. Баары дал ошондон кийин башталат...","Дени халатты киет. Жазуу үстөлүнүн артында шыктануу менен иштеп жатып, күтүлбөгөн жерден бул кооз баркыт халат менен үстөл бири-бирине төп келбей турганын ойлойт.","Колундагы мол акчага ишенип, дароо жаңы үстөл сатып алганы жөнөйт. Көзүнө эң кооз көрүнгөнүн тандап алат. Эми халаты менен үстөлү жарашып калды...","Бирок ошондо жердеги эски килем халатына да, үстөлүнө да жарашпай калганын көрөт. Чуркап барып, акчасына да, өзүнө да ылайык жаңы килем сатып алат.","Ошентсе да ичиндеги тынчсыздануу кетпейт. Үйдөгү креслолор, шкафтар, отургучтар, дубалдагы сүрөттөр жана бөлмөнүн жасалгалары эми бири-бирине төп келбей, эскирип калгандай көрүнөт...","Эми баары көзүнө уруна баштайт...","Убакыт өтүп отуруп, Дидро үйүндөгү буюмдардын баарын майда-чүйдөсүнө чейин алмаштырат.","Көп өтпөй Дидро абалын түшүнөт. Кайра баштапкы чекитине келип калышына өзүнүн тойбогон ач көздүгү себеп болгонун аңдайт.","Натыйжада жазуучу ушул тема жөнүндө «Эски халатым менен коштошконума өкүнөм» аттуу белгилүү эмгегин жазат. Андан соң түшкөн абалын бир сүйлөм менен билдирет:","«Эски кийимимдин кожоюну элем, жаңы кийимимдин кулуна айландым».","Сабак: Адам бир жаңы нерсе алгандан кийин калгандарын да алмаштыруу зарылдыгын сезет — муну «Дидро эффекти» деп аташат. Ач көздүктүн чеги жок; эскинин кожоюну болуу жаңынын кулу болуудан жакшы.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"most-beautiful-places-in-the-world","title":"Дүйнөдөгү эң сонун жерлер","paragraphs":["Дүйнөдөгү эң сонун жер — өзүң сүйгөн адамдардын оюнда, дубасында жана жүрөгүндө ээлеген ордуң.","Сабак: Адам боло ала турган эң сонун жер — сүйгөндөрүнүн жүрөгү жана дубасы. Чыныгы жай дарек эмес, сүйүү.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"secret-of-living-well-and-longevity","title":"Жакшы жашоонун жана узак өмүрдүн сыры","paragraphs":["Тамагыңарды жарымына азайткыла, сейилдөөңөрдү эки эсе, күлкүңөрдү үч эсе көбөйткүлө, ал эми сүйүүңөргө эч кандай чек койбогула.","Тибет макалы.","Сабак: Тамактын ченемин бил, басып-сейилде, күлкүңдү, мээримиңди аяба. Бактылуу өмүрдүн сыры кээде ушундай жөнөкөй нерселерде.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"what-matters-in-life","title":"Жашоодо эмне маанилүү?","paragraphs":["Мугалим класска кирип, окуучулар менен учурашат да, сумкасынан айнек банка алып чыгып, үстөлдүн үстүнө коёт:","— Ар бирибизге бир гана өмүр берилген. Убактыбызды туура пайдалансак, бул жашоодо каалаган нерсебиздин баарына жете алабыз. — Анан банканы гольф топтору менен толтуруп, окуучулардан сурайт: — Кандай дейсиңер, банка толдубу?","— Толду, — деп баары бир ооздон жооп берет.","Мугалим сумкасынан бир аз ири шагыл чыгарып, банкага салат да, кайра сурайт:","— Эмичи, банка толдубу?","— Ооба, — деп жооп беришет окуучулар.","Мугалим банкага дагы бир аз кум куюп, дагы бир жолу сурайт:","— Банка толдубу?","Окуучулар бул жолу да банканын толгонун ырасташат.","Көрсөтмөсүн аяктаган мугалим анын маанисин окуучуларга мындайча түшүндүрөт:","— Бул банка жашоонун белгиси деп элестеткиле:","гольф топтору — жашоодо эң жогору баалаган нерселериңердин: үй-бүлөңөрдүн, досторуңардын, сүйүктүү адамдарыңардын;","ири шагылдар — башка маанилүү нерселердин: мал-мүлкүңөрдүн, үй-жайыңардын, ишиңердин;","кум болсо силерге керек болушу мүмкүн, бирок анчалык маанилүү эмес башка нерселердин белгиси.","Эгер мен банканы адегенде кумга толтурсам, гольф топторуна да, шагылдарга да орун калмак эмес. Жашоо да ушундай. Эгер аны майда, маанисиз нерселерге толтуруп, бүт убактыбыз менен күчүбүздү ошолорго сарптасак, эң маанилүү нерселерге убакыт калбайт.","Сабак: Жашооңдо адегенде үй-бүлөңө, сүйүүгө, ден соолугуңа орун бер. Бүт убактыңды майда иштерге сарптасаң, эң баалуу нерселерге убакытың калбайт.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"what-we-learn-in-life","title":"Жашоодон үйрөнгөндөрүбүз","paragraphs":["Бул жашоодо дайыма үйрөнөсүң:","бирөөдөн сабыр кылууну, бирөөдөн сүйүүнү, бирөөдөн берилген, ишенимдүү, адептүү болууну; дагы бирөөдөн эки жүздүүлүк, жасалмалуулук, кара ниеттик жана чыккынчылык эмне экенин.","Сабак: Жашоо ар бир адамдан бир нерсе үйрөтөт: бирөөдөн берилгендикти, бирөөдөн чыккынчылык эмне экенин. Экөө тең сабак.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"searching","title":"Издөө","paragraphs":["Бир нерсени ал жок жерден издөө — издөө эмес, өзүңдү өзүң алдоо. Бул берилбегенден берилгендикти, уятсыздан адепти, абийирсизден мээримди издегенге тете.","Сабак: Адамда жок нерсени андан күтүү — өзүңдү алдоо. Ар кимден бардыгын күтпө, адамды кандай болсо ошондой тааны.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"what-it-means-to-be-late","title":"Кечигүү деген эмне?","paragraphs":["Кечигүү — бир ишти, бир аракетти өз убагында жасай албай калуу. Адамдар менен мамиледе кечигүү кээде андан да оор болот.","Сүйөрүбүздү айтуу, кимдир бирөөдөн сүйүү үлүшүбүздү алуу, таарынычты кечирүү, көңүлүн ооруткандарыбыздан кечирим суроо — мунун баары өз убагында жасалганда баалуу.","Биз пендебиз. Ар бирибиз каалаган учурда жаңылышып же туура эмес иш кылып алышыбыз мүмкүн. Эң маанилүүсү — кетирген катабызды моюнга алып оңдоого, кечирим суроого, көңүл алууга кечикпөө. Өмүр кыска.","Кечикпейли: ошондо «аттиң» деген өкүнүчү жок, «жакшы болгон экен» деген шүгүрү көп, адилеттүү жана бакытка толгон өмүр сүрөбүз.","Сабак: Сүйүүнү билдирүү, кечирүү жана кечирим суроо өз убагында сонун. Өмүр кыска — көңүл иштерин кийинкиге калтырбайлы.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"bookstore","title":"Китеп дүкөнүндө","paragraphs":["Медицина боюнча билим алып жаткан студент Бурсадагы «Билге» китеп дүкөнүнөн көпкө издегенден кийин керектүү китебин тапты. Артындагы баасын көргөндө жылмаюусу заматта өчтү: аны сатып алууга акчасы жетпейт эле.","Муну билдирбегенге аракет кылып, барактарын ачып, мугалим тапшырган бөлүмдү тапты. Дүкөн ээлери кардарлар менен алек экенин көрүп, текстти бат эле окуп чыгып кетти.","Кийинки бир ай ичинде студент эки күндө бир китеп дүкөнүнө келип, текчелердин арасында сабагын окуп жүрдү. Бүтүрүү сынактарына бир жума калганда кайра келди, бирок китепти ордунан таппады. Бардык текчени карап чыкты; китеп дайынсыз жоголгондой эле.","Өңү кубарып, кетүүгө камынганда дүкөн ээлери аны токтотушту:","— Кел, отур. Сага айта турган сөзүбүз бар.","Китепчилердин бири үстөлүнүн алдынан ошол китепти чыгарды:","— Жакында бир кардар баасын сурап, сатып алгысы келди. Мен китепти текчеден алып, сен үчүн сактап койдум. Ушул жерде отуруп окуй берсең болот.","Жигит окуусун бүтүрүп, дарыгер болгондон кийин да ошол эки китепчини унуткан жок. Акчасы жок бейтаптардан эч качан акы алган жок.","Сабак: Кичинекей жакшылык адамдын жүрөгүндө өмүр бою из калтырышы мүмкүн. Жакшылык көргөн адам көп учурда өзү да башкага жакшылык кылат.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"small-changes-big-meaning","image":"wisdom-stories/Etibar%20Siracsoy/illustrations/es_small-changes-big-meaning_ky.webp","title":"Кичинекей жаңылыктардын чоң мааниси","paragraphs":["Бир калыптагы жашоо адамдын жан дүйнөсүн билинбей чарчатат. Ар бир күн кечээкисиндей өтүп, баягы эле иштер кайталана берсе же эч нерсе кылбай убакытты өткөрсөң, ичиңде боштук пайда болуп, көңүлүң чөгөт. Анткени жан дүйнө да жашоо сыяктуу кыймылды, өзгөрүүнү, жаңылыкты самайт.","Кээде жашообузга кичинекей эле жаңылык кирсе, ичибизде жаңы терезе ачылгандай болот. Кадимки күндөр заматта өңүнө чыгып, көңүлгө жагымдуу толкундануу, жашоого кызыгуу, жакшы маанай келет. Чынында, жашоонун көркү бизге туш келген кокустуктарда гана эмес, өзүбүз ага канчалык сулуулук, канчалык жаңылык кошо аларыбызда да жатат.","Адам өз жашоосуна сырттан карап турган көрүүчү болуп калбашы керек. Кээде башка жолду тандап көрүү, жаңы адам менен таанышуу, жаңы жерге баруу, бир нерсе үйрөнүү, бир нерсе жаратуу же сүйгөн ишиңе убакыт бөлүү эле жашоонун өңүн өзгөртөт. Жаңылык дайыма эле чоң окуя эмес: кээде кичинекей кадам чоң шыктануунун башаты болот.","Жашоо бизге жазылып бүткөн барак болуп берилбейт. Анын ар бир күнүн өзүбүз жазабыз. Ошондуктан өмүр барактарын кайталанган иштер менен эмес, жаңы сезимдер, жаңы кыялдар, жакшы эскерүүлөр менен толтуруу өз колубузда.","Сабак: Жашообузга жаңылык киргизүү үчүн чоң өзгөрүүлөрдү күтүүнүн кереги жок. Үйрөнүүгө, сүйгөн ишибизге бөлгөн аз гана убакыт да күнүбүзгө маңыз бере алат.","Этибар Сиражсой"],"hasAudio":false,"hasImage":true},{"stem":"to-dream","title":"Кыялдануу","paragraphs":["Кудай насип кылбай турган нерсени кыялдантпайт.","Сабак: Жүрөккө түшкөн ар бир кыялдын бир хикматы бар. Кудай насип кылбай турган тилекти жүрөккө салбайт — үмүтүңдү үзбө.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"blind-who-have-eyes","title":"Көзү бар сокурлар","paragraphs":["Жер үстү көзү бар деп көрүп жатам деген сокурларга толгон.","Сабак: Көрүү үчүн көз эле жетишсиз, көргөнүңдү аңдап түшүнүү да керек. Карап көрбөгөн, угуп түшүнбөгөн адам чыныгы сокур.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"lecturer-and-the-groom","title":"Лектор жана ат багуучу","paragraphs":["Бир айылга элге баяндама окуш үчүн лектор чакырышат. Ал залга кирип, ичинде бир эле киши отурганын көрөт. Саламдашкандан кийин андан: «Сизден башка эч ким келген жок. Кандай дейсиз, лекцияны өткөрөлүбү же жокпу?» — деп сурайт.","Жалгыз «угуучу» мындай дейт:","— Агай, мен ат багуучумун, жыйырма атым бар. Он тогузу качып кетип, бирөө калса да, аны багып, суусун, жемин берем.","Лектор сөзүн баштап, узактан-узак сүйлөйт. Бүткөндөн кийин ат багуучудан сурайт:","— Кандай, лекциям жактыбы?","Ат багуучу жооп берет: «Мен ат багам, сиздин айткандарыңыздан көп нерсени түшүнгөн жокмун. Бирок бир нерсени так айта алам: жыйырма аттын жемин бир атка берип, аны жарылып кеткенче тойгузбайм».","Сабак: Жакшы сүйлөө — көп сүйлөө эмес, ойду угуучу түшүнүп, сиңире ала тургандай айтуу.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"what-do-i-need-it-for","title":"Мага эмне","paragraphs":["Кануни Султан Сулейман (1494–1566; 1520-жылы такка отуруп, өмүрүнүн акырына чейин бийлик жүргүзгөн) Осмон мамлекетин өз доорунун эң кубаттуу мамлекеттеринин бирине айлантат. Бирок ал кээде: «Күндөрдүн биринде Осмон урпактарынын мамлекети да алсырап, кыйрап калабы?» — деп ойлоно берчү экен.","Башка көп маселелердей эле, бул тынчсыздандырган оюн да сүт бир тууганы, белгилүү аалым Яхья Эфендиге айтууну чечет. Кашфына, кереметине ишенген Яхья Эфендиге мындай кат жазып жөнөтөт: «Сен Кудайдын сырларына каныксың. Ырайым кылып, муну бизге түшүндүрүп бер. Мамлекет кандай учурда кыйрайт? Осмон урпактарынын тагдыры эмне болот? Бул мамлекет банкрот боло турган күн келиши мүмкүнбү?»","Доорунун кудуреттүү султаны Улуу Сулеймандан келген катты окуган Яхья Эфендинин жообу өтө кыска болот: «Мага эмне, султаным!»","Топкапы сарайында бул жоопту таң кала окуган султан анын маанисин түшүнө албай, ого бетер тынчсызданат. Анткени Яхья Эфендидей адам олуттуу маселеге мынчалык жөнөкөй жооп бермек эмес. «Бул жоопто биз билбеген бир маани барбы?» — деп ойлонгон султан ордунан туруп, Яхья Эфендинин Бешикташтагы дербишканасына жөнөйт. Бул жолу султан бир аз жемелегендей үн менен: «Агай, катыма жооп берсең боло. Бул маселеге олуттуу кара», — деп суроосун кайталайт.","Яхья Эфенди:","«Султаным, сиздин сурооңузга олуттуу карабай коюу мүмкүнбү? Мен сурооңузду жакшылап ойлонуп, бүтүмүмдү ачык эле билдирген элем».","«Макул, бирок жообуңдан эч нерсе түшүнгөн жокмун. Болгону “мага эмне” депсиң. Бул “мени бул иштерге аралаштырба” дегендей сезилди».","Яхья Эфенди төмөнкү таалимдүү сөздөрүн тарых барактарына түбөлүккө жазат:","«Султаным! Эгер бир мамлекетте зулумдук жайылып, адилетсиздик аршка көтөрүлсө, аны уккандар да “мага эмне” деп четке чыга берсе; койлорду карышкырлар эмес, койчулар жесе; билгендер чындыкты айтпай унчукпай, аны жашырса; кедейлердин, муктаждардын, жакырлардын, кимсиздердин зар-муңу асманга жетип, аны таштан башка эч ким укпаса — анда мамлекеттин акыры көрүнөт. Мындай учурда мамлекеттик казына бошойт, элдин ишеними менен урмат-сыйы солгундайт. Тынчтыктын тиреги болгон баш ийүү сезими жоголуп, элге болгон урмат өчөт. Ошентип, кыйроо менен банкроттук сөзсүз келет...»","Бул сөздөрдү угуп отуруп ыйлап жиберген кары султан башын төмөн салып, алардын туура экенин мойнуна алат. Анан өз өлкөсүндө ага ушундай насаат айта ала турган аалым бар экенине Кудайга шүгүр кылып, ал жерден чыгып кетет.","Сабак: Зулумдукту көрүп «мага эмне» деген коом төмөндөйт. Адилетсиздикке көз жумуу — ага шерик болуу.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"more-effective-way","title":"Натыйжалуураак жол","paragraphs":["Токой аралап бараткан мерген кызык көрүнүшкө туш болот. Бир отунчу бир даракты кыюу үчүн көптөн бери аябай кыйналып балталап жатыптыр. Бетинен тер куюлуп, бүт денеси чыңалып турган экен.","Мерген жакындап келип сурайт:","— Эмне үчүн ишиңиз ушунчалык оор жана жай жүрүп жатат? Балтаңыз такыр мокоп калыптыр. Бир аз курчутуп албайсызбы?","Отунчу ага таң кала карап, жооп берет:","— Эмне деп жатасыз? Балтаны курчутууга убакытты кайдан табам? Алдыда кыйыла турган дагы жыйырма дарак бар!","Сабак: Эмгек баалуу, бирок ойлонулбаган эмгек натыйжасыз болушу мүмкүн. Бир аз токтоп, куралыңды курчутсаң, калган ишиң тезирээк, жеңилирээк бүтөт.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"newtons-second-law","title":"Ньютондун 2-мыйзамы","paragraphs":["Физика мугалими сабактан чыгып, мугалимдер бөлмөсүнө кирет да, кесиптештерине даттанат: «Бул студенттер кандай гана акылсыз! Ньютондун 2-мыйзамын аларга үч жолу түшүндүрдүм. Акырында атүгүл өзүм да түшүндүм, бирок алар дагы эле түшүнгөн жок».","Сабак: Үйрөтүүдөн мурда өзүң түшүн. Өзүң түшүнбөй туруп түшүндүргөн сөздөн мугалимге да, окуучуга да пайда жок.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"road-to-the-cotton-field","title":"Пахта талаасына кеткен жол","paragraphs":["Биз али жөндөп окуп-жаза албаган кез эле. Айылыбызга бир мугалим келди. Көрсө, жөн эле мугалим эмес, бизге ага да, ата да боло турган адам келиптир. Мектебибиздин жана биз, окуучулардын кейиштүү абалын, мектепти бүткөндөн кийин пахта талаасында иштөөгө аргасыз экенибизди билгенде, анын көзүнө жаш толду.","Айылыбызда бир жол бар эле. Айдын агай бизден анын кайда барарын сурады. Биз ал жол пахта талаасына алып барарын айттык. Айылдан чыккан дагы бир жол бар болчу. Анын кайда барарын да сурады. Өмүрүбүздө айылдан чыкпагандыктан, дүйнө биздин айылдан гана турат деп ойлогондуктан, бул суроого жооп бере алган жокпуз.","Ошол күнү ал бизден чоңойгондо ким болгубуз келерин да сурады. Эмне деп жооп берерибизди билбей, баарыбыз унчукпай калдык...","Мугалимибиз бизге кыска убакытта окуп-жазганды үйрөттү. Күндөр өтүп, эми эркин окуп-жаза баштадык. Бир күнү Айдын агай бизге толтура кат алып келди. Ал каттар дарыгерлерден, инженерлерден, окумуштуулардан жана ар түрдүү кесип ээлеринен келгенин айтты. Анын айтымында, ошол адамдар биз менен кат алышкан досторубуз болмок. Жылдар бою такыр тааныбаган ал адамдар бизге кат жазып турушту. Каттарында өз кесиптери, жашоонун маңызы, илим менен билимдин мааниси тууралуу айтып беришти. Ошол каттарды алганга чейин илим үйрөнүү, пахтачылыктан башка кесипке ээ болуу жөнүндө кыял да кылган эмес элек.","Анткени алдыбызда дайыма бир гана жол — пахта талаасына алып барган жол бар деп ойлочубуз.","Кат алышкан досторубуздун аркасында жашообуз өзгөрдү. Экинчи жолдун кайда алып барарын билдик. Айдын агайдын зор эмгегинин аркасында мектепти бүткөндөн бир нече жыл өткөн соң чоң ийгиликтерге жеттик. Азыр айрымдарыбыз дарыгер, айрымдарыбыз инженер, дагы бирөөлөрүбүз мугалим болууга даярданып жатабыз.","Арадан жылдар өткөн соң, бир күнү бизге дагы бир кат келди:","«Балдарым... Ар дайым кыялдангыла. Кыялдар силерди каалаган жериңерге жеткирет. Болгону күч-аракет жумшап, эмгектенип, максатыңарга жетүүгө чечкиндүү болгула. Баарыңарды чын жүрөктөн куттуктайм. Мен силердин колуңардан келерин жана ийгиликке жетериңерди билчүмүн».","«Силер менен кат алышкан досуңар Айдын агай».","Баарыбыз таң калуудан катып калдык. Көрсө, жылдар бою бизге жол көрсөтүп, жашообузду өзгөрткөн каттарды өзүбүздүн Айдын агайыбыз жазып жүрүптүр.","Сабак: Мугалим балдарга жол гана көрсөтпөстөн, алардын алдына жаңы жолдорду да жараткан. Кыялдай алган адам үчүн дүйнө эми бир эле жолдон турбайт.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"pawn-and-the-king","title":"Пешка менен падыша","paragraphs":["Пешка деп кемсинтпе!","Күндөрдүн биринде ПАДЫША болот.","Падыша деп ишенип калба!","Күндөрдүн биринде МАТ болот.","Сабак: Эч кимди кичине көрүп кемсинтпе, чоң даражага таянып бой көтөрбө. Бүгүн алсыз көрүнгөн эртең көтөрүлүшү мүмкүн, күчтүү көрүнгөн болсо жеңилиши мүмкүн.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"teacher-hello-do-you-remember-me","title":"Саламатсызбы, агай, мени эстедиңизби","paragraphs":["— Саламатсызбы, агай! Мени эстедиңизби? Бир кезде мектепте мага сабак бергенсиз.","— Ооба, эстедим. Башталгыч класста менин окуучум болгонсуң. Көп жылдан кийин сени кайра көргөнүмө кубанып турам. Азыр эмне иш кыласың?","— Мен да сизди көргөнүмө абдан кубанычтамын. Мен да сиздей мугалим болдум.","— Абдан жакшы. Мугалим болууну эмнеге чечтиң?","— Анткени бир кезде сиз мугалим катары мага дем берип, жашоодо үлгү болгонсуз. Ошондуктан мен да мугалим болуп, балдардын өсүп-жетилишине салым кошууну, аларды жашоодо ийгиликке жетүүгө шыктандырууну чечтим.","— Мындай ойдо болуп, мугалимдикти тандаганыңа кубанычтамын. Бирок сен мени бир кезде өзүңө дем берип, үлгү болгон дедиң. Так эмнени айтып жатасың?","— Сиз бизге сабак берип жүргөндө, класстагы балдардын бирине ата-энеси кооз саат сатып берген эле. Менин ата-энемдин шарты жок болгондуктан, мага саат алып бере алышчу эмес. Ал саат мага аябай жагып, бир күнү чоң танаписте аны тиги баланын чөнтөгүнөн уурдап алдым. Танапистен кийин бала сааты уурдалганын сизге айтты. Сиз класстагы окуучуларга кайрылып, саатты ким алса, кайра кайтарып беришин сурадыңыз. Эч ким үн катпаганда, бөлмөнүн эшигин жаап, бардык балдардын чөнтөгүн текшерериңизди айттыңыз. Ошондо ичимден: «Бул менин жашоомдогу эң уят учур болот», — деп ойлодум.","Балдар дубалды бойлой тизилишти. Сиз баарына көзүн колу менен жабууну буйрудуңуз. Анан бирден бардык балдардын чөнтөгүн текшердиңиз. Саатты менин чөнтөгүмдөн тапкандан кийин да калган окуучулардын чөнтөктөрүн текшерүүнү уланттыңыз жана акырында аны ким уурдаганын эч кимге айтпадыңыз. Ал тургай жыл бою бул окуя тууралуу мага да, ата-энеме да бир ооз сөз айткан жоксуз. Саатты жөн гана ээсине кайтарып бердиңиз. Ошол күнү менин кадыр-баркымдын тебеленишине жол бербедиңиз, балалык акылсыз жоругумдун айынан «ууру», «жалганчы» атка конуудан сактап, мени кечирдиңиз.","Ал окуя мага чоң сабак болду. Чыныгы мугалим окуучусуна билим гана берген адам эмес экенин түшүндүм. Ал туура баалуулуктарды сиңирген, катасы үчүн жазалабай, андан сабак алууну үйрөткөн, окуучусун жашоого байланыштырган адам экен. Дал ошол учурда келечекте мен да сиздей мугалим болууну чечтим.","Мугалим бул окуяны угуп, таң калат. Жигит сурайт:","— Бул окуяны эстеген жоксузбу? Саатты менин чөнтөгүмдөн тапканыңызды унуттуңузбу?","— Окуяны эстедим, болгону саат сенин чөнтөгүңдөн чыкканын билчү эмесмин.","— Кандайча саат менин чөнтөгүмдөн чыкканын билген эмессиз? Аны өзүңүз менин чөнтөгүмдөн тапкансыз да!","— Анткени окуучулардын чөнтөктөрүн текшерип жатканда мен да көзүмдү жумгам...","Сабак: Адамдын кемчилигин бетине чаппай, көзүн жумуп аны коргоо — чыныгы мугалимдик. Кадыр-баркы сакталган адам катасынан сабак алып көтөрүлөт.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"blind-well","title":"Суусу соолгон кудук","paragraphs":["Күндөрдүн биринде бир дыйкандын эшеги суусу соолуп калган кудукка түшүп кетет. Сааттар өтөт. Акыры эшектин жан кейиткен үнүн уккан ээси менен кошуналары чогулуп келип, аны куткаруунун жолун издей башташат. Ар ким ар нерсени сунуштап отуруп, соңунда эшекти кудуктан чыгаруу мүмкүн эмес деген бүтүмгө келишет. Жалгыз арга — кудукту топурак менен толтуруу деп чечишет. Ар бири колуна күрөк алып, тегеректен топурак ташып, кудукка төгө баштайт.","Бечара жаныбар үстүнө түшкөн топуракты силкип, бутунун алдына таптап турат. Ошол топурактын жардамы менен улам жогорулап отуруп, акыры кудуктун оозуна чейин көтөрүлүп чыгат. Эшектин кудуктан аман-эсен чыкканын көргөн эл аябай таң калат.","Сабак: Үстүңө түшкөн топуракты силкип, тепкич кыл. Аргасыздыктан чыгуу ыйлап отурууда эмес, силкинип күрөшүүдө.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"from-the-memoirs-of-a-lady-from-istanbul","title":"Стамбулдук бир айымдын эскерүүлөрүнөн","paragraphs":["1919-жыл эле. Стамбул толугу менен англиялыктардын баскынчылыгы алдында болчу. Орто мектепти жаңы эле бүткөм.","Сулуу кыз элем, үйүбүзгө жуучулар келип турчу. Бир күнү өзүн адвокат деп тааныштырган бир жигит жуучулары менен үйүбүзгө келди. Келбеттүү, узун бойлуу бул жигитти көрүп жактырдым. Сөйкө салынды. Сүйлөшкөн жигитимди сүйчүмүн... Бактылуу үй-бүлө курайын деген тилек менен таң аткыча чырактын жарыгында майда сүлгүлөрдү токуп, себимди даярдачумун.","Бир күнү аймакка ушак тарады.","«Айшенин сүйлөшкөн жигити адвокат эмес экен, мечиттин алдында табыт көтөрүп жан багат турбайбы», — дешти.","Дүйнөм астын-үстүн болду. Атам экөөбүз мечитке барып, алыстан байкадык. Анын чынында эле табыт көтөрүп жүргөнүн көрдүк.","Катуу селт эттим. Сөйкөнү кайтарып, ажыраштык.","Беш жыл өттү. Турмушка чыгып, бир балалуу болгом. Өлкөбүз эми эркин эле.","Бир күнү шаардан аны жолуктурдум. Уулум да жанымда болчу.","Мени көрүп токтоду. Тартынып: «Убактыңыз болсо, сизди бир чыны чайга чакырсам дейм», — деди. Макул болдум. Бир кеңсеге кирдик.","Бул юридикалык фирма экен; эшиктеги тактайчада анын аты жазылып туруптур. Ичинде жардамчылары иштеп жатышты.","— Чын эле адвокатсыңбы? — деп сурадым.","— Ооба, — деди.","— Анда адвокат болсоң, эмне үчүн мечиттин алдында табыт көтөрүп жүрдүң эле?","Ал башын жерге салып: «Мени кечир», — деди.","«Стамбул баскынчылык алдында болчу. Тегерек-четибиз англиялык жоокерлерге толуп, алар баарын, ар кимди катуу текшеришчү. Биз болсо Анадолуга, Улуттук күчтөргө жардам берүү үчүн, маркумду узаткандай түр көрсөтүп, ичине курал-жарак толтурулган табыттарды жөнөтүп турчубуз. Бул өлкө үчүн өмүр менен өлүмгө тете маанилүү милдет эле. Муну сага да айта алмак эмесмин...»","Сабак: Көргөнүңө карап шашылыш өкүм чыгарба. Ар бир иштин артында билбеген чындыгың болушу мүмкүн. Эркиндигибизди өзүн арнаган адамдардын эмгегине жана курмандыгына милдеттүүбүз.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"properties-of-water","title":"Суунун касиеттери","paragraphs":["Суунун касиеттерине назар салыңыз:","— дарак менен достошсо, аны тирүү кармайт;","— отко жолукса, аны өчүрөт;","— кирге жолукса, аны тазалайт;","— унга аралашса, аны камырга айлантып, бышырууга даярдайт;","— күн нуру менен кошулса, асан-үсөн жаралат;","— акса, жашоо тартуулайт;","— токтоп калса, сазга айланып, сасый баштайт.","Адамдын жүрөгү да сууга окшош: баарлашканда жанданып, жалгыздыкта соолуйт.","Сабак: Адамдын жүрөгү суу сыяктуу: баарлашканда жанданат, жалгыздыкта туруп калып соолуйт. Адамды тирүү кармаган — башка адамдар.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"it-wont-go-to-waste","title":"Текке кетпейт","paragraphs":["Чын жүрөктөн жасалган жакшылык,","сүйүү менен коштолгон мамиле,","чын ыкластан айтылган сөз,","адеп-ахлакка сугарылган жүрүм-турум,","махабатка боёлгон жылмаюу,","акыйкаттык үчүн ташталган кадам,","руханий баалуулуктарга көрсөтүлгөн урмат —","эч качан текке кетпейт. Мунун баары башкалардын жолун жарык кылып, өзүңдүн өмүрүңө да нур, ден соолук жана көрк кошот.","Сабак: Жүрөктөн жасалган жакшылык, сөз жана иш эч качан жоголбойт; башкалардын жолун жарык кылат жана өз өмүрүңдү да нурлантат.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"to-be-full-or-to-be-gone","title":"Ток болуу же жок болуу","paragraphs":["Бөлүшсөк — ток болобуз,","бөлүнсөк — жок болобуз.","Юнус Эмре","Сабак: Бөлүшкөндө күчөйбүз, бөлүнгөндө алсырап жок болобуз. Ынтымакты сактоо үчүн билимибизди арттырып, руханиятыбызды бийик тутушубуз керек.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"life-lesson","title":"Турмуш сабагы","paragraphs":["Ата карышкыр бөлтүрүгүнө турмушту үйрөтүп жатып, койлорду көрсөтүп мындай дейт:","— Карачы, алардын эти даамдуу болот.","Андан соң койчуну көрсөтөт:","— Анын таягы болсо ачуу тиет. Этият бол.","Бөлтүрүк койчунун жанындагы итти көрүп, сүйүнүп кетет:","— Ата, карачы, тигил бизге окшош экен!","Ата карышкыр жооп берет:","— Аны көргөндө эле кач, балам. Бизге эң көп зыян келтиргендер — бизге окшошуп туруп, бизден болбогондор.","Сабак: Кээде эң чоң зыян бизге окшоп, бирок ниети башкалардан келет. Өзүңдү коргош үчүн сырткы окшоштукка алданба, эки жүздүүлүктү өз убагында сез.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"sowing-millet-at-the-bottom","title":"Түбүнө таруу айдоо","paragraphs":["Бир күнү падыша жөкөрлөрү менен сейилге чыгат. Жол боюндагы бир айылдан өз талаасына көчөт отургузуп жаткан карыяны көрүп, алыстан үн катат:","— Ата, бул көчөттөрдү эмнеге отургузуп жатасыз? Машалла, жашыңызды жашап калдыңыз; булардын мөмөсүн жегенге өмүрүңүз жетпесе керек.","Карыя өкүмдарга мындай жооп берет:","— Бул көчөттөрдүн мөмөсүн сөзсүз эле биз жешибиз шарт эмес, балам. Бизден мурункулар отургузган көчөттөрдүн мөмөсүн биз жегендей, биз отургузгандардын мөмөсүн да бизден кийинкилер жейт.","Бул жооп өкүмдарга жагып, карыяга бир кап алтын берүүнү буюрат.","Карыя алтын толгон капты көрсөтүп мындай дейт:","— Көрдүңбү, балам? Биз отургузган көчөт азыртан эле мөмө берди.","Бул жооп да өкүмдарга жагып, карыяга дагы бир кап алтын берүүнү буюрат. Кары дыйкан жөнөкөй адам эмес эле — көптү көргөн, зирек кишилерден болчу:","— Балам, ар ким отургузган көчөт жылына бир жолу мөмө берет, биз отургузган көчөт болсо эки жолу мөмө берип үлгүрдү.","Бул жоопту да жактырган өкүмдар карыяга дагы бир кап алтын берүүнү буюрат. Бирок бул жолу вазир кийлигишип, өкүмдарды оюнан кайтарууга аракет кылат:","— Оо, падышам! Бул жерден тезирээк кетели. Болбосо, бул карыя талаасына көчөт эмес, казынабыздын түбүнө таруу айдап коёт!","Сабак: Адам өзү үчүн гана жашабайт. Бизден мурункулар тиккенди биз жедик; биз да кийинкилер үчүн тигишибиз керек.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"hayats-life-story","title":"Хаяттын жашоо баяны","paragraphs":["Апам үйүбүздү, атамды жана бизди таштап кеткенде, мен алтыда, агам сегиз жашта эле. Апамдын атамдан кеткенин ошол курагымда эле түшүнгөм, бирок бизди таштаганын түшүнө алган эмесмин. Эне да балдарын таштап кетеби?","Атам апамды сабачу. Мени да, агамды да урчу. Ошондон улам эркектердин баары аялын, балдарын сабайт деген ойго ишенип калгам...","Энесиз үй төрт дубалдан гана турарын апам кеткенден кийин билдим. Эртең менен «колу-бетиңерди жууп келгиле, тамагыңар даяр» деген да, бир нече күн ачка калсаң «ачкасыңбы?» деп сураган да болбой турганын түшүндүм. Бирок үйрөнгөндөрүмдүн ичинен жанымды эң катуу оорутканы ушул болду: эненин жыты жок болсо, бала канча жашта болбосун, заматта чоңоёт экен. Мен да алты жашымда чоңойдум.","Апам үйдөн кеткенден он күндөй өткөндө, үйүбүзгө полиция кызматкерлери келишти. Айткан сөздөрүнө караганда, апам өз жанын кыйыптыр. Колунда бекем кысып кармаган бир конверт болуптур. Анын сыртына «кызым менен уулума берилсин» деп жазылыптыр.","Ал кезде окуганды билчү эмесмин, кантип окумак элем? Агам окуду. Катты угуп жатып мен да ыйладым. Агам да ыйлады.","Апам үйдөн кеткенде төркүнүнө барыптыр. Атасы катуу ачууланыптыр. Көрсө, аял күйөөсүнүн үйүндө отурушу керек экен; оозу канга толсо да, «кызыл шербет ичтим» деши керек тура. Апам таятама: «Бир ай силерде турайын, анан бир айласын табам. Балдарымды жаныма алып, жаңы турмуш баштайм», — деп жалыныптыр.","Кой-ай, кой-ай, кой-ай! Аял жалгыз жашайт имиш. Таятамдын намысын беш тыйын кылат имиш, элдин бетин карай албай калат имиш; кызы өлүп калса, андан жакшы болмок имиш. Ошол кечте апам өзүн асып коюптур. Мунун баарын мага жылдар өткөндөн кийин, мен он тогуз жашка чыкканда, таенем өлүм төшөгүндө жатып айтып берди.","Атам апамдын өлгөнүн укканда такыр кайгырган жок. Бизди балдар үйүнө өткөрүп берерин айтты. Эми ошол жерде жашап, ал жер биздин үйүбүз болмок экен. Бир туугандар бири-биринен бөлүнүп, бири-бирин унутуп, жылдар өткөн соң тааныбай калышы мүмкүн болгондуктан, экөөбүз тең апамдын катын сакташыбыз керек имиш.","Бир катты экөөбүз кантип сактайбыз деп сураганга үлгүрбөй жатып, агам аны кайчы менен ортосунан кести. Сүйлөмдөрдүн баш жагын мага берди. Сүйлөмдөрдүн башы менде болгондуктан, окуганды үйрөнгөндө уландысын өзүм болжошум керек экен. Агам болсо катты ансыз да жаттап алган эле.","Бизди балдар үйүнө берерин уккан таежем келди. Атамга: «Кыз баланы балдар үйүнө беришпейт. Хаятты мен алып, өзүм чоңойтом», — деди. Кыз баланы эмне үчүн балдар үйүнө берүүгө болбой турганын таежем менен жашай баштаганда түшүндүм: кыз бала үйдө жумшалчу акысыз кызматчы дегенди билдирет экен. Таежем мени бир күн да өз атым менен чакырган жок. Эми менин атым «Келчи» болуп калган: «Келчи, суу алып кел... Келчи, бул идиштерди жууп кой...»","Агам айына бир жолу таежемдикине мени көргөнү келчү. Балдар үйүндө жакшы жашап жатканын айтчу. Мен да жакшы жашап жатканымды айтчумун — агамды капа кылгым келчү эмес. Балким, агам да мен кайгырбасын деп «жакшы жашап жатам» дечү беле? Муну сураганга эч качан батынбадым.","Мектепке бардым. Класста окуганды эң биринчи мен үйрөндүм. Кантип үйрөнбөй коёюн — апамдын катын окушум керек эле. Каттын менде калган бөлүгү «Хаят, сулуу кызым, мен сени...» деген сөздөр менен башталчу. Ар түнү төшөгүмдө жатып ошол сүйлөмдү толуктоого аракет кылчумун:","«Хаят, сулуу кызым, мен сени абдан жакшы көрөм».","«Хаят, сулуу кызым, мен сени абдан сагындым».","«Хаят, сулуу кызым, мен сени күтүп жатам».","Сүйлөмгө кошкон сөзүмө жараша кыял курчумун. Кыялдарымда абдан бактылуу элем. Адам кайгылуу кыял курабы?","Орто мектепти бүтүрдүм. Таежем мындан ары окубай турганымды айтты. Бирок мен окугум келчү — билим алып, өз бутума туруп, агам менен бир үйдө жашоону самачумун.","Ошол жайда биздин көчөдөгү дүкөнчү, үч балалуу Хасан байкенин аялы рак оорусунан каза болду. Абдан кайгырдым. Үч бала эми эмне кылат, эненин жытын кайдан табат? Энелер эмне үчүн өлөт? Ал үч бала да мен сыяктуу өз атын унутуп, «Келчи» болуп калабы?","Мен Хасан байкенин балдарына боорум ооруп жүргөндө, ага кудалашып коюлганым белгилүү болду. Көрсө, сегиз билерик менен үч миң лирага сатылыптырмын. Расмий никеге жашым жетпегендиктен, кырк күндөн кийин Хасан байке экөөбүздүн никебиз кыйылды.","Мен он беш жашта элем. Хасан байкенин аялы болдум. Эки, беш, алты жаштагы үч балам бар эле. Анан дагы ортобузда өз балабыз болсун деп көшөргөн таежем бар болчу... Өз балам төрөлсө гана ордум бекем болуп, Хасан байке башка аялдарга көз артпайт имиш.","Хасан байкеден биринчи жолу аны «Хасан байке» дегеним үчүн жаакка жедим. Аял да күйөөсүнө «байке» дейби? Апамдан алты жашымда айрылганда унчукпоону үйрөнгөм. Ошондуктан «Бир эркек он беш жаштагы кызды аялым деп атайбы?» деген суроону бербей, дагы унчукпай калдым.","Хасан байке мени чапканда, үч бала тең атасынын бутуна жармашып: «Хаят эжебизди урба, ал биз менен ойнойт, бизге жомок айтып берет», — деп жалынды. Мен ал балдардын эжеси элем. Ал эми жомок деп айтып бергендерим — өз кыялдарым болчу.","Хасан байке үйдөн кеткенде, күзгүнүн алдына туруп, «Хасан» дегенди үйрөнмөк болдум. «Хасан» деген сайын анын чачы түшкөн башы, мурдунун үстүнө түшүп турган көз айнеги, чыккан курсагы көз алдыма тартылчу. «Хасан» деген сайын күнөө кылгандай уялып, ага атынан кайрыла албай койдум. Күзгүнүн алдында машыгып жатканымда, Хасан байкенин алты жаштагы уулу жаныма келип: «Хаят эже, апам атама «мырза» дечү, сен да «мырза» де», — деп мага дем берди.","«Мырза» — албетте, «мырза» жакшы болмок. Эңкейип, кара көздүү, кыялдарымды жомок деп уккан Самини өптүм. Беш жаштагы Элиф менен эки жаштагы Зехраны да чакырып, аларга жомок айта баштадым. Ал күнү жомогумду мындай баштадым: «Илгери-илгери алты жаштагы аты Жомок болгон кыз жашаптыр. Жомок апасынан айрылыптыр. Ал апасын бардык жерден издеп, таба албаганда Кыялдар өлкөсүнө кетиптир. Жомок ал жерде ушунчалык бактылуу болгондуктан, чыныгы дүйнөгө эч качан кайтып келбептир».","Менин жомогумдагы Жомок дайыма бактылуу, дайыма жылмайып жүрчү. Бул жомокту балдарга күн сайын айтып берчүмүн. Биз абдан бактылуу элек.","Хасан байке да жакшы адам болчу. Эми аны «Мырза» дечүмүн. Кээде ачууланчу, бирок мен себебин түшүнчүмүн: ал бир аялдын ордуна сегиз билерик жана үч миң лирага жомокчу эжени сатып алган эле.","Агам мени көргөнү келип турчу. Ар келген сайын апамдын катынын өзүндө калган жарымын бергиси келчү. Мен албай койчумун. Анткени каттын экинчи жарымын окусам, Кыялдар өлкөсүнөн таш боор, чыныгы дүйнөгө кайтып келип, бактысыз болуп каламбы деп коркчумун. Менин бүт кыялдарым каттын ошол экинчи жарымына курулган эле.","Кырк жашка чыкканымда, жомогумду угуп чоңойгон балдарым эр жетип калышкан. Сами дарыгер болуп, башка шаарга дайындалып, үйүбүздөн көчүп кеткен эле. Маанайы чөккөндө мага телефон чалып: «Хаят эже, мага бир жомок айтып берчи», — дечү.","Элиф мугалим болуп, турмушка чыккан. Бир кыз неберелүү болдум. Атын Хаят койгулары абдан келди, бирок уруксат берген жокмун. Элиф: «Анда небереңиздин аты Жомок болсун», — деди. Ошентип, неберемдин аты Жомок болду.","Кичүү кызым Зехра ветеринар болду. «Хаят эже, кайсы жаныбар тынчы кетсе, жомок айтып берем, ошондо тынчып калат», — дечү. Зехра да турмушка чыгып, бир уул неберелүү болдум.","Кырк беш жашка чыкканымда Хасан байке, башкача айтканда, Мырзам дүйнөдөн кайтты. Абдан кайгырдым. Анын акыркы сөзү: «Менден акыңды адал кыл», — болду. Мен чын жүрөктөн, толук ыкласым менен ага болгон акымды адал кылдым. Ал жакшы адам эле.","Бирок акымды —","он беш жаштагы кыздарды турмушка берүүдөн эч кандай жамандык көрбөгөндөргө жана муну колдогондорго;","күн сайын зомбулук көрүп жатканын билип туруп, кызынын ажырашуусун намыссыздык деп эсептеген адамдарга жана бул ойду актагандарга;","жарадар куштай айласыз, үмүтсүз калган өз балдарына ырайымсыз мамиле кылгандарга жана аларды колдогондорго —","адал кылбайм!","Сабак: Сокур адат жана туура эмес «намыс» түшүнүгү аялдын, баланын өмүрүн кыйратышы мүмкүн. Эрте никеге, зомбулукка жана кайдыгерликке көз жумгандар бул зулумдун шериги.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"windmill-turning-in-still-air","title":"Шамалсыз абада айланган жел тегирмен","paragraphs":["Шамалсыз абада айланган жел тегирменди сөзсүз бирөө үйлөп турат.","Эскимос макалы","Сабак: Эч нерсе себепсиз болбойт. Окуянын артындагы күчтү көрбөсөк да, анын таасирин натыйжасынан түшүнө алабыз.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"two-bowls-of-water","title":"Эки чөйчөк суу","paragraphs":["Байыркы заманда байлыгы менен атагы чыккан бир өкүмдар болуптур. Ал кайда барбасын, байлыгынын бир бөлүгүн ала барып, элге көрсөтүп мактанчу экен. Өкүмдардын эң ишенимдүү, акылман устаты бар эле. Бир күнү андан: «Сен көптү көргөн адамсың. Менин бийлигим жана байлыгым тууралуу эмне ойлойсуң?» — деп сурайт.","Акылман анын көзүнө карап мындай дейт: «Өкүмдарым, элестетели: өтө ысык, учу-кыйыры көрүнбөгөн чөлдө калдыңыз. Өлүп калбашыңыз үчүн бир чөйчөк суу берген адамга байлыгыңыздын жарымын бересизби?» «Албетте, берем», — дейт өкүмдар. Акылман: «Бир аздан кийин суусаганыңыз андан бетер күчөдү дейли. Кийинки чөйчөк суу үчүн байлыгыңыздын калган жарымын да берет белеңиз?» Өкүмдар бир аз ойлонуп: «Өлбөш үчүн, албетте, берет элем», — дейт.","Акылман жылмайып: «Анда, өкүмдарым, анча мактанбаңыз. Анткени байлыгыңыздын баасы болгону эки чөйчөк суу экен», — дейт.","Сабак: Байлыктын баасы шартка жараша болот: чөлдө бүт байлык болгону эки чөйчөк суу. Байлыгың менен мактанба — анын баасы өткүнчү.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"three-statues","title":"Үч айкел","paragraphs":["Коңшулаш эки өлкөнүн өкүмдарлары жакшы дос эле. Бир күнү алардын бири экинчисине туулган күнүнө белек жөнөтүүнү чечет. Өлкөсүнүн эң мыкты айкелчисин алдына чакырып, ага алтындан бир карыш бийиктиктеги, бири-бирине куюп койгондой окшош үч айкел жасоону тапшырат. Бирок айкелдердин ортосунда өкүмдар менен айкелчи гана билген бир айырма болмок.","Айкелдер даяр болуп, туулган күнүндө коңшу өкүмдарга жөнөтүлөт. Белекке кошулган катта мындай деп жазылган эле: «Туулган күнүңүз менен ушул үч алтын айкел аркылуу куттуктайм. Бир караганда айкелдер бири-биринен айырмасы жоктой көрүнүшү мүмкүн. Бирок алардын бири калган экөөнөн баалуураак. Ошол айкелди тапканыңызда мага кабар бериңиз».","Белекти алган өкүмдар адегенде айкелдерди таразага тарттырат. Алардын салмагы граммына чейин бирдей экени аныкталат. Башка да текшерүүлөр жүргүзүлөт, бирок жыйынтык чыкпайт.","Өкүмдар өлкөсүндөгү өнөрдү түшүнгөн адамдардын баарын сарайына чакыртат. Ар ким айкелдерди кылдат изилдейт, бирок айырмасын таба албайт. Күндөр өтүп, айла табылбайт.","Акыры бир күнү өкүмдарга бул табышмакты чече турган адам бар экенин кабарлашат. Аны дароо таап, сарайга алып келишет. Ал айкелдерди кылдат карап чыгып, ичке зым алып келүүнү суранат. Зымды биринчи айкелдин кулагына салса, экинчи кулагынан чыгат. Экинчи айкелдин кулагына салса, оозунан чыгат. Акыры үчүнчү айкелдин кулагына салганда, зым ичинде туруп калат. Ошентип, айкелдердин айырмасы билинет.","Өкүмдар айкелдерди жөнөткөн коңшусуна мындай жооп жаздырып жөнөтөт:","«Бул үч айкел үч башка адамдын түрүн туюнтат. Укканын:","— бир кулагынан киргизип, экинчисинен чыгарган;","— ошол замат оозунан чыгарып жиберген;","— жүрөгүндө сактай билген.","Эң баалуу адам — укканын жүрөгүндө сырдай сактап, зарыл жерде, өз убагында гана айта билген адам. Бул баалуу белегиңиз үчүн чоң рахмат».","Сабак: Тилди тийиштүү жерде кармай билүү да акылмандык. Сырды сактап, керектүү сөздү керектүү жерде айткан адамдын баркы бийик.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"three-landscapes","title":"Үч көрүнүш","paragraphs":["Сапарга чыккан бир жигит жолдон үч таң калычтуу көрүнүшкө туш болот.","Биринчи көрүнүш мындай эле: бир нече киши талаага буудай сээп жатышкан. Буудайдын даны жерге түшөрү менен өсүп чыгып, ошол замат түшүм берет. Бирок дыйкандар түшүмдү жыйноонун ордуна талааны өрттөп жиберишет.","Экинчи көрүнүштө бир киши чоң ташты жерден көтөрүүгө аракет кылат, бирок колунан келбейт. Чоң таштын үстүнө дагы бир таш койгондо гана көтөрө алат. Үчүнчү ташты кошкондо андан да оңой көтөрөт. Жигит канча караса да эч нерсе түшүнбөй, жолун улантат.","Жолдо көргөн үчүнчү таң калычтуу көрүнүш мындай болот: бир киши койдун белине минип алган, дагы бир нече киши анын ийнине жармашкан. Кой катуу чуркайт; алардын артынан бир нече адам канча чуркаса да жетише албайт.","Жигит көргөндөрүн канча ойлонсо да, маанисин түшүнө албай, бир шаарга жетет. Кире бериш дарбазанын жанынан нур жүздүү карыяны көрүп салам берет. Карыя алик алып, аны токтотуп маек курат. Жигит жолдо көргөндөрүн айтып берет, карыя болсо аларды мындайча чечмелейт:","— Сен көргөн дыйкандар, буудай талаасы жана аны өрттөгөн адамдар кимдер экенин билесиңби? Алар — адегенде жакшылык кылып, анан кылганын элге айтып, анын баркын жок кылгандар.","— Таш көтөргөн кишинин көрүнүшү муну билдирет: адамга биринчи жолу күнөө кылуу өтө оор. Бирок күнөө кылгандан кийин тообо кылбаса, кийинки күнөөлөр ага өтө жеңил сезилет. Тообосуз калган бир күнөө — башка күнөөгө ачылган эшик.","— Кой менен анын үстүндөгү адамдар тууралуу болсо, кой бейиштин жаныбары экенин жана жонуна мингендерди бейишке жеткирерин унутпа. Койго биринчи мингендер — аалымдар. Аалымдардын ийнине жармашкандар — ар түрдүү катмардагы ыймандуулар. Алардын артынан чуркагандар болсо ишенбегендер, динсиздер.","Сабак: Айтып баасы түшүрүлгөн жакшылык, тообосуз күнөө жана чыныгы жетекчинин артынан ээрчөө — ар бири жашоонун жашыруун бир сабагы.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"three-questions","title":"Үч суроо","paragraphs":["Падыша вазирин алдына чакырып мындай дейт:","— Сага үч суроо берем. Эртеңге чейин жообун таппасаң, сарайдан куулуп чыгасың. Биринчиси: Кудай эмнеге чыдайт? Экинчиси: Кудай кайсы чындыктарды жашырат? Үчүнчүсү: Кудай Өз даанышмандыгы жана кудурети менен кайсы иштерди ишке ашырат?","Вазир канча баш катырса да, суроолорго жооп таба албайт. Кечинде көңүлү чөгүп үйүнө кайтат. Анын акылдуу жана зирек бир кызматчысы бар экен. Кызматчы кожоюнунун кабагы салыңкы экенин көрүп, себебин сурайт. Вазир башынан өткөндөрдү айтып берет.","Кызматчы мындай дейт:","— Үч суроонун тең жообун билем. Экөөнү азыр айтайын, үчүнчүсүн эртең айтам. Кудай чыдап жүргөн нерсе — пенделеринин кайгы-муңу, жашырганы болсо алардын айыптары.","Эртеси вазир падышага барып, ушул эки жоопту айтат. Падыша мындай дейт:","— Туура. Бул жоопторду өзүң таптыңбы же сага бирөө үйрөттүбү?","Вазир чындыкты айтат:","— Акылдуу, зирек кызматчым үйрөттү.","Муну уккан падыша вазирге чепкенин чечип, кызматчысына берүүнү буюрат. Ошентип, вазир вазирлик чепкенин чечип кызматчысына кийгизет, өзү болсо анын эски кийимин киет.","Айран-таң калган вазир кызматчыдан сурайт:","— Үчүнчү суроонун жообу кандай? Кудай Өз даанышмандыгы жана кудурети менен кайсы иштерди ишке ашырат?","Кызматчы жылмайып мындай дейт:","— Дагы эле түшүнбөдүңбү? Кудай бир көз ирмемде вазирди кызматчы, кызматчыны болсо вазир кылат!","Сабак: Мансап түбөлүк эмес. Бүгүн буйрук берген эртең өзү кызмат кылышы мүмкүн. Эч ким өз ордуна ишенип калбасын.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"dead-remain-in-life","title":"Өлгөн — жашоодо калганы","paragraphs":["Бири-бирин жанындай көргөн эки адамдын бири дүйнөдөн кайтса, чыныгы өлгөн — жашоодо калганы.","Сабак: Ажырашуу сүйүүнүн тереңдигин дагы да сездирет. Артта калганы сагыныч менен жашайт жана өзүн тирүүлөй өлгөндөй сезет.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"life-is-short","title":"Өмүр кыска","paragraphs":["Өмүр кыска. Аны сени кубанткан жана сүйүктүү экениңди сездирген адамдар менен өткөр.","Сабак: Кыска өмүрүңдү көңүлүңдү көтөрүп, сени сүйгөн адамдар менен өткөр. Сага жакшылык алып келбеген мамилелерге убактыңды коротпо.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"living-in-the-past","title":"Өткөн менен жашоо","paragraphs":["Өткөн менен жашоо — артыңды карап алып жол жүргөндөй. Алдыңды карабаганың үчүн улам мүдүрүлүп жыгыласың; артта калганды өзгөртө да, алдыңдагы эшиктерди ача да албайсың.","Сабак: Өткөндү кайтара албайсың; жүзүңдү алдыга бур, алдыңдагы мүмкүнчүлүктөрдү көр. Артыңды эле карай берсең, алдыңдагы тоскоолдукту көрбөйсүң.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true}]},{"title":"Эмгек, ырыскы жана байлык","slug":"emek-ruzi-ve-servet","blurb":"Эмгек, ырыскы жана байлыкка көз караш.","count":19,"stories":[{"stem":"grocery-shop-and-the-supermarket","title":"Азык-түлүк дүкөнү жана супермаркет","paragraphs":["Конушубузда бир кары аялдын азык-түлүк дүкөнү бар эле. Күндөрдүн биринде анын маңдайына супермаркет ачылды. Экөө тең дүкөнүнүн алдындагы тактага азык-түлүктүн баасын жазып иле башташты. Супермаркет «Сары май — 70 манат» деп жазганда, аял «Бизде сары май — 60 манат» деген жарыя илди. Эртеси супермаркет «Сары май — 50 манат» деп жарыялады; эжеке да дароо тактасын «Бизде сары май — 40 манат» деп өзгөрттү.","Бул жагдайга тынчсызданган конуш тургундарынын бири аялга кайрылды:","— Эжеке, бул супермаркет менен атаандашпай эле койгонуңуз жакшы. Алардын мүмкүнчүлүгү чоң, бааны түшүрсө да зыян тартпайт, сиз болсо банкрот болуп каласыз.","Аял камырабай жооп берди:","— Мен сары май сатпайм да... Эл жок дегенде арзан сатып алсын.","Сабак: «Эмне таптым?» эмес, «кимге пайдам тийди?» деген суроо менен жашаган адам башка. Пайда көздөбөй берген адам чынында эң көп уткан адам.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"everyone-has-work-to-do","image":"wisdom-stories/Bakhtiyar%20Sirajov/illustrations/everyone-has-work-to-do.webp","title":"Ар кимдин өз иши бар","paragraphs":["Акылман мугалимдерден таалим алганым — чоң бактым. Алардын бири адабият мугалимим, урматтуу Балададаш агай эле. Ал: кимдир бирөө силерден бир нерсе сураса же иш тапшырса, кандайдыр бир себеп менен аткара албай калсаңар да, ага эч качан «ишим көп болуп, убактым жетпей, бүтүрө албай калдым» дебегиле — бул чын болсо да. Анткени мындай сөз адамды «менин ишим жокпу, аны бекер убара кылдымбы?» деп ойлонууга мажбурлайт, — дечү.","Ар кимдин өз иши бар. Адам силерди боштуктан эмес, силерге муктаж болгондуктан убара кылат. Силерге кайрылган адамды көңүл сыртында калтырбагыла, унчукпай аны күттүрбөгүлө. Ишти аткарууга мүмкүнчүлүгүңөр жок болсо, созбой билдиргиле, адамды белгисиздикте кармабагыла. Анткени ал силерден үмүт кылып, ишенип жатат. Көп убакыт өткөндөн кийин «убактым болгон жок» десеңер, өзүңөргө болгон ишенимди талкалайсыңар.","Сабак: Башкалар сени ишенимсиз, ишенимге татыксыз адам катары билип турганын сезип жашоо өтө ачуу.","Бахтияр Сиражов"],"hasAudio":false,"hasImage":true},{"stem":"garden-and-the-gardener","title":"Бак жана багбан","paragraphs":["Мугалим студенттерине кайрылат:","— Багбан бакты карап жатат деп элестеткиле. Элестеттиңерби?","— Ооба, — деп жооп беришет студенттер.","Мугалим олуттуу үн менен айтат:","— Эми айтарымды жакшылап эсиңерге түйгүлө: бак багбандын аркасында өсөт деп айтууга болбойт, бирок бак өзүнөн өзү өсөт деген да туура эмес.","Сабак: Өсүп-жетилүүдө өз аракетиңдин да, сага кам көргөндөрдүн да үлүшү бар. Бирин баалап, экинчисин жокко чыгарба.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"fish-shop","title":"Балык дүкөнүндө","paragraphs":["Жумуштан чыккан бир киши аялдамага баратканда балык дүкөнүнүн жанынан өттү. Кызы менен жубайы балыкты жакшы көрөрүн ойлоп, аларды кубантуу үчүн ичкери кирди.","Сатуучудан адегенде бир килограмм, анан эки килограмм балык тартууну өтүндү. Ошол маалда үстүндөгү кийими жупуну кары аял тартына жакындап келип сурады:","— Балам, мага да балык алып бересиңби?","Киши эч ойлонбостон сатуучуга кайрылды:","— Төрт килограмм тарт: экөө меники, экөө эжекеники.","Андан кийин аялдан наны бар-жогун сурады. «Жок» деген жоопту укканда, маңдайдагы дүкөндөн төрт нан сатып алып, анын үлүшүн берди.","— Дагы бир каалооңуз барбы, эжеке?","Аял чөнтөгүнөн бош дары шишесин чыгарды. Бул эки ай мурун сатып алган көз дарысы экенин, жаңысын алууга акчасы жетпегендиктен көзү начарлап баратканын айтты.","Киши дары сатып алуу үчүн дарыканага кетти. Окуяга көз салып турган балыкчы аялга отургуч берип отургузду. Киши жаңы дары менен кайтып келгенде, балыкчынын боорукерлигин көрүп кубанды.","Дарыны аялга сунуп, анан чөнтөгүндө калган акчанын баарын да ага берди. Аял бата берип, үйүнө жөнөдү.","Киши аялдаманы көздөй баратып, балыктын акчасын төлөбөгөнүн эстеди. Чөнтөгүндө акча калбаптыр. Балыкчы жылмайып:","— Бара бер, бир тууганым, адал болсун, — деди.","Жол киреси да калбагандыктан, киши үйүнө жөө жөнөдү. Кызына телефон чалып, балык алганын жана жакында барарын айтты. Жамгыр астында басып баратып, бүгүн бирөөгө пайдасы тийгенине шүгүр кылды; көз жашы жаагынан сызылып, жамгыр суусуна аралашты.","Сабак: Жакшылык үчүн чоң мүмкүнчүлүк күтпө; ал байлыктын эмес, кең жүрөктүн иши. Жүрөгү бай адам мүмкүнчүлүгү жок кезде да жакшылык жолун табат.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"chief-accountant-and-the-ceo","title":"Башкы бухгалтер жана башкы директор","paragraphs":["Башкы бухгалтер башкы директорго мындай дейт:","— Кызматкерлерибиздин өсүп-өнүгүшүнө убакыт да, каражат да жумшадык дейли. Бирок ошого карабай алар компаниябыздан кетип калышты. Анда эмне болот?","Башкы директор жооп берет:","— Аларга убакыт да, каражат да бөлгөн жокпуз дейли, алар болсо компаниядан кетпей, иштеп кала беришти. Анда эмне болот?","Сабак: Адамдын өнүгүүсүнө кеткен акча текке кетпейт. Бүгүн окутуудан аяган акчаң эртең ишиңе чоң зыян алып келиши мүмкүн.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"we-are-rich","title":"Биз байбыз","paragraphs":["IV кылымдын аягына жакын Жапонияда такта отурган император Нинтоку бир күнү бийик мунарага чыгып, өлкөсүн карайт. Асманга көтөрүлгөн бир да түтүн көрбөгөндө, эли жакырчылыкка батканын жана эч ким үйүндө тамак бышыра албай калганын түшүнөт.","Ал дароо жарлык чыгарып, элге үч жыл бою өздөрү үчүн гана иштөөнү буюрат. Сарай кызматкерлерин да үйлөрүнө жөнөтөт. Өзү үчүн иштеп, салык төлөбөгөн эл үч жылдын аягында молчулукка жетет.","Үч жылдан кийин мунарага кайра чыккан Нинтоку туш-туштан көтөрүлгөн түтүндү көрүп, бүт өлкөдө очоктор жанганына ынанат да, жанындагы жубайына кубанып:","— Эми биз байбыз! — дейт.","Императрица болсо үч жыл кароосуз калып эскирген, чатырынан суу аккан, гүлдөрү соолуган сарайды көрсөтүп:","— Муну сен байлык дейсиңби? — деп сурайт.","Нинтокунун жообу кылымдар бою жапондордун эсинен чыккан эмес:","— Элибиздин жакырчылыгы — биздин жакырчылыгыбыз, байлыгы болсо — биздин байлыгыбыз.","Сабак: Чыныгы байлык казынада эмес, элдин турмушунда. Жетекчини улук кылган кызматы эмес, ошол кызматта эли үчүн кылган иши.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"henry-fords-choice","title":"Генри Форддун тандоосу","paragraphs":["Айтымда, бир күнү «Ford Motor» автомобиль компаниясынын негиздөөчүсү Генри Форд анын компаниясында иштегиси келген эки жаш досту кечки тамакка чакырат. Экөө тең бир университетти бүтүргөн, өтө таланттуу, билимдүү адистер эле.","Кечки тамак желип, отуруш аяктайт. Ресторандан чыгып баратканда Форд жигиттердин бирине аны жумушка алганын айтат, экинчисине болсо ийгилик каалап, жумуш бере албай турганын билдирет. Көңүлү чөккөн жигит бүт кайратын жыйнап, Форддон сурайт:","— Форд мырза, биз кеч бою автомобиль да, инженердик жөндөм жөнүндө да сүйлөшкөн жокпуз, жалпы темаларды гана кеп кылдык. Бирок сиз досума жумуш сунуштап, мени мындай мүмкүнчүлүктөн ажыраттыңыз. Эмне үчүн ушундай чечим чыгардыңыз?","Форд мындай жооп берет:","— Караңыз, жигит, мунун эки себеби бар. Биринчиси: тамак бою экөөңөрдүн тең жүрүм-турумуңарды байкадым. Досуңуз адегенде тамактын даамын татып, андан кийин туз септи; сиз болсо алгач туз сээп, анан гана даамын таттыңыз. Мен байкап көрүп, кылдат ойлонгондон кийин гана өзгөртүү киргизүүгө чечим кабыл алган адамдарды баалайм.","— Экинчи себеби мындай: досуңуз тейлөөчүлөргө абдан сылык мамиле кылды, сиз болсо аларды көрмөксөнгө салып, мага гана сылыктык көрсөттүңүз. Адамдарга ээлеген кызматына карабай бирдей урмат менен мамиле кылуу керек.","Сабак: Адамдын мүнөзү майда кылык-жоругунан билинет: ойлонбой чечим чыгарганынан жана алсыздарга болгон мамилесинен.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"scarf-seller","title":"Жоолук сатуучу","paragraphs":["Түнкү кычыраган суук шаарды чулгап алган. Жер муз болуп, тайгак эле. Оозумдан чыккан дем да тоңуп калчудай. Жыгылып кетпеш үчүн өтө этият басып келаттым. Автобустун эшигине жакындап, аман-эсен жеткениме «Кудайга шүгүр» дедим. Дал ошол маалда колунда сатууга аракет кылган жоолуктары бар бир бала мага жакындады. Аны менен сүйлөшүүгө чамам жок эле; тезирээк автобуска отурсам деген гана ойдо болчумун.","Бала мага бир жоолук сунуп: — Аласызбы, эже? — деди. Андан кутулуш үчүн: — Жок, каалабайм, — дедим. — Алыңызчы, эже, керек болуп калат, — деди ал. Кутулайын деп: — Акчам жок, — дедим. — Мейли, эже, ала бериңиз, акча сурабайм, менден болсун, — деди. — Андай болбойт, каалабайм, жоолугум бар, — деп автобуска шашып кирдим. Ошол учурда өзүмдү гана ойлоп, балага такыр көңүл бурган жокмун. Тез-тез басып ордума жөнөдүм.","Отурардан мурун пальтомдун чөнтөгүндөгү телефонумду алуу үчүн колумду салдым. Колума бир баштык урунду. Алып чыгып карасам, ичинде жоолук бар экен. Аябай таң калдым. Көрсө, бала баштыкты байкатпай чөнтөгүмө салып коюптур.","Дароо автобустан түштүм. Бала баягы эле жерде жоолуктарын сатып жүрүптүр. Он эки-он үч жаштарда экен. Мурду сууктан кызарып, колдору колкапсыз эле. Үстүндө жука пальтосу бар. Капкара көздөрү түн ичинде жылдыздай жаркырап, жылмайганда аппак тиштери көрүнөт. Жанына барып, ийнине колумду койдум да, жоолукту көрсөттүм: — Бул эмне?","Бала жылмайып: — Эч нерсе эмес, эже, керек болуп калат, менден болсун, — деди.","— Ушинтип жүрсөң, кантип акча табасың? Бул суукта кыйналбайсыңбы? — дедим.","— Эч нерсе болбойт, эже, — деди ал мээрим төгүлгөн көздөрү менен.","Акчаны сундум.","— Жок, эже, кереги жок, менден болсун, — деди ал кайрадан.","Эгер ал: «Эже, акчам жок дебедиңиз беле, муну кайдан таптыңыз?» — деп жүзүмө караса, ошол замат уялганымдан жерге кирип кетмекмин. Бирок ал түз пейил, күнөөсүз, таптаза, жүрөгү кирдей элек, баарын өзүндөй аруу көргөн бала эле.","— Муну ал, — дедим да, чечкиндүү түрдө жүзүнө карадым. Чечимимди көрүп, акчаны алды да, экинчи колу менен чөнтөгүнөн кайтарым берүүгө тыйын чыгара баштады.","— Жок, кереги жок, кайтарымы өзүңдө калсын, — дедим.","— Эже, бул өтө көп, болбойт, — деп шашкалактап акчаларды бөлө баштады. Айрымдары жерге түшүп кетти.","— Эч нерсе эмес, башың аман болсун, менден болсун, — дедим жылмайып.","Бала уялып, музду эриткен баягы күлкүсү менен: — Рахмат, эже, Кудай сизден ыраазы болсун, — деди.","«Сага да рахмат! Сага да рахмат, жарды өлкөмдүн жүрөгү кенен, көзү ток баласы!» — дедим ичимен да, кайра ордума барып отурдум. Сыртта муздак суук ошол баланын чакан, сүйкүмдүү шаарын каптап турган. Ал шаарда али да аруулугун жоготпогон, адамдарга болгон ишеними бүлүнбөгөн, күлкүсү менен кышты жазга айланткан, бир нерсе жасап акча таап, үй-бүлөсүнө жардам берүүгө умтулган балдар бар эле.","Жолго чыктык. Түндүн караңгылыгында шаар да, жоолук саткан бала да артта калды. Жүрөгүм ооруп, бул суукта үй-жайынан ажыраган адамдарды ойлодум. Ичимде ар түрдүү сезимдер толкуп, алкымым түйүнүп, көз жашымды араң токтотуп турдум.","Автобусубуз болсо аппак кар жамынган тоолордун арасынан ийри-буйру жол менен сапарын улантты.","Сабак: Кээде эң чоң жоомарттыкты эң жарды адам көрсөтөт. Баланын аруу жүрөгү материалдык жокчулукту байлыкка айландырат.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"organization-without-an-action-plan","image":"wisdom-stories/Bakhtiyar%20Sirajov/illustrations/organization-without-an-action-plan.webp","title":"Иш-аракет планы жок уюм","paragraphs":["Иш-аракет планы жок уюм көздөгөн порту белгилүү болгону менен, деңиз картасы, жүрүү багыты жана экипаж мүчөлөрүнүн милдеттери аныкталбаган кемеге окшош. Мындай кеме кээде жолу болуп, капитаны жөндөмдүү же аба ырайы ыңгайлуу болгондуктан портко жетиши мүмкүн. Бирок бул системалуу башкаруунун эмес, кокустуктун натыйжасы болот. Туруктуу ийгилик болсо кокустук менен эмес, туура пландалып, тартип менен аткарылган иштин аркасында келет.","Иш-аракет планы жок уюм убакыт өткөн сайын мүчөлөрүн да жоготот. Анткени адамдарды уюмда кармап турган нерсе идеялар гана эмес, ошол идеялардын ишке ашканын көрүүгө болгон үмүт. Үмүт өчкөндө адамдар алыстайт, адамдар кеткенде уюм акырындап алсырап, ишин токтотот.","Сабак: Максат кайда барарыңды, план болсо ал жакка кантип жетериңди көрсөтөт. Плансыз уюмдун ийгилиги кокустукка байланыштуу; туруктуу ийгилик ойлонулган, ырааттуу ишти талап кылат.","Бахтияр Сиражов"],"hasAudio":false,"hasImage":true},{"stem":"credit-ledger","title":"Карыз дептери","paragraphs":["Жөнөкөй кийинген бейтааныш киши конуштагы дүкөнгө кирет. Сатуучуну, анан прилавканы бир сыйра карап чыгып, мындай дейт:","— Байке, сенден карызга нан, чай, жумуртка сурасам, бересиңби?","— Үч айдан бери карызга нан алып жүргөн бирөө бар. Чынын айтсам, карызын төлөйт деп деле ишенбейм. Бирок эмне кылайын, үч жетимди багып жатат, балдарын ач калтырбайлы да. Кудай улук, биздин да ырыскыбызды жеткирет. Сага берген нанымдын да акысын сурабайм. Ала бер, адал болсун. — Бейтааныш кишинин жүзүнө жылмаюу тарап, ичинен: «Издегенимди таптым окшойт», — деп ойлойт.","— Сенин тиги карыз дептериңде канча карыз бар?","Сатуучу бир аз таң калып, бир аз кыжырдана сурайт:","— Аны эмне кыласың?","Келген киши аны тынчтандыруу үчүн токтоо үн менен сөзүн улантат:","— Байке, суранам, ачууланба. Мен бул жерге келип, сенин кыжырыңды келтирип, убактыңды алардай бош жүргөн адам эмесмин. Ошол дептериңди сатып алам. Суранам, ичиндеги карыздардын баарын азыр эле эсептеп айт.","Сатуучу бир маңдайындагы кишиге, бир толуп калган дептерге карайт. Тигинин айтканынан кайтпай турганын түшүнүп, каршы болбойт; дептерге жазылган карыздардын баарын кошуп, чыккан сумманы айтат. Бейтааныш киши костюмунун төш чөнтөгүнөн бир таңгак акча чыгарып, сатуучунун алдына коёт да, мындай дейт:","— Байке, Кудай сенден ыраазы болсун. Сен бул элге ушунчалык ишенип, Кудайды ойлоп, жетимди ач калтырбай жүрсөң, демек, жакшы адамсың. Мен баарынын карызын төлөдүм. Бул менин ушул элге Рамазандагы белегим болсун. Эми дептерди мага бер. Мен аны алып барып көмөм жана Кыямат күнү ошол тизме мага жардам берет деп ишенем. — Киши дептерди алып, дүкөндөн чыгып кетет.","Дүкөнчү алдындагы акчаны санап, кассага салып жатып да эмне болгонун толук түшүнө албай турду. Катып калгандай эле болду. Дүкөндүн кичинекей терезесинен сыртты карады. Бейтааныш киши көрүнбөйт. Ооз ачарга аз калгандыктан, элдин баары үйүнө шашып бараткан. Ошол маалда күйөөсү кургак учуктан каза болгон Сүрейянын жети жашар кызы эшиктин алдына келип, уяла мындай деди:","— Ахмед байке, апам ооз ачарга бир нан, үч жумуртка берсин деди. Кийинки айда таякем бизге келгенде акчасын төлөйбүз. — Кыздын сөзүн уккан дүкөнчү уйкудан ойгонгондой болду. Адаттагыдай эле дептерин чыгармак болуп, колун тезгенин алдына сунду. Бир саамга токтоп, жылмайды да:","— Кел, кызым, жумуртка да ал, нан да, май да ал. Апаңа айт, тиги таяке келип да кетти... — деди.","Сабак: Үнсүз жасалган жакшылык — эң бийик жакшылык. Бирөөнү карыздан куткарып, жетимдин курсагын тойгузган адамдын көңүлү бай.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"his-hand-is-at-work","title":"Колу иште","paragraphs":["Бир киши он жумуртканы он капыкка сатып алып, тогуз капыкка сатчу экен. Тааныштары мындай таң калыштуу сооданын максатын сураганда, ал мындай деп жооп берет:","— Зыян тартып жатканыма карабагыла; соода кылып жүргөнүмдү көрүп, баары мени соодагер деп эсептейт, колум иште экенин көрүшөт.","Сабак: Элге иштеп жаткандай көрүнүү башка, иштен майнап чыгаруу башка. Көрүнүш үчүн гана маанисиз иш кылуу зыян алып келет.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"do-you-have-spending-money","title":"Чыгымыңызга акчаңыз барбы?","paragraphs":["Ата-энеңиздин көзү тирүүсүндө кадырын билиңиз. «Чыгымыңызга акчаңыз барбы?» деп суроо менен чектелбеңиз. Колуңуздан келишинче муктажын бүтүрүп, камын көрүңүз. Алардын ордун эч ким баса албайт.","Сабак: Ата-энеңдин кадырын көзү тирүүсүндө бил, муктаждыгын сөз менен эмес, иш менен бүтүр. Алардын ордун эч ким да, эч нерсе да баса албайт.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"weight-of-the-oil","title":"Майдын салмагы","paragraphs":["Бир наабайчы дыйкандан такай белгилүү өлчөмдө сары май сатып алчу экен. Бир күнү дыйкандан алган майдын салмагы күн өткөн сайын азайып баратканын байкайт. Дыйканды алдап жатат деп айыптап, казыга даттанат.","Дыйкан казыга мындай дейт: «Менин такыр таразам жок. Сатар майды бир алаканыма, экинчи алаканыма күн сайын ушул наабайчыдан алган бир килограммдык нанды коюп өлчөйм. Майды ошол нанга теңеп тартам».","Сабак: Бирөөгө кандай өлчөм колдонсоң, өзүңө да ошондой өлчөм кайтып келет. Кантип нан берсең, ошондой май аласың.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"why-am-i-poor","title":"Мен эмнеге кедеймин?","paragraphs":["Бир күнү бир кедей адам Буддага жолугуп, андан сурайт:","— Будда, мен эмнеге кедеймин?","— Анткени сен колуңда бар нерседен эч кимге эч нерсе бербейсиң.","— Мен аны кантип кылам? Башкаларга берер эч нерсем жок да!","— Сенде бөлүшө ала турган беш байлык бар, бирок сен аларды бөлүшпөйсүң.","— Суранам, ошол беш байлыкты мага түшүндүрүп бериңизчи.","— Макул.","1. Жүзүң менен башкаларга жылмаюу тартуулай алмаксың, бирок андай кылбайсың.","2. Көзүң менен башкаларга мээрим жана сүйүү төгүп карай алмаксың, бирок андай кылбайсың.","3. Тилиң менен башкаларга жакшы сөздөрдү айта алмаксың, бирок андай кылбайсың.","4. Жүрөгүң менен башкаларга бакыт каалай алмаксың, бирок андай кылбайсың.","5. Колуң менен башкаларга жакшылык кыла алмаксың, бирок андай кылбайсың.","Сабак: Берүүгө дайым бир нерсең бар: жылмаюу, жакшы сөз, мээримдүү кароо, жардам берген кол. Адам канча бөлүшсө, ошончо бай.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"mercedes","title":"Мерседес","paragraphs":["Мерседес — анын негиздөөчүсүнүн фамилиясы да, мурдатан белгилүү бир автомобиль компаниясынын аты да эмес эле. Бул унааларга ашык болгон бир атанын кызынын аты болчу.","Атасы кызынын аты ага ийгилик алып келет деп ишенген.","Ошондой да болду…","Ал «Мерседес» деп атаган автомобиль катышкан жарыштарда удаа-удаа жеңишке жетти.","Ушул ийгиликтердин аркасында 1902-жылдан бүгүнкү күнгө чейин сан жеткис Мерседес автомобилдери чыгарылды.","Атанын кызына болгон сүйүүсү Мерседес деген атты дүйнөдөгү эң ири автомобиль өндүрүүчүлөрдүн биринин брендине айлантты.","Эки жолу бактысыз турмуш курган Мерседес айым Венада жашаган. Ал 1929-жылы отуз тогуз жашында рак оорусунан каза болуп, Венада жерге берилген.","Сабак: Сүйүү менен коюлган ат, сүйүү менен жасалган иш дүйнөнү өзгөртө алат. Атанын мээрими бир атты түбөлүккө калтырды.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"former-minister-at-the-seminar","title":"Мурдагы министр семинарда","paragraphs":["Мурдагы бир министрди семинарга чакырышат. Кезеги келгенде колуна желим стакан кармап, трибунага чыгып сөзүн баштайт. Бирок ою башка жакта экени көрүнүп турду. Бир маалда желим стаканды көтөрүп карап, терең үшкүрөт да, залга кайрылып мындай дейт:","— Билесиздерби, эмнени ойлоп жатам? Өткөн жылы ушул эле трибунада сөз сүйлөгөм. Бир гана айырмасы — анда министр болчумун. Бул жакка келерде мага бизнес-класстан билет алып беришкен, аэропортто лимузин менен коштоочу унаалар күтүп турган. Мени мейманканага жеткиришти. Кымбат бөлмөдө эс алдым, эртеси бул жерге ошол лимузин менен келдим. Атайын тосуп алуу уюштурулган эле. Сөз сүйлөй турган кезегимди күтүп жатканда мага кымбат фарфор чыныга куюлган кофе сунушташкан. Анан атайын бөлүнгөн орунга отургузушкан. Бирок бүгүн силердин алдыңарда министр катары сүйлөп жаткан жокмун. Кечээ бул жакка өз акчама сатып алган билет менен учуп келдим.","Аэропорттон мени эч ким тосуп алган жок. Мейманканага такси менен бардым, бөлмөмө чейин коштоп барган да киши болгон жок. Бүгүн эртең менен бул жерге келгенимде күбөлүгүмдү тизмеден текшерип, анан ичкери киргизишти. Залдан биринчи бош орунду таап отурдум. Кофе ичким келип, мага коридордогу кофе автоматын көрсөтүштү. Мен да чыгып, өзүңөр көрүп турган ушул желим стаканга кофе куюп алдым.","Семинардын катышуучулары күлүп калышкан эле. Мурдагы министр сөзүн мындай улады: «Демек, өткөн жылы кымбат чыныдагы кофе мага эмес, менин кызмат ордума сунушталган экен». Зал кол чабууга толду. Кол чабуу басылганда, ал сөзүн улантты:","— Үйрөнгөн ушул маанилүү сабагымды силер менен бөлүшкүм келет: бардык мактоо жана көрсөтүлгөн кызмат силердин наамыңарга, ролуңарга же кызмат ордуңарга гана арналат. Алардын бири да жеке өзүңөргө таандык эмес. Кызматта жүргөндө пайдаланган кымбат чынынын ордуна, кызматтан кеткенде силерге желим стакан — башкача айтканда, өзүңөр татыктуу болгон нерсе — берилет.","Сабак: Сага көрсөтүлгөн сый көбүнчө кызматыңа арналат, өзүңө эмес. Кызматың менен мактанба — ал кеткенде чыныгы баркың көрүнөт.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"baklava","title":"Пахлава","paragraphs":["Балалык жылдарымда үй-бүлөбүз жупуну турмушта жашачу. Бир күнү атам үйгө бир аз пахлава алып келип, кечинде аны чай менен жедик.","Эртеси майрам болчу. Апам мектепке алып барышым үчүн баштыгыма бир даана пахлава, бир аз зайтун жана бир тилим нан салып берди.","Класстагы балдардын алдында ар кандай тамак бар эле. Өзүм жактырбаган бир бала менин тамагымды көрүп күлдү:","— Бул пахлаваны чычкандарга деп алып келдиңби?","Баары күлгөндө уялып, ыйлаган бойдон үйгө чуркап бардым да апама кыйкырдым:","— Эмнеге мага бир эле пахлава салып бердиң? Класстагылардын тамагы толтура болчу, мени уят кылдың!","Апам муңайыңкы үн менен мындай деди:","— Пахлавадан мага тийген үлүш ошол бирөө эле, балам.","Ошондо жүрөгүм зырп этти. Апам өзүнө тийген жалгыз пахлаваны жебей, мага сактаптыр. Уялганымдан аны кучактоого да бетим барбады. Ошол күнкү кылыгым эсиме түшкөн сайын ичимден кечирим сурайм. Ал эми пахлаваны ошондон бери оозума ала албай калдым.","Сабак: Бирөөнүн жокчулугуна күлүү эң чоң күнөөлөрдүн бири. Эне өз үлүшүнөн, атүгүл акыркы тилиминен да баш тартарын унутпайлы.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"pay-rent-for-the-water","title":"Суу үчүн ижара акысын төлө","paragraphs":["Бир адам айылдык кишиден кудук сатып алат. Кудуктан суу тартып алгысы келгенде, сатуучу ага уруксат бербей: «Мен сага кудуктагы сууну эмес, кудуктун өзүн саткам», — дейт. Экөө талаша кетет. Бири тигини, экинчиси муну айтат — акыры казын алдына барууга аргасыз болушат.","Казы сатуучуга мындай дейт: «Суу сеники болсо, аны башка бирөөнүн кудугунда сактай албайсың! Же сууңду алып кет, же кудуктун ээсине сууңду ошол жерде сактаганың үчүн ижара акысын төлө».","Сабак: Акыны кыңыр жол менен ээлегиси келген өз тузагына түшөт. Адилет эки тараптын акысын таразага салат.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"hot-bread","title":"Ысык нан","paragraphs":["Жаңы бышкан ысык нандын жыты бүт көчөгө тараган эле.","Карыя нан бышыруучу жайга жакындады. Небересине ысык нан алып барышы керек эле. Бала бир нече күндөн бери жаңы нан сурап жүргөн.","Эл нан алуу үчүн кезекке турушуптур. Ал да кезекке турду.","Киши көп эмес экен, кезеги бат эле жетти.","Чөнтөгүнөн майда тыйын чыгарды. Акчасы көбүрөөк болгондо, эки нан алмак. Акчасын наабайчыга сунду. Бирок наабайчы карыядан акча албай, колуна бир баштык карматты.","— Алыңыз, ата, аш болсун.","Баштыктын ичинде үч нан бар эле.","— Уулум, мен бир эле нан алайын дегем.","— Үчөөнү тең алыңыз, ата, кийин да жейсиз.","Карыя наабайчыга акырын жакындап, кулагына шыбырады:","— Уулум, менин бир эле нанга жетчү акчам бар.","Наабайчы жылмайды:","— Ата, бул — бизден бир үлүш. Бүгүн жума; биз ар жумада үч ысык нан таратабыз. Аш болсун.","— Аллах ыраазы болсун, балам.","— Оомийин!","Нан бышыруучу жайдан жаңы эле узай бергенде, бирөө карыяга үн катты:","— Ата, ата!","Карыя бурулуп карады:","— Угуп жатам, уулум.","— Ата, бул апамдын зекети эле; кабыл алсаңыз, абдан кубанам.","Жигит карыянын чөнтөгүнө бир конверт салды.","— Аллах кабыл кылсын, уулум. Аллах апаңыздан ыраазы болсун.","Базардын жанынан өтүп бара жатканда, бир аял ага үн катты:","— Ата... Бир мүнөт токтой туруңузчу, суранам.","Карыя токтоп, үн чыккан жакты карады. Жаш аял ага эки толо баштык сунду:","— Атаке, бул Рамазанда жолдон өткөндөргө тамак берип жатабыз, сиз да кабыл алыңызчы. Суранам, бул баштыктарды алып, бизди кубантыңыз.","— Аллах кабыл кылсын, кызым.","— Оомийин, ата!","Карыя чарчап, араңдан зорго үйүнө жетти.","— Кош келиңиз, ата.","— Апаң кайда, кызым?","— Ашканада. Жумуртка бышырам деди, Орхан кайгананы абдан жакшы көрөт.","— Буларды алып, апаңа берчи, белим үзүлүп калды.","— Чоң ата, ысык нан алдыңызбы? — деп небереси үн катты.","— Ооба, көп нерсе алдым.","— Жашасын чоң атам!","— Ата, эртең менен акчаңыз жок эле го, атүгүл чайга да жетчү эмес.","— Аллах берди, кызым.","Аялы бөлмөгө кирди:","— Ой, абышка, мынча көп нерсе алгансың го?","— Булар — үлүш, кемпир.","Карыя болгон окуяларды бирден айтып берди.","Азан айтылды. Ооз ачарды кайгана менен башташты. Ысык нан өзгөчө жарашты. Баштыктарда май да, сыр да бар экен. Чай менен абдан даамдуу болду.","— Ооба, эң сонун болду, Аллахка шүгүр. Аллах кабыл кылсын. Халва да абдан даамдуу экен.","Небереси дасторкондон туруп:","— Бөлмөмө барып, дагы бир аз дуба кылайын, — дегенде чоң атасы таң калды:","— Уктаардан мурда кыласың, уулум, али эрте го.","— Кечээ да ушул маалда кылгам. Аллахтан ысык нан менен сыр сурагам. Карачы, бүгүн келди. Эми барып, сенин тишиңди жасатканга акча жиберсин деп дуба кылайын. Тиштериң бузулуп калган, бул тиштер менен араң чайнайсың.","Апасы жылмайды:","— Маркум атаң ушул күндөрдү көргөндө кана.","— Атам ансыз деле ар түнү түшүмө кирип, мунун баарын көрүп турат. Негизи, мага дуба кылууну да ошол айткан.","Карыянын эсине капысынан күрмөсү түштү. Илгичке барып, колун чөнтөгүнө салып, конвертти алды. Ичинде чоң суммадагы акча бар экен.","Көзүнө жаш толду.","— Эмне болду, абышка, көзүң эмнеге жашка толду?","— Неберебиздин жүрөгүнөн өткөн нерсенин баарын Эгем жөнөтүптүр, кемпир. Бул акчаны карачы — майрамга чейин экөөбүз тең тишибизди жасата алабыз. Эгеме шүгүр!","Сабак: Чын жүрөктөн чыккан баланын дубасы жана бир нече боорукер адамдын жакшылыгы бир үй-бүлөнүн кайгысына даба болот. Бөлүшө билген коомдо эч ким ач калбайт.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true}]},{"title":"Адилеттүүлүк жана коом","slug":"edalet-ve-cemiyyet","blurb":"Акыйкат, коом жана жалпы жоопкерчилик.","count":10,"stories":[{"stem":"humanity-rebuilds-in-peace","image":"wisdom-stories/Etibar%20Siracsoy/illustrations/es_humanity-rebuilds-in-peace_ky.webp","title":"Адамгерчилик","paragraphs":["Дүйнө кандай гана кереметтерге, назик сулуулукка бай… Ар бир гүлдө, желдин ар бир шыбырында, асмандын өңүндө бир сыр, бир акылмандык катылган. Бул сулуулук адамдын жан дүйнөсүнө үнсүз тапшырылган аманат сыяктуу. Тилекке каршы, адам кээде ошол жарашууну өз колу менен бузат: жалында жер эле эмес, үмүттөр, тагдырлар, эскерүүлөр да күйөт.","Согуш жерди гана эмес, адамдын ичиндеги жарыкты да жаралайт. Ар бир кыйылган өмүр менен дүйнөнүн бир бөлүгү үнсүз калат. Адамдын бул дүйнөгө келүүдөгү милдети болсо кыйратуу эмес, коргоо, жаратуу жана жашоону улантуу эмеспи.","Балким, эң чоң суроо ушулдур: адам өзүнүн күчүн жок кылуудан эмес, өмүрдү сактоодон качан табат? Жер жүзүндө жымжырттыктын ордуна тынчтыктын үнү качан жаңырар экен? Ошондо, балким, дүйнө сулуу гана болбостон, баркы билинген жайга да айланар.","Сабак: Адамгерчилик өмүрдү сактоо, тынчтыкка жана жакшылыкка кызмат кылуу менен бийиктейт. Күчүбүздү жашоону улантууга жумшаган сайын дүйнө баарыбыз үчүн көркүнө чыгат.","Этибар Сиражсой"],"hasAudio":false,"hasImage":true},{"stem":"why-injustice-when-there-is-justice","title":"Адилеттик барда адилетсиздиктин кереги не","paragraphs":["Ажы Бекташ Вели:","Сүйүү барда жек көрүүнүн кереги не,","Тынчтык барда согуштун кереги не,","Бир туугандык барда тирешүүнүн кереги не,","Достук барда душмандыктын кереги не,","Сабыр барда сабырсыздыктын кереги не,","Эркиндик барда туткундуктун кереги не,","Адилеттик барда адилетсиздиктин кереги не?","Сабак: Сүйүүгө, тынчтыкка, бир туугандыкка жана адилеттикке жол ачык болсо, жек көрүүгө, чырга жана адилетсиздикке бурулуу адамдын өз тандоосу. Жоопкерчилик ошол адамдын өзүндө.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"sharing-justice","title":"Адилеттикти бөлүшүү","paragraphs":["Же эч ким ыйлабасын,","же дайыма күлүп жүргөндөр да күлбөсүн;","же акча деген илдет эч кимде болбосун,","же акчалуулар бөлүшкөндү үйрөнсүн;","же эч ким сүйөрүн айтпасын,","же чыныгы сүйүүнүн эмне экенин түшүндүрүп беришсин;","же бул майрамдар такыр болбосун,","же майрамда эт жебей калган жан болбосун.","Сабак: Кубанычты, нанды жана сүйүүнү бөлүшүү — адамгерчилик. Бир тарап күлүп, экинчи тарап ыйлап турса, ал жерде адилеттик жок.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"skins-of-the-lambs","title":"Козулардын териси","paragraphs":["«Козулардын терисин сыйрыгандан көрө, кочкорлордун жүнүн кырккан жакшы».","Бул сөздү Осмон доорунда Дамаск аймагынын валиси болгон Азмзаде Эсед-паша менен байланыштырышат. Окуясы мындай:","Бир күнү Эсед-пашанын казынасы бошоп, өзү оор абалда калат. Кеңешчилери казынаны толтуруш үчүн Дамасктагы токуучуларга кошумча салык салууну сунушташат. Эсед-паша аларды угуп: «Мындай салык салсак, канча киреше алабыз?» — деп сурайт.","— Элүү-алтымыш кап алтын түшөт, — дешет алар.","Эсед-паша каршы болот: «Бул адамдар ансыз да араң жан багышат. Салыкты кантип төлөшөт?» Кеңешчилери болсо: «Үйлөрүндөгү алтынын, асыл таштарын сатышат, паша», — деп аны көндүрүүгө аракет кылышат.","Эсед-паша: «Мен бул сумманы жакшыраак жол менен табам», — дейт.","Кеңешчилер унчукпай калышат.","Эртеси паша муфтийге чакыруу жөнөтүп, түнкүсүн жашыруун жолугушууну сунуштайт. Түн ичинде муфтий пашанын алдына келет. Паша мындай дейт:","— Муфтий мырза! Биз алган маалымат боюнча, жеке жашооңузда шариятка каршы иш кылып, үйүңүздө жашыруун арак ичет экенсиз. Бул жөнүндө Стамбулга билдирүүгө тийишмин. Бирок адегенде өзүңүзгө эскертип коёюн дедим.","Муну уккан муфтий пашага жалына баштайт. Стамбулга билдирбеши үчүн миң меджидие сунуштайт. Паша макул болбойт. Муфтий эки эсе көп сунуштайт. Паша дагы эле кабыл албайт. Акыры алты миң меджидиеге макулдашышат.","Эртеси Эсед-паша казыны чакырып: «Казы мырза, ишенимдүү булактардан сиз пара алып, кызматыңызды жеке пайдаңызга колдонуп жүргөнүңүздү билдик», — дейт.","Бул жолу казы пашага жалына баштайт. Ал да муфтий сыяктуу Эсед-паша менен соодалашат: «Оо, мырзам, мени кызматтан кетирбеңиз, болбосо эл алдында шерменде болом». Казы менен да алты миң меджидиеге макулдашышат.","Андан кийин Эсед-паша казыначыны, коопсуздук башчысын, соодагерлерди жана байларды бирден жолугушууга чакырат.","Бул иштин аягында Эсед-паша туптуура эки жүз кап меджидие алтынын чогултат. Анан кеңешчилерин чакырып: «Дамаск элине салык салганымды уктуңарбы?» — деп сурайт. Алар: «Жок, уккан жокпуз», — дешет.","Паша: «Салык салбасам да, элүү эмес, эки жүз кап меджидие алтынын чогулттум», — дейт.","— Муну кантип кылдыңыз, паша?","Паша жооп берет: «Козулардын терисин сыйрыгандан көрө, кочкорлордун жүнүн кырккан жакшы».","Сабак: Жардыны тоногондон көрө, бардардын адилетсиз пайдасын алуу адилеттүү. Жүктү жардыга эмес, күчтүүгө салуу керек.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"homeland-and-land","title":"Мекен жана топурак","paragraphs":["Топуракка суу кошсоң — ылай, кан кошсоң — Мекен болот.","Сабак: Топуракты Мекен кылган нерсе — ал үчүн төгүлгөн кан. Мекен жөн гана бир жер эмес, ал үчүн курмандыкка барган ыйык жерибиз.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"with-this-nation-the-world-can-be-conquered","title":"Мындай эл менен дүйнөнү багындырууга болот","paragraphs":["Бир күнү падыша калкы кандай жашап жатканын көрүш үчүн кийимин алмаштырып, шаарга чыгат. Товарлардын сапатын, бааларын жана дүкөн ээлеринин турмушун билүү үчүн шаар базарларын кыдыра баштайт.","Падыша көчө башындагы биринчи дүкөнгө кирет. Саламдашып:","— Мага жарым батман май, жарым батман бал жана бир аз сыр бериңизчи, — дейт.","Кардарын жайдары тосуп алган дүкөн ээси саламын сылык алып, жарым батман майды ыраазы боло тартып берет. Каршысындагы адам падыша экенин билбестен, майды берип жатып мындай дейт:","— Мырзам, бал менен сырды да бере алам. Бирок сиздин аркаңыз менен бүгүнкү соодамдын башын ачтым. Калганын али соода кыла элек маңдайкы кошунамдан алсаңыз, ыраазы болмокмун.","Муну укканда чын жүрөктөн сүйүнгөн падыша майдын акчасын төлөп, маңдайдагы дүкөнгө кирет. Ал жерден жарым батман бал менен сыр сурайт. Дүкөндүн улгайган ээси балды тартып бергенден кийин:","— Кудайга шүгүр, сиз бүгүнкү соодамдын башын ачтыңыз. Эми сырды тиги коңшу дүкөндөн алыңызчы. Анын соодасы али жүрө элек, — дейт.","Көргөндөрүнө абдан таасирленген падыша жанындагы дүкөнгө кирип, соодасын бүтүргөндөн кийин:","— Бул элде ушундай бийик адеп-ахлак барда бүт дүйнөнү багындырууга болот, — деп, бактылуу жана ыраазы маанайда базардан чыгып кетет.","Сабак: Чыныгы күч куралда эмес, элдин адалдыгында. Жер алуу эмес, жүрөк багындыруу — чыныгы жеңиш.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"bell-to-hang-on-the-cats-neck","title":"Мышыктын мойнуна тагыла турган коңгуроо","paragraphs":["Бир топ чычкан чогулуп, башына балээ болгон мышыктан кутулуунун жолун издей баштайт.","Ар кандай сунуш айтылат, бирок бири да кабыл алынбайт. Акыры жаш чычкан мышыктын мойнуна коңгуроо тагууну сунуштайт.","Сунуштун жөнү мындай эле: мойнуна коңгуроо тагылган мышык чычкандарга жакындаган сайын, алар анын үнүн угуп качып, жанын сактап калышмак. Бул сунушту чычкандардын баары чоң кубаныч жана кол чабуу менен кабыл алат.","Ошондо бурчта баарын үн катпай угуп отурган кары чычкан сөз алат:","— Бул абдан акылдуу сунуш, ишке ашса, ийгиликтүү болорунан шегим жок. Бирок бир суроо мени ойлондурат: айткылачы, коңгуроону мышыктын мойнуна ким тагат?","Сабак: Сунуш айтуу оңой, аны аткаруу кыйын. Ишке ашпаган эң жаркын ой да пайдасыз.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"bedouin-whose-camel-was-stolen","title":"Төөсү уурдалган бедуиндин окуясы","paragraphs":["Төөсү менен чөлдө бараткан бир бедуин бутуна араң турган, суусуздуктан эриндери кургаган адамга жолугат. Ал киши жалбарып, бедуинден ичкенге суу сурайт. Бедуин төөсүнөн түшүп, ага суу берет. Сууну ичкен киши капысынан бедуинди түртүп жиберип, төөгө минип кача жөнөйт.","Бедуин төөсүн кайтарып алууга алы жетпесин түшүнүп, уурунун артынан кыйкырат:","— Мейли, төөнү алып кете бер, сеники болсун. Бирок бул окуяны эч кимге айтпа.","Мындай өтүнүчтү күтпөгөн ууру бир саамга токтоп, артына кылчаят да, себебин сурайт.","— Эгер айтып берсең, бул окуя бардык жерге тарайт да, мындан ары эч ким жолуккан муктаж адамга жардам бербей калат, — деп жооп берет бедуин.","Сабак: Кээде адам башына түшкөндү жашырат, анткени башкалардын жакшылыкка болгон ишеними өчпөсүн. Бир жаман кабар миңдеген жакшылыктын эшигин жаап коюшу мүмкүн.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"just-verdict-of-the-frankfurt-judge","title":"Франкфурт судьясынын адилет өкүмү","paragraphs":["Бул окуя 1506-жылы Франкфурт шаарында катталган. Бир соодагер ичинде 800 гульден акчасы бар баштыгын жолдо жоготуп алат. Ошол жолдон кокустан өтүп бараткан жыгач уста баштыкты таап алат. Өтө динчил уста табылгасы тууралуу эч кимге айтпай, мынчалык көп акчанын жоголгонун байкабай калуу мүмкүн эмес, ээси сөзсүз издеп келет деп ойлойт.","Бир күнү жыгач уста сыйынуу үчүн чиркөөгө келет. Сыйынуу аяктагандан кийин кечил элге Франкфуртка келген бир соодагер 800 гульден акчасын жоготконун жана таап келген адамга 100 гульден сыйлык берерин жарыялайт.","Муну уккан жыгач уста тапкан акчасын алып чиркөөгө келет да, баштыкты кечилге тапшырат.","Соодагерге акчасы табылганын кабарлашат. Ал чиркөөгө келип, баштыгын алат, бирок убада кылган 100 гульденди жыгач устага бербей, болгону 5 гульден сунат. Жыгач уста андан убадасын аткарууну талап кылат. Ач көз соодагер болсо 100 гульденди бербеш үчүн баштыгында 800 эмес, 900 гульден болгонун, жыгач уста акчанын бир бөлүгүн алганын айтып чыгат. Кечил устаны коргоп, талашка аралашат: аны тааный турганын, абийирдүү адам экенин айтат. Талаш күчөйт. Акыры кечил соодагер менен жыгач устаны шаардык сотко алып барат.","Сот отуруму башталат. Судья соодагерден колун Инжилдин үстүнө коюп, 900 гульден жоготконуна ант берүүнү талап кылат. Соодагер эч тартынбай колун Инжилге коюп ант берет. Андан кийин судья жыгач устага 800 гульден тапканына ант берүүнү буюрат. Жыгач уста да колун Инжилге коюп ант берет.","Баары судьянын чечимин чыдамсыздык менен күтөт. Судья иш күндөй ачык экенин айтып, өкүмүн жарыялайт:","— Жыгач уста 800 гульден тааптыр, соодагер болсо 900 гульден жоготуптур. Демек, уста тапкан акча соодагердики эмес. Ээси табылбагандыктан, бул 800 гульден жыгач устага берилет. Ал эми соодагер жоготкон 900 гульденин издей берсин.","Сабак: Ач көздүк адамды өз тузагына салат. Акыны танган сараң акыры өз калпынын курмандыгы болот; адилет болсо акылуунун тарабында.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"woman-whose-house-was-robbed","title":"Үйү тонолгон аял","paragraphs":["Байыркы заманда бир шаарда жашаган кемпирдин үйүн ууру тоноп кетет. Кемпир кайгырып, падышага даттанганы барат. Падыша аны угуп, ачуулана: «Үйүңө ууру киргенин да сезбей калгыдай эмнеге мынчалык катуу уктадың?» — деп сурайт. Кемпир: «Падышам, биз сиз ойгоо жүрөт деп ойлоп, үйүбүздө бейкапар уктап жатканбыз», — деп жооп берет.","Сабак: Эл бийликке таянып, бейпил жашайт. Эл жетекчиси ойгоо экенин билсе, үйүндө бейкапар жатат.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true}]},{"title":"Карылык жана убакыт","slug":"yaslanma-ve-zaman","blurb":"Өмүрдүн мезгилдери жана убакыт өзгөрткөн нерселер.","count":4,"stories":[{"stem":"for-those-who-have-reached-sixty","title":"Алтымышка келгендерге","paragraphs":["Ушул күнгө чейин топтогон акчаңызды колдоно турган мезгил келди. Аны сарптап, ырахатын көрүңүз. Ал акчаны табыш үчүн канча мээнет кылганыңызды билбегендерге калтыруу үчүн өзүңүздү баарынан кур калтырбаңыз. Азыр — бейпилдиктин даамын сезүүгө эң ылайыктуу учур.","Балдарыңыз менен неберелериңиздин материалдык абалы үчүн кабатыр болбоңуз, акчаңызды өзүңүзгө коротконуңузга да өкүнбөңүз. Сиз аларды жылдар бою багып, колуңуздан келгендин баарын үйрөттүңүз. Билим, тамак-аш, башпаанек жана колдоо бердиңиз. Эми өз каражатын өздөрү табууга тийиш. Өз жолун өздөрү тапсын.","Эми ашыкча күч жумшабай, сергек жашоо өткөрүңүз. Орточо көнүгүү жасап, күн сайын сейилдеп, туура тамактанып, жакшы уктаңыз.","Бул куракта ооруу оңой, сак болуу кыйын. Ошондуктан ден соолукка өзгөчө көңүл буруу керек. Денеңиздин муктаждыгын эске алып, дарыгериңиз менен байланышта болуңуз. Өзүңүздү жакшы сезсеңиз да, текшерүүдөн өтүп туруңуз.","Майда-барат нерселер үчүн санааркабаңыз. Сиз өмүрүңүздө далай кыйынчылыкты жеңдиңиз. Жакшы да, жаман да эскерүүлөрүңүз болду. Өткөн күндөрдүн артка тартуусуна, келечектин коркутуусуна жол бербеңиз. Азыркы учурдун жакшылыгын сезиңиз. Майда кыйынчылыктар көп өтпөй унутулат.","Канча жашта экениңизге карабай, сүйүүңүздү дайыма жашатыңыз. Жубайыңызды, жашоону, үй-бүлөңүздү сүйүңүз жана эсиңизде болсун: акыл-эсиңиз менен мээримиңиз ордунда турганда, сиз кары эмессиз.","Өзүңүзгө кам көрүүнү унутпаңыз: чачтарачка барыңыз, тырмагыңызга кам көрүңүз, дерматологго жана тиш дарыгерине көрүнүп туруңуз, атыр менен крем колдонуңуз. Тыкан көрүнүш маанайыңызга да жакшы таасир этип, өзүңүздү ишенимдүүрөөк жана сергек сезесиз.","Курагыңызга ылайык мода багыттарын көз жаздымда калтырбаңыз, бирок өз стилиңизди сактаңыз. Китеп окуп, гезит карап, жаңылыктарды көрүп туруңуз. Интернетке кирип, адамдар эмне жөнүндө ойлонуп жатканын билиңиз. Электрондук почтаңыз активдүү экенине жана жок дегенде бир нече социалдык тармакты колдонуп жатканыңызга ынаныңыз.","Жаш муунду жана алардын ойлорун урматтаңыз. Алар сиз менен бир пикирде болбошу мүмкүн, бирок келечек — алардыкы, өз жашоосун каалаган нукка бурушат. Сындай бербей, кеңешиңизди айтып, кечээки акылмандык бүгүн да күчүн жоготпогонун эскертип турууга аракет кылыңыз.","«Биздин убакта...» деген сөздү эч качан колдонбоңуз. Азыр да сиздин убактыңыз. Жашап турганыңызда ушул замандын бир бөлүгү болуңуз.","Дайыма нааразы болуп, көңүл чөктүргөндөрдөн оолак болуп, жаныңызга жылуулук, көңүлүңүзгө кубат берген адамдар менен гана убакыт өткөрүңүз.","Кызыгууларыңыздан баш тартпаңыз. Саякаттап, сейилдеп, тамак жасап, китеп окуп, бийлей аласыз. Кааласаңыз, мышык же ит багыңыз.","Үйдөн чыгып туруңуз, көптөн бери көрбөгөн адамдар менен жолугуп, жаңы жерлерди көрүп, эски эскерүүлөрдү жаңыртыңыз. Эң негизгиси — өзүңүздү үйгө камап албаңыз. Музейлерге барып, сейил бакта басыңыз.","Дайыма сылык болууга, зарыл болбосо даттанбай жана сындабай жүрүүгө аракет кылыңыз. Кимдир бирөө көңүлүңүздү оорутса, аны кечириңиз. Өзүңүз көңүлүн ооруткан адамдардан кечирим сураңыз.","Азап-кайгыңызды өзүңүз менен кошо көтөрүп жүрбөңүз. Ал сизди гана кыйнайт. Кимдин туура экени маанилүү эмес. «Кек сактоо — өзүң ууланып алып, башка бирөөнүн өлүмүн күткөндөй», — деп айтылат. Ал ууну эч качан ичпеңиз. Кечириңиз, унутуңуз жана жашооңузду улантыңыз.","Күлүңүз, кубаныңыз. Өмүрүңүздүн ушул маалында бейпил жашоонун даамын татыңыз... Бактылуу болуңуз!","Сабак: Курмандыктын кезеги бир күнү бүтөт; өмүрүңүздүн күзүндө өзүңүзгө да жашоого укук бериңиз. Бактылуу адам айланасына да бакыт таратат.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"what-changed-after-sixty","title":"Алтымыштан кийин эмне өзгөрдү","paragraphs":["60тан ашып, 70ке жакындаган досторумдун биринен өзүндө кандай өзгөрүү байкаганын сурадым. Ал мындай жооп берди:","Карыларга «бул окуяны мурда айткансың» дебей калдым. Анткени ал сөздөр аларга жакшы эскерүүлөрүн жандандырып, сонун ирмемдерди кайра жашоого жардам берет.","Адамдар жаңылганда да оңдой бербөөнү үйрөндүм. Баарын кемчиликсиз кылуу менин милдетим эмес. Жан тынчтыгы кемчиликсиздиктен маанилүү.","Мактоону аябайм. Анткени бул маңдайымдагы адамга гана эмес, өз жан дүйнөмө да жагат.","Кийимимдеги бырышты же бир такты көйгөй кылбоону үйрөндүм. Анткени адамдын баркы сырткы көрүнүшүнөн эмес, ички дүйнөсүнөн билинет.","Менин дүйнөмө жат адамдардан алыс жүрүүнү үйрөндүм. Анткени алар жакшы мамиле түзүп, аны сактай алышпайт; мен болсо муну да үйрөндүм.","Сезимдеримден уялбоону үйрөндүм. Анткени мени адам кылган — ошол сезимдерим.","Мамилени бузгандан көрө, сыймыгымды четке коюуну үйрөндүм. Орунсуз сыймык адамды жалгыз калтырат, жакшы мамиле болсо жалгыздыктан сактайт.","Мени бактылуу кыла турган нерселерди жасоону үйрөндүм. Анткени өз бактым үчүн өзүм жооп берем.","Сурашпаса жардам бербөөнү үйрөндүм. Анткени жардамга муктаж адам ал жардамдын дал менден келишин каалабашы мүмкүн.","Ден соолугум, коңшуларым, туугандарым же пенсияда жүргөнүм тууралуу даттанбоону үйрөндүм! Анткени бардык кыйынчылыкка карабай жашап жатканыма жана жакындарым жанымда экенине шүгүр кылышым керек.","Жаштарга «мен сенин жашыңда...» деген сөздөрдү айтпай калдым; «сага эң жакшы жылдарымды бердим...» дегенди болсо таптакыр колдонбойм. Анткени ар бир замандын өз шарттары бар, өткөндүн өлчөмүн азыркы учурга таңуулоо туура эмес.","Бир кезде жаш, күчтүү жана кубанычтуу болгонун унутпай, жубайыма көбүрөөк көңүл бура баштадым — азыр ал бырыш баскан, алсыз, кайгылуу карыя болсо да. Анткени ушул учурда мага чындап муктаж болгон жалгыз адам, балким, ошол.","Баарына өзүмдү күнөөлөй бербөөнү үйрөндүм. Анткени жашоодо өзүм үчүн да, балдарым үчүн да колуман келгендин баарын жасадым.","Акыры, Эгемден өзгөртө ала турган нерселер үчүн күч, өзгөртө албай тургандарым үчүн сабыр, ал экөөнү айырмалай билүү үчүн акылмандык суроону үйрөндүм. Анткени адам катары баарына кудуретим жетпейт.","Сабак: Жаш курак адамга эң чоң акылмандыкты үйрөтөт. Тынчтык кемчиликсиздиктен, түшүнүү болсо туура чыгуудан жогору.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"aging","title":"Жашка толуу","paragraphs":["Жашка толуу тоого чыкканга окшош: жогорулаган сайын чарчооң күчөп, демиң кысылат, бирок дүйнөгө болгон көз карашың кеңейет.","Сабак: Жаш өткөн сайын адамдын күчү кемигени менен, көргөн-билгени көбөйүп, жашоого болгон көз карашы кеңейет.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"cherish-today-with-loved-ones","image":"wisdom-stories/Etibar%20Siracsoy/illustrations/es_cherish-today-with-loved-ones_ky.webp","title":"Убакыт — үнсүз аккан өмүр","paragraphs":["Убакыт — таң калыштуу керемет… Аны көрө албайсың, кармап кала албайсың, кайра кайтара да албайсың. Ал билинбей өтө берет: сааттын жебеси жылганда, күндөр алмашканда, чачка ак түшкөндө, балдар чоңойгондо, эскерүүлөр алыстаганда…","Адам көбүнчө убакыттын баркын аны жоготкондон кийин гана түшүнөт. Кечээ эле кадимкидей көрүнгөн бир күн жылдар өткөн соң эң кымбат эскерүүгө айланат. Бир кезде анча маани бербеген маек, бир караш, бир күлкү, сүйүктүү адамың менен өткөргөн жөнөкөй кеч кийин өмүрүңдүн эң сонун көз ирмемдеринин бири болуп калышы мүмкүн.","Убакыт эч кимди күтпөйт. Ал байлыкка да, атак-даңкка да, адамдын каалоосуна да баш ийбейт. Бул — баарына бирдей өлчөмдө берилген, бирок ар ким ар башка баалаган эң чоң байлык. Чынында, адамдын өмүрү жылдар менен эмес, маңыздуу өткөн көз ирмемдер менен өлчөнөт.","Кээде өмүр али алдыда, убактыбыз дагы көп деп ойлойбуз. Эртең жасайбыз, эмки жумада барабыз, бир күнү сүйлөшөбүз, кийин жолугушабыз… Бирок ошол «кийин» дайыма эле келе бербейт.","Убакыт бизден көп нерсени алып кетет: жаштыгыбызды, айрым адамдарды, кээ бир кыялдарыбызды, мүмкүнчүлүктөрүбүздү… Анын ордуна эскерүүлөрдү, тажрыйбаны жана жашоонун чыныгы маңызын түшүнүүгө мүмкүнчүлүк берет.","Ошондуктан убакытты өткөн жылдар менен гана өлчөбөйлү. Аны канча жашаганыбызга эмес, кандай жашаганыбызга карап баалайлы. Жакындарыбызга сүйүүбүздү бүгүн билдирели. Досторубуз менен жолугушууну кийинкиге калтырбайлы. Кооз көрүнүштөргө суктаналы, күндүн чыгышын карайлы, деңиздин үнүнө кулак төшөйлү, жүрөгүбүздү кубанткан көз ирмемдерди жашайлы.","Анткени убакыт өтүп жатат…","Сабак: Сүйүүбүздү билдирүүнү, жакындарыбызга убакыт бөлүүнү кийинкиге калтырбайлы. Өткөн көз ирмем кайтып келбейт. Бүгүнкү күндүн баркын бүгүн билишибиз керек.","Этибар Сиражсой"],"hasAudio":false,"hasImage":true}]},{"title":"Тамсилдер жана жомоктор","slug":"temsiller-ve-meseller","blurb":"Жаныбарлар жана образдар аркылуу үйрөткөн жомоктор.","count":8,"stories":[{"stem":"lions-footprint","title":"Арстандын изи","paragraphs":["Коркок, ошол эле учурда мактанчаак бир мергенчи арстандын артынан түшүп, токойго жетет да, алдынан чыккан отунчудан сурайт:","— Байке, бул жактан арстанды же анын изин көрдүңүзбү?","Отунчу:","— Арстандын өзүн көрдүм. Кааласаң, сени ошол турган жерине алып барайын.","Өңү кубарып кеткен мергенчи:","— Жок, жаным, рахмат. Мен чынында арстандын өзүн эмес, изин гана издеп жүргөм.","Сабак: Мактанган сөзгө эмес, сын сааттагы ишке кара. Арстанды алыстан издегендер көп, бирок аны менен бетме-бет келгенде көбү артка чегинет.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"hunters-description","title":"Мергенчини даңазалоо","paragraphs":["Арстан жазганды үйрөнмөйүнчө, ар бир окуя мергенчини даңазалай берет.","Африка макалы","Сабак: Окуяны айткан адам көбүнчө өзүн баатыр кылып көрсөтөт. Өз чындыгыңды өзүң айтпасаң, башкалар сени өздөрү билгендей таанытышат.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"elephant-and-the-rope","title":"Пил жана аркан","paragraphs":["Бир саякатчы пилдер кармалган жайдын жанынан өтүп баратып, капысынан токтойт: алп жаныбарлардын алдыңкы буту кыска эле аркан менен казыкка байланып турганын көрүп, аябай таң калат. Чынжыр да, капас да жок. Мындай шартта пилдер арканды каалаган учурда үзүп, оңой эле качып кетчүдөй көрүнгөнү менен, алар качууга такыр аракет кылышчу эмес. Киши жакын жердеги үйрөтүүчүгө барып, бул кереметтүү жаныбарлар эмне үчүн баш ийип, ордунда турганын жана эмнеге качууга аракет кылбай турганын сурайт.","Үйрөтүүчү мындай түшүндүрөт:","— Булар кичинекей кезинде ушул арканды үзүүгө алы жетчү эмес. Канча аракет кылышса да бошоно алышпагандыктан, кийин чоңойгондо да «арканды үзө албайбыз» деген ойдон чыга албай калышат.","Муну уккан киши айран таң калат. Элестетип көрүңүз: бул жаныбарлар каалаган учурда бошоно алышмак, бирок муну мүмкүн эмес деп ишенип, турган жерине байланып кала беришкен.","Сабак: Кээде бизди аркан эмес, мурдагы ийгиликсиздиктерден жаралган ишенбөөчүлүк тушап турат. «Эл эмне дейт?» деген коркунууну жеңмейинче эркин боло албайсың.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"ant-that-carries-water","title":"Суу ташыган кумурска","paragraphs":["Уламыш боюнча, Немруд (Ыйык Китепте аты аталган Шынар өкүмдары) өзүнүн зулумдугуна тоскоол деп эсептеген Ибрахим пайгамбарды отко ыргытып жазаламак болот. Ал аянттын ортосуна алоолонгон чоң от жагууну буюрат. Алоону көргөн жан-жаныбардын баары качууга шашат.","Ошол маалда бир кумурска оозуна бир тамчы суу алып, отту көздөй шашып баратат.","Аны көргөн башка бир кумурска сурайт:","— Мынчалык шашып кайда баратасың?","— Уккан жоксуңбу, Немруд Ибрахим пайгамбарды отко ыргытат экен? — деп суу ташыган кумурска тынчсыздануусун жашырбайт.","— Сен ал отту көрбөсөң керек. Ал эбегейсиз чоң, качкандан башка арга жок. Оозуңдагы бир тамчы суу менен ошону өчүрмөкчүсүңбү? — деп экинчи кумурска шылдыңдай сурайт.","Суу ташыган кумурска жооп берет:","— Өчүрө албасам да, жок дегенде ким тарапта экеним билинет.","Сабак: Баарын өзгөртүүгө күчүң жетпесе да, акыйкаттан тайба. Кыйынчылыкка кабылган жакыныңдын жанында болуунун өзү баалуу.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"turtles-wrong-calculation","title":"Таш баканын жаңылыш эсеби","paragraphs":["Таш бакадан сурашат:","— Жакынкы айылга канча убакытта жетесиң?","— Жамгырды, баткакты, шамалды, өйдө-төмөн жолду эсепке алсак, үч күндүк жол. Бирок мен алты күндө жетем... — деп жооп берет таш бака.","Алты күндөн кийин карашса, таш бака айылга али жетпептир. Издеп жүрүп, акыры аны жолдун ортосунан табышат да: — Эмне болду, үч күндүк жолду алты күндө да басып өтө албадыңбы? — деп таң кала сурашат.","Таш бака көңүлү чөгүп жооп берет: — Айтпа, достор. Жамгырды, баткакты, шамалды, өйдө-төмөн жолду эсептедим, бирок, тилекке каршы, жаман адамдарды эсепке алуу оюма келбептир. Качан ылдамыраак жүрө баштасам, кармап алып, мени чалкамдан оодарып коюшту.","Сабак: Жашоодогу ар бир кыйынчылыкты эсептесе болот, бирок жаман ниети бар адамдарды эсептей албайсың. Аллах сени алдыга жүрүүгө жол бербегендер менен эмес, колдогондор менен жолуктуруп койсун.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"fly-in-the-china-shop","title":"Фарфор дүкөнүндөгү чымын","paragraphs":["Бир чымын фарфор идиштер сатылган дүкөндү талкалагысы келсе да, ага күчү жетпейт. Бирок ал өгүздүн кулагына кирип кетсе, үркүп кеткен өгүз бүт дүкөндү талкалап салышы мүмкүн.","Бул чымын — ырым-жырымдын, жалгандын жана бир жактуу көз караштын белгиси. Өгүз болсо ойлонбой иш кылган наадан адамды билдирет.","Сабак: Кичинекей жалган наадандын кулагына жеткенде чоң кырсыкка алып келиши мүмкүн. Мунун алдын алуу үчүн билимдүү болуп, укканыңды таразалап, адеп-ахлак баалуулуктарына бекем туруу керек.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"two-donkeys","title":"Эки эшек","paragraphs":["Эки эшек жолдо баратып, даракта отурган маймылды көрүшөт. «Кел, бул маймылды шылдыңдайлы. Досуң барбы деп сурайбыз. “Бар” десе, “Сени менен кайсы келесоо достошот?” дейбиз; “жок” десе, “Сени менен кайсы келесоо дос болмок эле?” дейбиз», — дешет. Даракка жакындап: «Маймыл, сенин досуң барбы?» — деп сурашат. Маймыл жогору жактан аны шылдыңдагысы келген эшектерди карап:","— Кайда карабайын, баары эшек; ким менен достошом? — дейт.","Сабак: Бирөөнү шылдыңдап күлөм деп, өзүң күлкүгө калба. Кемсинткен сөз ээсине кайтып тийиши мүмкүн.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"donkeys-law","title":"Эшектин мыйзамы","paragraphs":["Бир күнү эшек токойдун падышасы болот. Бир нече күндөн кийин мыйзам чыгарат: баары кечки саат алтыда уктап, таңкы саат алтыда ойгонууга тийиш. Он эки саат бою токойдо толук тынчтык өкүм сүрүп, мыйзамды бузган жаныбар жазаланмак.","Ошентип, бир топ убакыт бою токойдо үн-сөз чыкпай калат.","Бир күнү короз таңкы саат беште ойгонуп, кыйкыра баштайт. Токойдо ызы-чуу түшөт. Дароо сот болуп, эшектин өкүмү менен короз өлүм жазасына тартылат. Ошол күндөн кийин падышадан корккон эч ким мыйзамга каршы чыкпайт.","Жылдар өтүп, эшек карып, алдан-күчтөн тайыйт. Токойдун бир бурчуна барып, өлүмүн күтүп калат. Арстан анын жанына келип, ал-жайын сурагандан кийин мындай дейт:","— Сен эми акыркы күндөрүңдү жашап жатасың. Билгибиз келет: кечки саат алтыда уктап, таңкы саат алтыда турууну буйруган мыйзамыңдын сыры эмнеде эле? Биз аны жокко чыгаруу үчүн нечен ирет көтөрүлгүбүз келди, бирок токойдогу тартип бузулуп кетпесин деп кармандык. «Бул мыйзамда биз түшүнбөгөн бир даанышмандык бар го», — деп ойлодук.","Эшек жылмайып жооп берет:","— Чынын айтсам, мен да көп жылдан бери ушуга таң калам: эшектик кылып чыгарган ушул мыйзамыма токойдун жапайы жаныбарлары эмнеге кой сыяктуу баш ийишти экен?","Сабак: Акылга сыйбаган мыйзамды кармап турган аны чыгаргандын күчү эмес, баш ийгендердин унчукпастыгы. Буйруктун артында дайыма акылмандык турбайт, кээде жөн гана эшектик турат. Суроодон тартынба: жоопсуз суроо эң эски сандыракты да мыйзамга айлантат.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true}]},{"title":"Тарых жана белгилүү инсандар","slug":"tarix-ve-taninmish-shexsiyyetler","blurb":"Тарыхтан жана белгилүү ысымдардан үлгү.","count":5,"stories":[{"stem":"albrecht-durer","title":"Альбрехт Дюрер","paragraphs":["Нюрнбергге жакын чакан айылда он балалуу үй-бүлө жашачу. Үй-бүлөсүн багуу үчүн атасы күнүнө он сегиз саат иштечү. Канчалаган кыйынчылыкка карабай, улуу уулдары Альбрехт менен Альберт атактуу сүрөтчү болууну кыялданышчу. Бирок атасынын экөөнү бирдей окутууга чамасы жетпесин билишчү.","Бир туугандар шамдын жарыгында көпкө кеңешип, акыры чүчүкулак таштамай болушту. Бирине Нюрнбергдеги академияда окуу насип этсе, экинчиси жакын жердеги кенде иштеп, анын окуусуна каражат таап бермек. Төрт жылдан кийин кезек алмашмак.","Чүчүкулак Альбрехтке түштү. Ал академияга жөнөдү, Альберт болсо кенде иштей баштады.","Төрт жыл бою бир туугандардын бири сүрөт өнөрү менен алектенип, экинчиси кендин тереңинде эмгектенди. Альбрехттин чыгармалары көп өтпөй чоң кызыгуу жаратты; атүгүл анын көптөгөн эмгектери устаттарынын чыгармаларынан да күчтүү экени айтылып жүрдү.","Окуусун аяктаганда Альбрехт жакшы киреше таап калган эле. Ал кубаныч менен үйүнө кайтып келип, бир тууганына мындай деди:","— Кымбаттуу бир тууганым, эми кезек сеники. Бар, кыялыңды ишке ашыр; бул жолу мен сага тирек болом.","Альберт колдорун ага сунуп, акырын үн менен жооп берди:","— Жок, бир тууганым, эми өтө кеч. Ушул төрт жылда кен менин колдорумду, ар бир манжамды жанчып бүттү. Мен мындан ары сүрөт тарта албайм.","Альбрехт бир тууганынын колдорун алаканына алып, көз жашына муунду.","Кылымдар өтсө да, Альбрехт Дюрердин (1471–1528) чыгармалары дүйнөдөгү кадыр-барктуу галереяларда көргөзүлүп келет. Анын бир тууганынын жан аябастыгы менен байланыштырылган атактуу сүрөтү «Дуба кылган колдор» деген ат менен белгилүү.","Сабак: Ар бир ийгиликтин артында көп учурда көзгө көрүнбөгөн бир жан аябастык турат. Аны көрө билүү жана баалоо — адамгерчиликтин эң сулуу белгилеринин бири.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"mihrimah-sultan-and-architect-sinan","title":"Михримах Султан жана архитектор Синан","paragraphs":["Султан Сулейман Канунинин кызы Михримах Султан он жети жашка чыкканда, аны алууга эки киши умтулганы айтылат. Алардын бири — Диярбакырдын бейлербеи Рүстем Паша, экинчиси — османдык архитектуранын улуу устаты архитектор Синан болгон. «Михримах» деген ысым фарс тилинен: «михр» — күн, «мах» — ай дегенди билдирет.","Султан Сулейман кызын Рүстем Пашага турмушка чыгарды. Ал кезде үйлөнүп калган жана элүү жашка жакындап калган архитектор Синандын тилеги орундалган жок. Уламышка ылайык, ал ошондой болсо да Михримах Султанды терең сүйүүнү улантты.","Сүйгөнүнө кошула албаган Синан сезимин жүрөгүндө сактап, анын назиктигин өнөрү аркылуу билдирүүгө аракет кылды.","Сарайдын буйругу менен архитектор Синан Үскүдарда Михримах Султан мечитин куруп, аны укмуштуудай архитектуралык эстеликке айландырды. Уламыштарда мечиттин назик силуэти этеги жерге төгүлгөн аялдын сымбатын элестетет деп айтылат.","Кийинчерээк Синан Стамбулдун эң бийик жерлеринин бири болгон Эдирнекапыда Михримах Султан үчүн экинчи мечит тургузду. Бул курулуш өлчөмү боюнча салыштырмалуу кичине болсо да, өзгөчө назик жана жарык көрүнүшү менен айырмаланат. Ичке мунарасы, күмбөздү курчаган көптөгөн терезелери жана кооз ички жасалгасы мечитке өзгөчө жеңилдик берет. Уламышка ылайык, айрым оюм-чийимдер менен кооздуктар Михримах Султандын узун чачын эске салгыдай кылып иштелген.","Ошентип Стамбулда бир сүйүүгө арналган деп айтылган эки укмуштуудай архитектуралык чыгарма жаралды.","Уламыштын эң таасирдүү учуру — Күн менен Айдын жолугушуусу. Айтылгандай, Стамбулда Эдирнекапыдагы да, Үскүдардагы да Михримах Султан мечиттерин көрүүгө боло турган бир чекит бар. Жазгы күн-түн теңелүү убагында ошол чекиттен караганда Эдирнекапыдагы мечиттин мунарасынын артында кыпкызыл Күн батып, ошол эле учурда Үскүдардагы мечиттин артынан Ай чыгат.","Михримах — Күн жана Ай…","Бул көрүнүш адамдарды таң калтырып, кыялын канаттандырат: бул архитектор Синандын так эсептелген архитектуралык ой жүгүртүүсүнүн натыйжасыбы, же кийинчерээк пайда болгон романтикалуу уламышпы?","Чындык кандай болбосун, бул окуя архитектор Синандын өнөрү менен Михримах Султандын ысымын бириктирген эң кооз Стамбул уламыштарынын бирине айланды.","Сабак: Сүйгөнгө жетүү ар кимге эле буюрбайт. Бирок жүрөктөгү сезим өнөргө айланса, адамдын өзүнөн да узак жашайт.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"architect-sinan-dies-in-a-house-without-water","title":"Стамбулга суу жеткирген архитектор Синан суусуз үйдө каза болду","paragraphs":["Султан Сулейман Канунинин тушунда калкы тездик менен көбөйгөн Стамбулда суу катуу тартыш эле. Бул түйшүктү чечүү улуу архитектор Кожа Синанга (1489–1588) жүктөлдү.","Бир күнү Султан Сулейман аны алдына чакырып, сурады:","— Башкы архитектор, эл бир атка жүктөлгөн сууга көп акча төлөп жатат. Стамбулду суу менен камсыз кылуунун жолу барбы?","Синан шаардын айланасын изилдөөгө уруксат сурады. Жардамчылары менен Чекмеджеден Бешикташка чейин кудуктарды, өрөөндөрдү жана агын сууларды текшерип, дамбалар менен суу түтүктөрүн кайсы жерге курууга болорун эсептеди.","Султандын алдына кайтып келгенде мындай деди:","— Стамбулга суу жеткирсе болот. Бирок ага эбегейсиз каражат керек: буга сан жеткис алтын кап керек болот.","Султан жооп берди:","— Сен болгону мунун мүмкүн экенин айт. Канча алтын талап кылынса, ошончосун берем.","Синан ишке киришип, шаардын ар кайсы аянтындагы кырк суу алуучу жайга чейин жеткен суу жолдорун курду. Суу ысырап болбосун деп, ал жерлерге чорголорду орноттурду.","Султан коомдук булактар элге таандык экенин билдирип, үйлөргө жашыруун суу түтүгүн тартууга тыюу салган жарлык чыгарды. Бирок Синандын эмгегин эске алып, анын үйүнө өзүнчө суу түтүгүн тарттырууга оозеки уруксат берди.","Жылдар өттү. Султан Сулейман да, Синандын эмгегин жакындан билгендер да дүйнөдөн кайтышты. Карыган архитектор бир күнү сарайга чакырылды. Диван мүчөлөрү анын үйүндө өзүнчө суу бар деген арызды иликтеп жатышкан.","Синан султан ага уруксат бергенин айтты. Бирок жазуу түрүндөгү жарлыкты сурашканда, ал мойнуна алды:","— Ошондо Аалам Падышасынан жарлык сурагандан уялгам. Жазуу түрүндөгү документим жок.","Узак талкуудан кийин диван аны мурда суу пайдаланганы үчүн жазалабоону, бирок өзүнчө суу түтүгүн кестирүүнү чечти.","Өмүрүнүн акыркы жылдарында Синан ооруп, төшөккө жатып калды. Эриндерин суулаш үчүн суу сураганда, үйдөгү крандан суу акпай калганы билинди. Улуу архитектор мындай деди:","— Биз кызматыбызды пайда үчүн эмес, Кудайдын ыраазылыгы үчүн кылдык. Сыйлыгын да акыреттен күтөбүз. Бул дүйнөдө үйүбүзгө суу берилбегени үчүн кайгырбайбыз.","Сабак: Дүнүйөгө, атак-даңкка, адамдардын берилгендигине ашыкча таянба. Чыныгы кызмат жеке пайданы көздөбөй, ак деп билгениң жолдо эмгектенүү.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"magnificent-lesson","title":"Улуу сабак","paragraphs":["Осмон падышасы II Мураддын уулу Фатих Султан Мехмед бала кезинде сабакта тынч отурбай, дайыма тентектик кылчу. Мугалими Акшемседдин ага эскертүү бергенде болсо:","— Сен мага эч нерсе дей албайсың. Мен падышанын уулумун! — деп жооп берчү.","Акшемседдин бул жагдайга абдан тынчсызданчу. Падышага даттануудан тартынганы менен, бир күнү кайратын жыйнап, II Мураддын алдына барат да болгон окуяны айтып берет.","Падыша бир аз ойлонуп, түзгөн планын мугалимдин кулагына шыбырайт. Акшемседдин мунун мүмкүн эместигин айтса да, II Мурад чечиминен кайтпайт:","— Бул иш сөзсүз болот.","Эртеси Фатих Султан Мехмед кайрадан сабакта тентектик кылып, мугалимдин эскертүүсүнө мурдагы сөздөрү менен жооп берип жаткан. Дал ошол учурда падыша эшикти ачып, класска кирет.","План боюнча аракет кылган Акшемседдин ачууланган түр көрсөтүп, падышага бурулат да, уруксатсыз класска киргени үчүн жемелейт. Атүгүл аны чаап жиберип, дароо сыртка чыгуусун талап кылат.","II Мурад башын жерге салып, кечирим сурайт да класстан чыгып кетет. Атасынын да мугалимдин алдында тартипке баш ийгенин көргөн ханзаада таң калганынан катып калат.","Бир аздан кийин эшик тыкылдайт. Бул жолу падыша уруксат сурап класска кирет да кайрадан кечирим өтүнөт.","План ишке ашкан эле. Ошол күндөн кийин Фатих Султан Мехмед сабакта эч качан тентектик кылган жок. II Мурад баласынын тарбиясы үчүн падышалык намысын да четке коё билген.","Сабак: Тарбияда жеке үлгү ар бир сөздөн күчтүү. Жоопкерчиликтүү ата-эне баласы туура жолду табышы үчүн кээде өз сыймыгынан да баш тарта алат.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true},{"stem":"three-essential-things-for-a-city","title":"Шаар үчүн зарыл үч нерсе","paragraphs":["Ар бир шаар үчүн зарыл үч нерсе бар: канализация, мончо жана китепкана. Анткени канализация шаардын, мончо дененин, китепкана болсо рухтун кирин тазалайт.","Фатих Султан Мехмет","Сабак: Шаардын жана дененин тазалыгы гана эмес, рухтун тазалыгы да керек. Китепкана — рухту тазалаган жай.","Аңгемелер ачык интернет булактарынан алынган, иллюстрациялар болсо ЖИ менен түзүлгөн."],"hasAudio":false,"hasImage":true}]}]};
